css:
/* Contour sign-in. Re-theme with --apa-split-paper, -ink, -accent and the three terrain tints. */
@property --apa-split-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.apa-split {
  --apa-split-paper: oklch(0.972 0.011 86);
  --apa-split-ink: oklch(0.24 0.025 52);
  --apa-split-accent: oklch(0.55 0.15 38);
  --apa-split-water: oklch(0.87 0.04 222);
  --apa-split-low: oklch(0.89 0.05 128);
  --apa-split-high: oklch(0.88 0.06 72);

  --apa-split-line: color-mix(in oklch, var(--apa-split-accent) 70%, var(--apa-split-ink));
  --apa-split-muted: color-mix(in oklch, var(--apa-split-ink) 64%, var(--apa-split-paper));
  --apa-split-faint: color-mix(in oklch, var(--apa-split-ink) 42%, var(--apa-split-paper));
  --apa-split-rule: color-mix(in oklch, var(--apa-split-ink) 12%, transparent);
  --apa-split-rule2: color-mix(in oklch, var(--apa-split-ink) 20%, transparent);
  --apa-split-field: color-mix(in oklch, var(--apa-split-paper) 55%, white);
  --apa-split-bad: oklch(0.55 0.19 27);
  --apa-split-ease: cubic-bezier(.22, .9, .24, 1);
  --apa-split-spring: linear(0, 0.08 4%, 0.32 9%, 0.74 17%, 0.97 24%, 1.06 30%, 1.07 36%, 1.04 44%, 1.01 55%, 0.995 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-split-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-split-paper);
  color: var(--apa-split-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apa-split-accent);
  outline: none;
}
:where(.apa-split) *, :where(.apa-split) *::before, :where(.apa-split) *::after { box-sizing: border-box; }
:where(.apa-split) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-split) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-split) :is(p, h1, figure, blockquote) { margin: 0; }
:where(.apa-split) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-split) :focus-visible { outline: 2px solid var(--apa-split-accent); outline-offset: 2px; }
:where(.apa-split) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 10%, transparent);
  box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 16%, transparent);
}
.apa-split [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-split__app {
  display: grid; height: 100%;
  grid-template: "art pane" minmax(0, 1fr) / minmax(0, 1.06fr) minmax(400px, 1fr);
}
.apa-split__art { grid-area: art; position: relative; overflow: hidden; margin: 10px 0 10px 10px; border-radius: 12px; background: var(--apa-split-low); box-shadow: inset 0 0 0 1px var(--apa-split-rule); }
.apa-split__pane { grid-area: pane; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }

/* ---------- art panel ---------- */
.apa-split__map {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block;
  transition: filter .7s var(--apa-split-ease), scale .9s var(--apa-split-ease);
}
.apa-split[data-peek] .apa-split__map { filter: blur(14px) saturate(.45) brightness(1.04); scale: 1.06; }
.apa-split__veil {
  position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 10px; pointer-events: none;
  color: var(--apa-split-ink); font-size: 13px; font-weight: 600; letter-spacing: .02em;
  opacity: 0; translate: 0 8px; transition: opacity .45s var(--apa-split-ease), translate .6s var(--apa-split-ease);
}
.apa-split__veil svg { width: 34px; height: 34px; stroke-width: 1.5; }
.apa-split[data-peek] .apa-split__veil { opacity: 1; translate: 0 0; transition-delay: .12s; }

.apa-split__plate {
  position: absolute; inset: 16px 16px auto; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  transition: opacity .4s;
}
.apa-split__brand {
  display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 13px 0 10px; border-radius: 999px;
  background: var(--apa-split-paper); box-shadow: 0 0 0 1px var(--apa-split-rule), 0 6px 18px -10px color-mix(in oklch, var(--apa-split-ink) 50%, transparent);
  font-weight: 760; font-size: 15px; letter-spacing: -.02em;
}
.apa-split__brand svg { width: 20px; height: 20px; color: var(--apa-split-accent); stroke-width: 1.9; }
.apa-split__plateno {
  padding: 6px 10px; border-radius: 7px; background: color-mix(in oklch, var(--apa-split-paper) 88%, transparent);
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; color: var(--apa-split-muted);
  white-space: nowrap;
}
.apa-split__plateno i { font-style: normal; opacity: .45; margin: 0 2px; }

.apa-split__quote {
  position: absolute; left: 16px; right: 16px; bottom: 62px; max-width: 430px;
  padding: 18px 20px 16px; border-radius: 12px; background: var(--apa-split-paper);
  box-shadow: 0 0 0 1px var(--apa-split-rule), 0 18px 40px -24px color-mix(in oklch, var(--apa-split-ink) 55%, transparent);
  transition: opacity .4s, translate .5s var(--apa-split-ease);
}
.apa-split__quote blockquote {
  font: italic 400 clamp(15px, 0.6rem + 1.05cqi, 18.5px)/1.42 ui-serif, "New York", Georgia, serif; letter-spacing: -.005em; text-wrap: pretty;
}
.apa-split__quote blockquote::before { content: "“"; margin-left: -.42em; color: var(--apa-split-accent); }
.apa-split__quote blockquote::after { content: "”"; color: var(--apa-split-accent); }
.apa-split__quote figcaption { display: flex; align-items: center; gap: 10px; margin-top: 12px; font-size: 12.5px; }
.apa-split__quote figcaption b { display: block; font-weight: 650; }
.apa-split__quote figcaption small { display: block; color: var(--apa-split-muted); font-size: 12px; }
.apa-split__av {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; flex: none;
  background: color-mix(in oklch, var(--apa-split-accent) 18%, var(--apa-split-paper)); color: var(--apa-split-accent);
  font-size: 11px; font-weight: 750; letter-spacing: .02em;
}
.apa-split[data-peek] :is(.apa-split__quote, .apa-split__plate, .apa-split__legend) { opacity: 0; }
.apa-split[data-peek] .apa-split__quote { translate: 0 10px; }

.apa-split__legend {
  position: absolute; left: 16px; right: 16px; bottom: 14px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  font: 500 11px/1.2 ui-monospace, Menlo, monospace; color: var(--apa-split-ink); transition: opacity .4s;
}
.apa-split__legend > * { padding: 6px 9px; border-radius: 7px; background: color-mix(in oklch, var(--apa-split-paper) 90%, transparent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apa-split__seed { color: var(--apa-split-muted); }
.apa-split__seed b { color: var(--apa-split-ink); font-weight: 600; }
.apa-split__seed.is-new b { animation: apa-split-flash .9s var(--apa-split-ease); }
.apa-split__readout { font-variant-numeric: tabular-nums; flex: none; }

.apa-split__cross { position: absolute; inset: 0; pointer-events: none; opacity: 0; transition: opacity .25s; }
.apa-split__art:hover .apa-split__cross { opacity: 1; }
.apa-split[data-peek] .apa-split__cross { opacity: 0; }
.apa-split__cross i { position: absolute; background: color-mix(in oklch, var(--apa-split-ink) 34%, transparent); }
.apa-split__cross i:first-child { left: 0; right: 0; top: 0; height: 1px; translate: 0 var(--y, -10px); }
.apa-split__cross i:nth-child(2) { top: 0; bottom: 0; left: 0; width: 1px; translate: var(--x, -10px) 0; }
.apa-split__cross b { position: absolute; left: -7px; top: -7px; width: 14px; height: 14px; border-radius: 50%; border: 1.5px solid var(--apa-split-ink); translate: var(--x, -20px) var(--y, -20px); }

/* ---------- pane ---------- */
.apa-split__top { display: flex; align-items: center; justify-content: flex-end; gap: 12px; padding: 18px clamp(18px, 3.4cqi, 36px) 0; min-height: 52px; }
.apa-split__brand--pane { display: none; margin-right: auto; box-shadow: none; padding-left: 0; background: none; height: auto; }
.apa-split__swap { font-size: 13px; color: var(--apa-split-muted); }
.apa-split__link {
  color: var(--apa-split-ink); font-weight: 650; border-radius: 4px;
  text-decoration: underline; text-decoration-color: color-mix(in oklch, var(--apa-split-accent) 55%, transparent); text-underline-offset: 3px; text-decoration-thickness: 1.5px;
  transition: text-decoration-color .2s, color .2s;
}
.apa-split__link:hover { color: var(--apa-split-accent); text-decoration-color: currentColor; }

.apa-split__stage { display: grid; place-items: center; min-height: 0; overflow: auto; padding: 18px clamp(18px, 5cqi, 56px); overscroll-behavior: contain; scrollbar-width: thin; }
.apa-split__view { width: min(100%, 384px); display: grid; gap: 0; }
.apa-split__view > * { animation: apa-split-rise .62s var(--apa-split-ease) both; animation-delay: calc(var(--i, 0) * 45ms); }
.apa-split__eyebrow { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: var(--apa-split-accent); margin-bottom: 12px; }
.apa-split__title {
  font: 400 clamp(30px, 1.3rem + 2.1cqi, 42px)/1.04 ui-serif, "New York", Georgia, serif; letter-spacing: -.025em; text-wrap: balance; outline: none;
}
.apa-split__lede { margin-top: 10px; color: var(--apa-split-muted); font-size: 14.5px; text-wrap: pretty; max-width: 36ch; }
.apa-split__lede b { color: var(--apa-split-ink); font-weight: 600; }

.apa-split__tabs {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; margin-top: 22px; padding: 3px; border-radius: 11px;
  background: color-mix(in oklch, var(--apa-split-ink) 6.5%, transparent);
}
.apa-split__tabs::before {
  content: ""; position: absolute; top: 3px; bottom: 3px; left: 3px; width: calc(50% - 3px); border-radius: 8px;
  background: var(--apa-split-field); box-shadow: 0 1px 2px color-mix(in oklch, var(--apa-split-ink) 16%, transparent), 0 0 0 1px var(--apa-split-rule);
  transition: translate .5s var(--apa-split-spring);
}
.apa-split[data-method="passkey"] .apa-split__tabs::before { translate: 100% 0; }
.apa-split__tabs button { position: relative; height: 34px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--apa-split-muted); transition: color .25s; }
.apa-split__tabs button[aria-selected="true"] { color: var(--apa-split-ink); }
.apa-split[data-mode="signup"] .apa-split__tabs { display: none; }
.apa-split[data-mode="signup"] .apa-split__forgot, .apa-split[data-view="done"] .apa-split__swap { visibility: hidden; }

.apa-split__form { display: grid; gap: 0; margin-top: 18px; }
.apa-split__form.is-shake { animation: apa-split-shake .44s cubic-bezier(.36, .07, .19, .97) both; }
.apa-split__field { display: grid; gap: 6px; }
.apa-split__lbl { font-size: 12.5px; font-weight: 620; letter-spacing: .005em; }
.apa-split__form :is(.apa-split__field, .apa-split__pw) + * { margin-top: 0; }
.apa-split__form > :is(label, .apa-split__pw, .apa-split__passkey, .apa-split__check) { margin-top: 14px; }
.apa-split__form > :first-child + label { margin-top: 0; }
.apa-split__grow { display: grid; grid-template-rows: 0fr; opacity: 0; visibility: hidden; transition: grid-template-rows .5s var(--apa-split-ease), opacity .3s, visibility 0s .5s; }
.apa-split__grow > div { min-height: 0; overflow: hidden; padding: 2px; margin: -2px; }
.apa-split__grow > div > :last-child:not(:empty) { margin-bottom: 4px; }
.apa-split[data-mode="signup"] .apa-split__grow { grid-template-rows: 1fr; opacity: 1; visibility: visible; transition-delay: 0s; padding-bottom: 14px; }

.apa-split input:is([type="text"], [type="email"], [type="password"]) {
  width: 100%; height: 44px; padding: 0 14px; border-radius: 10px; border: 1px solid var(--apa-split-rule2);
  background: var(--apa-split-field); font-size: 14.5px; outline: none;
  transition: border-color .2s, box-shadow .25s var(--apa-split-ease), background-color .2s;
}
.apa-split input::placeholder { color: var(--apa-split-faint); }
.apa-split input:hover { border-color: color-mix(in oklch, var(--apa-split-ink) 34%, transparent); }
.apa-split input:focus { border-color: var(--apa-split-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-split-accent) 17%, transparent); background: white; }
.apa-split input[aria-invalid="true"] { border-color: var(--apa-split-bad); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-split-bad) 13%, transparent); }
.apa-split__err { color: var(--apa-split-bad); font-size: 12.5px; margin-top: 6px; display: flex; gap: 6px; }
.apa-split__err:empty { display: none; }

.apa-split__pw { display: grid; gap: 6px; }
.apa-split__pwhead { display: flex; justify-content: space-between; align-items: baseline; }
.apa-split__forgot { font-size: 12.5px; font-weight: 600; }
.apa-split__pwbox { position: relative; }
.apa-split__pwbox input { padding-right: 46px; letter-spacing: .02em; }
.apa-split__eye { position: absolute; top: 4px; right: 4px; width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center; color: var(--apa-split-muted); transition: color .2s, background-color .2s; }
.apa-split__eye:hover { color: var(--apa-split-ink); background: color-mix(in oklch, var(--apa-split-ink) 6%, transparent); }
.apa-split__eye > svg { grid-area: 1 / 1; transition: opacity .2s, scale .35s var(--apa-split-spring); }
.apa-split__eye-off, .apa-split__eye[aria-pressed="true"] .apa-split__eye-on { opacity: 0; scale: .6; }
.apa-split__eye[aria-pressed="true"] .apa-split__eye-off { opacity: 1; scale: 1; }
.apa-split__caps { display: flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 600; color: var(--apa-split-accent); animation: apa-split-rise .35s var(--apa-split-ease) both; }
.apa-split__caps svg { width: 15px; height: 15px; }

.apa-split__passkey {
  display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center; padding: 14px; border-radius: 12px;
  background: color-mix(in oklch, var(--apa-split-accent) 7%, var(--apa-split-field)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-split-accent) 22%, transparent);
  font-size: 13px; color: var(--apa-split-muted); text-wrap: pretty; animation: apa-split-rise .45s var(--apa-split-ease) both;
}
.apa-split__passkey b { color: var(--apa-split-ink); display: block; font-weight: 650; }
.apa-split__pkicon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--apa-split-paper); color: var(--apa-split-accent); box-shadow: 0 0 0 1px var(--apa-split-rule); }
.apa-split__pkicon svg { width: 24px; height: 24px; stroke-width: 1.6; }
.apa-split[data-method="password"] [data-only="passkey"], .apa-split[data-method="passkey"] [data-only="password"] { display: none; }

.apa-split__check { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; color: var(--apa-split-muted); cursor: pointer; }
.apa-split__check input { width: 16px; height: 16px; margin: 1px 0 0; flex: none; }
.apa-split__check:has(input:checked) { color: var(--apa-split-ink); }

.apa-split__submit {
  position: relative; overflow: hidden; display: flex; align-items: center; justify-content: center; gap: 10px;
  height: 46px; margin-top: 20px; padding: 0 18px; border-radius: 11px;
  background: var(--apa-split-ink); color: var(--apa-split-paper); font-weight: 650; font-size: 14.5px; letter-spacing: .005em;
  box-shadow: 0 10px 22px -14px color-mix(in oklch, var(--apa-split-ink) 80%, transparent);
  transition: background-color .25s, scale .3s var(--apa-split-spring), box-shadow .25s;
}
.apa-split__submit:hover { background: color-mix(in oklch, var(--apa-split-ink) 82%, var(--apa-split-accent)); }
.apa-split__submit:active { scale: .985; }
.apa-split__submit kbd { background: color-mix(in oklch, var(--apa-split-paper) 16%, transparent); box-shadow: none; }
.apa-split__submit[aria-busy="true"] { cursor: progress; }
.apa-split__submit[aria-busy="true"]::after {
  content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 38%; background: var(--apa-split-accent);
  animation: apa-split-busy 1.05s cubic-bezier(.6, 0, .3, 1) infinite;
}
.apa-split__submit:disabled { cursor: default; background: color-mix(in oklch, var(--apa-split-ink) 70%, var(--apa-split-paper)); }
.apa-split__submit--sm { height: 38px; margin: 0; font-size: 13.5px; }
.apa-split__status { margin-top: 10px; font-size: 12.5px; color: var(--apa-split-muted); min-height: 1.45em; text-align: center; }
.apa-split__ghost {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 38px; padding: 0 14px; border-radius: 10px;
  font-weight: 600; font-size: 13.5px; color: var(--apa-split-ink); box-shadow: inset 0 0 0 1px var(--apa-split-rule2);
  transition: background-color .2s, box-shadow .2s;
}
.apa-split__ghost:hover { background: color-mix(in oklch, var(--apa-split-ink) 5%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-split-ink) 34%, transparent); }

/* ---------- signed-in view ---------- */
.apa-split__seal {
  display: grid; place-items: center; width: 58px; height: 58px; border-radius: 50%; margin-bottom: 20px;
  background: var(--apa-split-accent); color: var(--apa-split-paper);
  box-shadow: 0 0 0 8px color-mix(in oklch, var(--apa-split-accent) 14%, transparent);
}
.apa-split__seal svg { width: 28px; height: 28px; stroke-width: 2.4; stroke-dasharray: 24; stroke-dashoffset: 24; animation: apa-split-draw .6s .25s var(--apa-split-ease) forwards; }
.apa-split__ws {
  display: flex; align-items: center; gap: 12px; margin-top: 22px; padding: 12px; border-radius: 12px;
  background: var(--apa-split-field); box-shadow: inset 0 0 0 1px var(--apa-split-rule);
}
.apa-split__wsmark { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 10px; background: var(--apa-split-ink); color: var(--apa-split-paper); font-weight: 750; font-size: 14px; letter-spacing: .02em; flex: none; }
.apa-split__wstext b { display: block; font-weight: 650; }
.apa-split__wstext small { color: var(--apa-split-muted); font-size: 12.5px; font-variant-numeric: tabular-nums; }
.apa-split__sync { margin-top: 16px; }
.apa-split__bar { height: 6px; border-radius: 99px; background: color-mix(in oklch, var(--apa-split-ink) 9%, transparent); overflow: hidden; }
.apa-split__bar i { display: block; height: 100%; border-radius: inherit; background: var(--apa-split-accent); transform-origin: 0 50%; scale: var(--apa-split-p) 1; transition: --apa-split-p .45s var(--apa-split-ease); }
.apa-split__synctext { margin-top: 8px; font-size: 12.5px; color: var(--apa-split-muted); font-variant-numeric: tabular-nums; }
.apa-split__sync[data-state="done"] .apa-split__synctext { color: var(--apa-split-ink); font-weight: 600; }
.apa-split__actions { display: grid; grid-template-columns: 1fr auto; gap: 10px; align-items: end; }
.apa-split__actions .apa-split__ghost { height: 46px; }

/* ---------- footer ---------- */
.apa-split__foot {
  display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 12px clamp(18px, 3.4cqi, 36px) 16px;
  font-size: 11.5px; color: var(--apa-split-faint);
}
.apa-split__hints { display: inline-flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.apa-split__hints kbd + kbd { margin-left: -1px; }
.apa-split__hints kbd:not(:first-child) { margin-left: 8px; }
.apa-split__hints kbd + kbd:not(:first-child) { margin-left: 2px; }

/* ---------- overlays ---------- */
.apa-split__layer {
  position: absolute; inset: 0; z-index: 10; display: grid; place-items: center; padding: 16px;
  background: color-mix(in oklch, var(--apa-split-ink) 30%, transparent);
  opacity: 1; transition: opacity .3s;
}
@starting-style { .apa-split__layer { opacity: 0; } }
.apa-split__sheet {
  width: min(340px, 100%); padding: 26px 24px 20px; border-radius: 18px; background: var(--apa-split-paper); text-align: center;
  display: grid; justify-items: center; gap: 4px;
  box-shadow: 0 30px 70px -30px color-mix(in oklch, var(--apa-split-ink) 70%, transparent), 0 0 0 1px var(--apa-split-rule);
  transition: opacity .35s, translate .5s var(--apa-split-spring), scale .5s var(--apa-split-spring);
}
@starting-style { .apa-split__sheet { opacity: 0; translate: 0 14px; scale: .96; } }
.apa-split__sheet--left { text-align: left; justify-items: stretch; width: min(380px, 100%); gap: 8px; }
.apa-split__sheett { font-weight: 700; font-size: 16px; letter-spacing: -.01em; }
.apa-split__sheets { font: 500 12.5px/1.3 ui-monospace, Menlo, monospace; color: var(--apa-split-muted); }
.apa-split__sheetm { font-size: 13.5px; color: var(--apa-split-muted); text-wrap: pretty; margin: 8px 0 14px; }
.apa-split__sheetm b { color: var(--apa-split-ink); }
.apa-split__sheet--left .apa-split__sheetm { margin: 0 0 8px; }
.apa-split__sheet[data-state="ask"] .apa-split__sent, .apa-split__sheet[data-state="sent"] .apa-split__ask { display: none; }
.apa-split__sheetact { display: flex; justify-content: flex-end; gap: 8px; }
.apa-split__ring {
  position: relative; display: grid; place-items: center; width: 84px; height: 84px; margin-bottom: 14px; border-radius: 50%;
  color: var(--apa-split-accent); background: color-mix(in oklch, var(--apa-split-accent) 10%, var(--apa-split-paper));
  transition: background-color .4s, color .4s;
}
.apa-split__ring::before, .apa-split__ring::after {
  content: ""; position: absolute; inset: 0; border-radius: 50%; border: 1.5px solid color-mix(in oklch, var(--apa-split-accent) 50%, transparent);
  animation: apa-split-pulse 2s cubic-bezier(.2, .7, .3, 1) infinite;
}
.apa-split__ring::after { animation-delay: 1s; }
.apa-split__ring svg { grid-area: 1 / 1; width: 40px; height: 40px; stroke-width: 1.5; transition: opacity .3s, scale .5s var(--apa-split-spring); }
.apa-split__ok { opacity: 0; scale: .4; stroke-width: 2.4 !important; }
.apa-split__sheet[data-state="ok"] .apa-split__ring { background: var(--apa-split-accent); color: var(--apa-split-paper); }
.apa-split__sheet[data-state="ok"] .apa-split__ring::before, .apa-split__sheet[data-state="ok"] .apa-split__ring::after { animation: none; opacity: 0; }
.apa-split__sheet[data-state="ok"] .apa-split__fp { opacity: 0; scale: .4; }
.apa-split__sheet[data-state="ok"] .apa-split__ok { opacity: 1; scale: 1; }

/* ---------- keyframes ---------- */
@keyframes apa-split-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes apa-split-shake { 15%, 85% { translate: -2px 0; } 30%, 70% { translate: 5px 0; } 45%, 55% { translate: -7px 0; } }
@keyframes apa-split-busy { from { translate: -100% 0; } to { translate: 270% 0; } }
@keyframes apa-split-draw { to { stroke-dashoffset: 0; } }
@keyframes apa-split-pulse { from { scale: 1; opacity: .9; } to { scale: 1.55; opacity: 0; } }
@keyframes apa-split-flash { 0% { color: var(--apa-split-accent); } 100% { color: var(--apa-split-ink); } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-split__app { grid-template-columns: minmax(0, .8fr) minmax(360px, 1fr); }
  .apa-split__quote { padding: 14px 16px; }
  .apa-split__quote figcaption small { display: none; }
  .apa-split__plateno { display: none; }
}
/* ---------- container: single pane ---------- */
@container (max-width: 759px) {
  .apa-split__app { grid-template: "art" 136px "pane" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-split__art { margin: 8px 8px 0; border-radius: 12px; }
  .apa-split__quote, .apa-split__cross, .apa-split__veil span { display: none; }
  .apa-split__veil svg { width: 26px; height: 26px; }
  .apa-split__plate { inset: 12px 12px auto; }
  .apa-split__legend { left: 12px; right: 12px; bottom: 10px; }
  .apa-split__top { padding-top: 14px; min-height: 0; }
  .apa-split__stage { place-items: start center; padding-top: 14px; }
  .apa-split__hints { display: none; }
  .apa-split__foot { justify-content: center; padding-top: 8px; }
}
@container (max-width: 460px) {
  .apa-split__swapq, .apa-split__seed, .apa-split__plateno { display: none; }
  .apa-split__legend { justify-content: flex-end; }
  .apa-split__stage { padding-inline: 16px; }
  .apa-split__title { font-size: 30px; }
  .apa-split__actions { grid-template-columns: 1fr; }
  .apa-split__actions .apa-split__ghost { height: 40px; }
}

/* ---------- reduced motion: a still map, instant swaps ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-split *, .apa-split *::before, .apa-split *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
  .apa-split__ring::before, .apa-split__ring::after { display: none; }
  .apa-split[data-peek] .apa-split__map { filter: saturate(.3) opacity(.45); scale: 1; }
  .apa-split__seal svg { stroke-dashoffset: 0; }
}

