// Presentational only: nothing is sent, stored or checked against a real account.
root.addEventListener('submit', (e) => e.preventDefault());
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = 'apa-split-' + Math.random().toString(36).slice(2, 8);
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);

const form = $('.apa-split__form');
const F = { name: form.elements.name, email: form.elements.email, pass: form.elements.pass, keep: form.elements.keep };
const submitBtn = form.querySelector('.apa-split__submit');
const statusEl = $('.apa-split__status');
const S = { mode: 'signin', method: 'password', view: 'form', busy: false, via: 'password', layer: null, sync: 'idle', lastFocus: null };

const COPY = {
  signin: { title: 'Welcome back', lede: 'Sign in to pick up your field maps where your crew left them.', q: 'New to Tallus?', swap: 'Create an account', keep: 'Keep me signed in on this device for 30 days', submit: 'Sign in', eyebrow: 'Field maps & survey plates' },
  signup: { title: 'Map it with your crew', lede: 'Your first three survey plates are free, offline maps included. No card needed.', q: 'Already mapping?', swap: 'Sign in instead', keep: 'Send me field-season tips, about once a month', submit: 'Create account', eyebrow: 'New workspace' },
};
const KNOWN = {
  'harrowwater.org': { org: 'Harrow County Water', person: 'Ines Okafor', crews: 6,
    maps: ['Kettle Ridge north', 'Kettle Ridge south', 'Alder Creek intake', 'Moraine pumphouse', 'Lyle Basin', 'Spillway 3', 'Cedar Flats', 'Upper Harrow main', 'Pike Hollow', 'Reservoir west shore', 'Gauge station 11', 'Fenwick culverts', 'Old mill race', 'Summit tank'] },
};
const GENERIC_MAPS = ['North parcel', 'South parcel', 'Access road', 'Creek crossing', 'Ridge line', 'Pump site', 'Trailhead lot', 'Quarry edge', 'East boundary', 'Wetland margin', 'Bridge footings', 'Utility corridor'];

const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
