const emailOk = (v) => /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v);
const domainOf = (v) => { const m = /@([a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,})$/i.exec(v.trim()); return m ? m[1].toLowerCase() : null; };
const nf = new Intl.NumberFormat('en-US');
const thin = (n) => nf.format(n).replace(/,/g, ' ');

/* ---------- ids for error descriptions ---------- */
['name', 'email', 'pass'].forEach((k) => {
  const p = $(`[data-err="${k}"]`); p.id = uid + '-' + k; F[k].setAttribute('aria-describedby', p.id);
});

/* ---------- render ---------- */
function render() {
  const c = COPY[S.mode];
  const method = S.mode === 'signup' ? 'password' : S.method;
  root.dataset.mode = S.mode; root.dataset.method = method; root.dataset.view = S.view;
  const formView = $('[data-v="form"]');
  formView.querySelector('.apa-split__title').textContent = c.title;
  formView.querySelector('.apa-split__lede').textContent = c.lede;
  formView.querySelector('.apa-split__eyebrow').textContent = c.eyebrow;
  formView.setAttribute('aria-label', S.mode === 'signup' ? 'Create account' : 'Sign in');
  $('.apa-split__swapq').textContent = c.q;
  $('[data-act="mode"]').textContent = c.swap;
  $('.apa-split__keep').textContent = c.keep;
  if (!S.busy) submitBtn.querySelector('.apa-split__sublabel').textContent = method === 'passkey' ? 'Continue with passkey' : c.submit;
  F.pass.placeholder = S.mode === 'signup' ? 'At least 10 characters' : 'Your password';
