function swapCopy() {
  if (reduce) return;
  $$('[data-v="form"] :is(.apa-split__eyebrow, .apa-split__title, .apa-split__lede)').forEach((el, i) => {
    el.animate([{ opacity: 0, transform: 'translateY(8px)', filter: 'blur(3px)' }, { opacity: 1, transform: 'none', filter: 'none' }],
