    sheet.querySelector('.apa-split__sheetm').textContent = 'Touch the sensor or use your screen lock';
    clearTimeout(pkTimer);
    pkTimer = later(() => {
      sheet.dataset.state = 'ok'; sheet.querySelector('.apa-split__sheetm').textContent = 'Verified on this device';
      pkTimer = later(() => { closeLayer(true); finish('passkey'); }, reduce ? 200 : 750);
    }, reduce ? 600 : 1900);
    later(() => sheet.querySelector('[data-act="close"]').focus(), 20);
