    water: rgbOf('--apa-split-water', [206, 224, 236]), low: rgbOf('--apa-split-low', [214, 228, 196]),
    high: rgbOf('--apa-split-high', [236, 220, 190]), paper: rgbOf('--apa-split-paper', [248, 245, 238]),
    line: rgbOf('--apa-split-line', [140, 80, 50]), ink: rgbOf('--apa-split-ink', [50, 40, 30]),
  };
}
const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const rgba = (c, a) => `rgba(${c[0] | 0},${c[1] | 0},${c[2] | 0},${a})`;

function resize() {
  const r = art.getBoundingClientRect();
  if (!r.width || !r.height) return;
  W = r.width; H = r.height; dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
