}

function computeField() {
  let best = -9, bi = 0, bj = 0;
  for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
    const v = height(i * cell, j * cell); field[j * cols + i] = v;
    if (v > best && i > 2 && j > 2 && i < cols - 4 && j < rows - 4) { best = v; bi = i; bj = j; }
  }
  peak = { x: bi * cell, y: bj * cell, m: Math.round(toM(best)) };
}

function paintTint() {
  const d = img.data, wl = hOf(500);
  for (let k = 0, p = 0; k < field.length; k++, p += 4) {
    const h = field[k]; let c;
    if (h < wl) c = mix(pal.water, pal.low, Math.max(0, 1 - (wl - h) * 6) * 0.25);
    else { const t = Math.min(1, (h - wl) / (hOf(1900) - wl)); c = t < 1 ? mix(pal.low, pal.high, t) : mix(pal.high, pal.paper, Math.min(1, (h - hOf(1900)) / 0.25)); }
    d[p] = c[0]; d[p + 1] = c[1]; d[p + 2] = c[2]; d[p + 3] = 255;
  }
  tctx.putImageData(img, 0, 0);
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(tint, -cell / 2, -cell / 2, cols * cell, rows * cell);
}

// marching squares: corners a(tl)=8 b(tr)=4 c(br)=2 d(bl)=1; edges 0 top 1 right 2 bottom 3 left
const SEG = [[], [3, 2], [2, 1], [3, 1], [0, 1], [3, 0, 2, 1], [0, 2], [3, 0], [3, 0], [0, 2], [0, 1, 3, 2], [0, 1], [3, 1], [2, 1], [3, 2], []];
let EX = 0, EY = 0;
function edge(e, x, y, a, b, c, d, v) {
  if (e === 0) { EX = x + cell * (v - a) / (b - a); EY = y; }
  else if (e === 1) { EX = x + cell; EY = y + cell * (v - b) / (c - b); }
  else if (e === 2) { EX = x + cell * (v - d) / (c - d); EY = y + cell; }
  else { EX = x; EY = y + cell * (v - a) / (d - a); }
}
function contour() {
  for (let k = 0; k < NL; k++) segs[k].length = 0;
  const h0 = hOf(LV0), hs = LVSTEP / MS;
  for (let j = 0; j < rows - 1; j++) for (let i = 0; i < cols - 1; i++) {
    const a = field[j * cols + i], b = field[j * cols + i + 1], c = field[(j + 1) * cols + i + 1], d = field[(j + 1) * cols + i];
    const lo = Math.min(a, b, c, d), hi = Math.max(a, b, c, d);
    let k0 = Math.ceil((lo - h0) / hs), k1 = Math.floor((hi - h0) / hs);
    if (k0 < 0) k0 = 0; if (k1 > NL - 1) k1 = NL - 1;
    for (let k = k0; k <= k1; k++) {
      const v = h0 + k * hs;
      const idx = (a > v ? 8 : 0) | (b > v ? 4 : 0) | (c > v ? 2 : 0) | (d > v ? 1 : 0);
      const s = SEG[idx]; if (!s.length) continue;
      const x = i * cell, y = j * cell, out = segs[k];
      for (let q = 0; q < s.length; q += 2) {
        edge(s[q], x, y, a, b, c, d, v); out.push(EX, EY);
        edge(s[q + 1], x, y, a, b, c, d, v); out.push(EX, EY);
