    }
  }
  ctx.lineCap = 'round';
  for (let k = 0; k < NL; k++) {
    const m = LV0 + k * LVSTEP, s = segs[k]; if (!s.length) continue;
    const index = m % 500 === 0, shore = m === 500;
    ctx.beginPath();
    for (let q = 0; q < s.length; q += 4) { ctx.moveTo(s[q], s[q + 1]); ctx.lineTo(s[q + 2], s[q + 3]); }
    ctx.strokeStyle = shore ? rgba(mix(pal.water, pal.ink, 0.45), 0.85) : rgba(pal.line, index ? 0.78 : 0.36);
    ctx.lineWidth = shore ? 1.4 : index ? 1.25 : 0.7;
    ctx.stroke();
