}
function drawPeak() {
  const { x, y, m } = peak;
  ctx.fillStyle = rgba(pal.ink, 0.9);
  ctx.beginPath(); ctx.moveTo(x, y - 5); ctx.lineTo(x + 4.5, y + 3); ctx.lineTo(x - 4.5, y + 3); ctx.closePath(); ctx.fill();
  ctx.font = '600 10.5px ui-monospace, Menlo, monospace'; ctx.textBaseline = 'middle';
  const label = thin(m) + ' m', tw = ctx.measureText(label).width;
  const lx = x + tw + 14 > W ? x - tw - 9 : x + 9;
  ctx.lineWidth = 3; ctx.strokeStyle = rgba(pal.paper, 0.9); ctx.strokeText(label, lx, y);
  ctx.fillText(label, lx, y);
}
let hovering = false;
function draw() {
  if (!field || !pal) return;
  computeField();
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  paintTint(); contour(); drawPeak();
  if (!hovering) readout.textContent = `Summit ${thin(peak.m)} m`;
}

/* loop: ~30 fps, only while visible */
let raf = 0, last = 0, visible = false, frameNo = 0;
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible) return;
  if (!document.hidden) {
    const dt = last ? Math.min(80, now - last) : 16; last = now;
    T += dt * 0.000016;
    const settling = Math.abs(tx - ox) + Math.abs(ty - oy) > 0.002;
    ox += (tx - ox) * 0.06; oy += (ty - oy) * 0.06;
    if (settling || (frameNo++ & 1) === 0) draw();
  }
  raf = requestAnimationFrame(frame);
}
function start() { if (!raf && !reduce && visible) { last = 0; raf = requestAnimationFrame(frame); } }

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } resize(); });
ro.observe(art);
const io = new IntersectionObserver((ents) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = ents[ents.length - 1].isIntersecting; if (visible) start();
});
io.observe(root);

/* seed from the email domain */
let seedTimer = 0, seeded = 'harrowwater.org';
function seedFrom(dom) {
  const h = hash(dom);
  tx = 3.1 + ((h & 1023) / 1023) * 40; ty = 7.4 + (((h >>> 10) & 1023) / 1023) * 40;
  if (dom === 'harrowwater.org') { tx = 3.1; ty = 7.4; }
  if (reduce || !visible) { ox = tx; oy = ty; draw(); }
}
F.email.addEventListener('input', () => {
  clearTimeout(seedTimer);
  seedTimer = later(() => {
    const dom = domainOf(F.email.value);
    if (!dom || dom === seeded) return;
    seeded = dom; seedEl.textContent = dom;
    seedEl.parentElement.classList.remove('is-new'); void seedEl.offsetWidth; seedEl.parentElement.classList.add('is-new');
    seedFrom(dom);
  }, 280);
});

/* pointer readout: elevation under the crosshair */
art.addEventListener('pointermove', (e) => {
  const r = art.getBoundingClientRect(); const x = e.clientX - r.left, y = e.clientY - r.top;
  hovering = true;
  cross.style.setProperty('--x', x + 'px'); cross.style.setProperty('--y', y + 'px');
  const m = Math.round(toM(height(x, y)));
  const lat = 47.6182 + (H / 2 - y) * 0.000098, lon = 121.0491 - (x - W / 2) * 0.000141;
  readout.textContent = m < 500 ? `${lat.toFixed(4)}° N  ${lon.toFixed(4)}° W  water` : `${lat.toFixed(4)}° N  ${lon.toFixed(4)}° W  ${thin(m)} m`;
});
art.addEventListener('pointerleave', () => { hovering = false; readout.textContent = `Summit ${thin(peak.m)} m`; });

render();

