/* Plan & receipt sign-up. Re-theme with --apa-plans-bg, -ink, -accent and -paper. */
.apa-plans {
  --apa-plans-bg: oklch(0.215 0.034 158);
  --apa-plans-ink: oklch(0.95 0.022 115);
  --apa-plans-accent: oklch(0.89 0.19 124);
  --apa-plans-paper: oklch(0.965 0.018 92);

  --apa-plans-print: color-mix(in oklch, var(--apa-plans-bg) 70%, black);
  --apa-plans-card: color-mix(in oklch, var(--apa-plans-ink) 5%, var(--apa-plans-bg));
  --apa-plans-side: color-mix(in oklch, var(--apa-plans-bg) 78%, black);
  --apa-plans-line: color-mix(in oklch, var(--apa-plans-ink) 11%, transparent);
  --apa-plans-line2: color-mix(in oklch, var(--apa-plans-ink) 20%, transparent);
  --apa-plans-muted: color-mix(in oklch, var(--apa-plans-ink) 64%, var(--apa-plans-bg));
  --apa-plans-faint: color-mix(in oklch, var(--apa-plans-ink) 40%, var(--apa-plans-bg));
  --apa-plans-on: color-mix(in oklch, var(--apa-plans-accent) 25%, black);
  --apa-plans-bad: oklch(0.74 0.16 32);
  --apa-plans-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-plans-spring: linear(0, 0.07 3.5%, 0.29 8%, 0.68 15%, 0.94 22%, 1.06 28%, 1.09 34%, 1.06 42%, 1.02 52%, 0.995 66%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-plans-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-plans-bg);
  color: var(--apa-plans-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apa-plans-accent);
  outline: none;
}
:where(.apa-plans) *, :where(.apa-plans) *::before, :where(.apa-plans) *::after { box-sizing: border-box; }
:where(.apa-plans) :is(button, input, select) { font: inherit; color: inherit; }
:where(.apa-plans) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-plans) :is(p, h2, ul, ol, dl, dd, fieldset) { margin: 0; padding: 0; }
:where(.apa-plans) :is(ul, ol) { list-style: none; }
:where(.apa-plans) fieldset { border: 0; min-width: 0; }
:where(.apa-plans) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-plans) :focus-visible { outline: 2px solid var(--apa-plans-accent); outline-offset: 2px; }
:where(.apa-plans) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 12%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 18%, transparent);
}
.apa-plans [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-plans__app { display: grid; height: 100%; grid-template: "main side" minmax(0, 1fr) / minmax(0, 1fr) 372px; }
.apa-plans__main { grid-area: main; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.apa-plans__side { grid-area: side; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; background: var(--apa-plans-side); border-left: 1px solid var(--apa-plans-line); }

/* ---------- header + stepper ---------- */
.apa-plans__head { display: flex; align-items: center; gap: 18px; padding: 18px clamp(18px, 3cqi, 32px) 12px; }
.apa-plans__brand { display: inline-flex; align-items: center; gap: 8px; font-weight: 780; font-size: 16px; letter-spacing: -.02em; }
.apa-plans__brand svg { width: 22px; height: 22px; color: var(--apa-plans-accent); }
.apa-plans__steps { display: flex; align-items: center; gap: 0; margin-left: auto; counter-reset: none; }
.apa-plans__steps li { display: flex; align-items: center; }
.apa-plans__steps li + li::before { content: ""; width: clamp(14px, 3cqi, 34px); height: 2px; margin: 0 8px; border-radius: 2px; background: linear-gradient(90deg, var(--apa-plans-accent) 50%, var(--apa-plans-line2) 50%) 100% 0 / 200% 100%; transition: background-position .6s var(--apa-plans-ease); }
.apa-plans__steps li.is-done + li::before { background-position: 0 0; }
.apa-plans__steps button { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px 0 4px; border-radius: 99px; font-size: 13px; font-weight: 600; color: var(--apa-plans-muted); transition: color .25s, background-color .25s; }
.apa-plans__steps button:disabled { cursor: default; color: var(--apa-plans-faint); }
.apa-plans__steps button:not(:disabled):hover { background: var(--apa-plans-line); }
.apa-plans__steps b { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; font-size: 12px; font-variant-numeric: tabular-nums; box-shadow: inset 0 0 0 1.5px currentColor; transition: background-color .3s, color .3s, box-shadow .3s; }
.apa-plans__steps li.is-done b { background: var(--apa-plans-accent); color: var(--apa-plans-on); box-shadow: none; font-size: 0; }
.apa-plans__steps li.is-done b::before { content: ""; width: 10px; height: 6px; border: solid currentColor; border-width: 0 0 2px 2px; rotate: -45deg; translate: 0 -1px; font-size: 12px; }
.apa-plans__steps button[aria-current="step"] { color: var(--apa-plans-ink); }
.apa-plans__steps button[aria-current="step"] b { background: var(--apa-plans-ink); color: var(--apa-plans-bg); box-shadow: none; }

/* ---------- body + steps ---------- */
.apa-plans__body { min-height: 0; overflow: auto; padding: 14px clamp(18px, 3cqi, 32px) 22px; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apa-plans-line2) transparent; }
.apa-plans__step { display: grid; align-content: start; gap: 0; max-width: 700px; }
.apa-plans__kicker { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--apa-plans-accent); }
.apa-plans__h { margin-top: 10px; font-size: clamp(24px, 0.9rem + 1.9cqi, 34px); line-height: 1.06; font-weight: 760; letter-spacing: -.035em; text-wrap: balance; outline: none; }
.apa-plans__sub { margin-top: 10px; color: var(--apa-plans-muted); font-size: 14.5px; text-wrap: pretty; max-width: 52ch; }
.apa-plans__sub b { color: var(--apa-plans-ink); font-weight: 650; }

.apa-plans__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 16px; margin-top: 24px; }
.apa-plans__field { display: grid; gap: 6px; align-content: start; }
.apa-plans__field--wide { grid-column: 1 / -1; }
.apa-plans__field > span { font-size: 12.5px; font-weight: 620; color: var(--apa-plans-muted); }
.apa-plans :is(input:not([type="radio"], [type="checkbox"]), select) {
  width: 100%; height: 44px; padding: 0 13px; border-radius: 10px; border: 1px solid var(--apa-plans-line2);
  background: color-mix(in oklch, var(--apa-plans-ink) 4%, var(--apa-plans-bg)); font-size: 14.5px; outline: none;
  transition: border-color .2s, box-shadow .25s var(--apa-plans-ease);
}
.apa-plans input[type="number"] { font-variant-numeric: tabular-nums; }
.apa-plans :is(input, select):hover { border-color: color-mix(in oklch, var(--apa-plans-ink) 34%, transparent); }
.apa-plans :is(input:not([type="radio"], [type="checkbox"]), select):focus { border-color: var(--apa-plans-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-plans-accent) 18%, transparent); }
.apa-plans [aria-invalid="true"] { border-color: var(--apa-plans-bad) !important; }
.apa-plans [data-err] { font-style: normal; font-size: 12.5px; color: var(--apa-plans-bad); }
.apa-plans [data-err]:empty { display: none; }
.apa-plans__rec { display: flex; gap: 10px; align-items: flex-start; margin-top: 22px; padding: 13px 14px; border-radius: 12px; background: color-mix(in oklch, var(--apa-plans-accent) 8%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-plans-accent) 22%, transparent); font-size: 13.5px; color: var(--apa-plans-muted); text-wrap: pretty; }
.apa-plans__rec svg { color: var(--apa-plans-accent); margin-top: 1px; }
.apa-plans__rec b { color: var(--apa-plans-ink); font-variant-numeric: tabular-nums; }

/* plan step */
.apa-plans__planhead { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.apa-plans__bill { display: inline-grid; grid-auto-flow: column; padding: 3px; border-radius: 11px; background: var(--apa-plans-line); position: relative; }
.apa-plans__bill label { position: relative; display: block; cursor: pointer; }
.apa-plans__bill input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
.apa-plans__bill span { display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px; border-radius: 8px; font-size: 13px; font-weight: 620; color: var(--apa-plans-muted); transition: background-color .25s, color .25s; white-space: nowrap; }
.apa-plans__bill em { font-style: normal; font-size: 11px; font-weight: 700; padding: 2px 6px; border-radius: 5px; background: color-mix(in oklch, var(--apa-plans-accent) 18%, transparent); color: var(--apa-plans-accent); }
.apa-plans__bill label:has(input:checked) span { background: var(--apa-plans-ink); color: var(--apa-plans-bg); }
.apa-plans__bill label:has(input:checked) em { background: var(--apa-plans-on); color: var(--apa-plans-accent); }
.apa-plans__bill label:has(input:focus-visible) span { outline: 2px solid var(--apa-plans-accent); outline-offset: 2px; }

.apa-plans__plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 18px; }
.apa-plans__plan {
  position: relative; display: grid; align-content: start; gap: 6px; padding: 16px 16px 15px; border-radius: 14px; cursor: pointer;
  background: var(--apa-plans-card); box-shadow: inset 0 0 0 1px var(--apa-plans-line);
  transition: box-shadow .3s, background-color .3s, translate .45s var(--apa-plans-spring);
  animation: apa-plans-rise .55s var(--apa-plans-ease) both; animation-delay: calc(var(--i) * 60ms);
}
.apa-plans__plan::before { content: ""; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(180deg, color-mix(in oklch, var(--apa-plans-accent) 14%, transparent), transparent 55%); clip-path: inset(0 0 100% 0 round 14px); transition: clip-path .55s var(--apa-plans-ease); pointer-events: none; }
.apa-plans__plan:hover { box-shadow: inset 0 0 0 1px var(--apa-plans-line2); translate: 0 -2px; }
.apa-plans__plan input { position: absolute; opacity: 0; inset: 0; margin: 0; pointer-events: none; }
.apa-plans__plan:has(input:checked) { box-shadow: inset 0 0 0 1.5px var(--apa-plans-accent); background: color-mix(in oklch, var(--apa-plans-accent) 5%, var(--apa-plans-card)); }
.apa-plans__plan:has(input:checked)::before { clip-path: inset(0 0 0 0 round 14px); }
.apa-plans__plan:has(input:focus-visible) { outline: 2px solid var(--apa-plans-accent); outline-offset: 3px; }
.apa-plans__ptop { display: flex; align-items: center; justify-content: space-between; }
.apa-plans__pname { font-size: 15px; font-weight: 720; letter-spacing: -.01em; }
.apa-plans__ptop kbd { color: var(--apa-plans-muted); margin-right: 30px; }
.apa-plans__price { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
.apa-plans__num { font-size: clamp(26px, 1rem + 1.6cqi, 32px); font-weight: 760; letter-spacing: -.03em; line-height: 1; }
.apa-plans__price small { font-size: 12px; color: var(--apa-plans-muted); }
.apa-plans__pdesc { font-size: 12.5px; color: var(--apa-plans-muted); text-wrap: pretty; min-height: 2.9em; }
.apa-plans__plan ul { display: grid; gap: 5px; margin-top: 6px; padding-top: 10px; border-top: 1px solid var(--apa-plans-line); font-size: 12.5px; }
.apa-plans__plan li { display: flex; gap: 7px; align-items: baseline; }
.apa-plans__plan li::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--apa-plans-accent); flex: none; translate: 0 -2px; }
.apa-plans__badge { position: absolute; top: -9px; left: 14px; padding: 3px 8px; border-radius: 6px; background: var(--apa-plans-accent); color: var(--apa-plans-on); font-size: 10.5px; font-weight: 750; letter-spacing: .04em; text-transform: uppercase; scale: 0; transform-origin: 0 100%; transition: scale .45s var(--apa-plans-spring); }
.apa-plans__plan.is-rec .apa-plans__badge { scale: 1; }
.apa-plans__tick { position: absolute; top: 13px; right: 13px; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--apa-plans-accent); color: var(--apa-plans-on); scale: 0; transition: scale .45s var(--apa-plans-spring); }
.apa-plans__tick svg { width: 14px; height: 14px; stroke-width: 2.6; }
.apa-plans__plan:has(input:checked) .apa-plans__tick { scale: 1; }

.apa-plans__opts { display: grid; grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); gap: 12px; margin-top: 12px; }
.apa-plans__seats, .apa-plans__addons { padding: 14px 16px; border-radius: 14px; background: var(--apa-plans-card); box-shadow: inset 0 0 0 1px var(--apa-plans-line); }
.apa-plans__olabel { display: flex; justify-content: space-between; align-items: baseline; width: 100%; font-size: 12.5px; font-weight: 650; color: var(--apa-plans-muted); padding: 0; }
.apa-plans__addnote { font-weight: 500; font-size: 11.5px; color: var(--apa-plans-faint); }
.apa-plans__stepper { display: flex; align-items: center; gap: 6px; margin-top: 10px; }
.apa-plans__stepper button { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 10px; background: var(--apa-plans-line); transition: background-color .2s, scale .3s var(--apa-plans-spring); }
.apa-plans__stepper button:hover:not(:disabled) { background: var(--apa-plans-line2); }
.apa-plans__stepper button:active:not(:disabled) { scale: .92; }
.apa-plans__stepper button:disabled { opacity: .35; cursor: default; }
.apa-plans__seatn { min-width: 52px; text-align: center; font-size: 26px; font-weight: 760; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.apa-plans__seatnote { display: block; margin-top: 8px; font-size: 12px; color: var(--apa-plans-muted); text-wrap: pretty; }
.apa-plans__seatnote.is-warn { color: var(--apa-plans-accent); }
.apa-plans__addons { display: grid; gap: 4px; }
.apa-plans__addon { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 0; cursor: pointer; border-top: 1px solid var(--apa-plans-line); }
.apa-plans__addon:first-of-type { border-top: 0; }
.apa-plans__addon input { width: 17px; height: 17px; margin: 0; }
.apa-plans__addon b { display: block; font-size: 13.5px; font-weight: 620; }
.apa-plans__addon small { display: block; font-size: 12px; color: var(--apa-plans-muted); }
.apa-plans__aprice { font-size: 12.5px; color: var(--apa-plans-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.apa-plans__addon:has(input:checked) .apa-plans__aprice { color: var(--apa-plans-ink); font-weight: 600; }
.apa-plans__addons:has(input:disabled) .apa-plans__addon { opacity: .45; cursor: not-allowed; }

/* review */
.apa-plans__review { display: grid; margin-top: 22px; border-radius: 14px; background: var(--apa-plans-card); box-shadow: inset 0 0 0 1px var(--apa-plans-line); }
.apa-plans__review > div { display: grid; grid-template-columns: 92px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 12px 16px; }
.apa-plans__review > div + div { border-top: 1px solid var(--apa-plans-line); }
.apa-plans__review dt { font-size: 12px; font-weight: 650; color: var(--apa-plans-muted); text-transform: uppercase; letter-spacing: .06em; }
.apa-plans__review dd b { display: block; font-weight: 620; }
.apa-plans__review dd span { display: block; font-size: 12.5px; color: var(--apa-plans-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-plans__review button { font-size: 12.5px; font-weight: 650; color: var(--apa-plans-accent); padding: 6px 8px; border-radius: 7px; }
.apa-plans__review button:hover { background: var(--apa-plans-line); }
.apa-plans__time { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); margin-top: 22px; }
.apa-plans__time::before { content: ""; position: absolute; left: 6px; right: calc(33.3% - 6px); top: 6px; height: 2px; background: linear-gradient(90deg, var(--apa-plans-accent), var(--apa-plans-line2)); border-radius: 2px; }
.apa-plans__time li { position: relative; display: grid; gap: 2px; padding-top: 22px; font-size: 12.5px; }
.apa-plans__time li::before { content: ""; position: absolute; left: 0; top: 0; width: 14px; height: 14px; border-radius: 50%; background: var(--apa-plans-bg); box-shadow: inset 0 0 0 2px var(--apa-plans-line2); }
.apa-plans__time li:first-child::before { background: var(--apa-plans-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-plans-accent) 22%, transparent); }
.apa-plans__time b { font-weight: 650; }
.apa-plans__time span { font-variant-numeric: tabular-nums; color: var(--apa-plans-ink); font-size: 18px; font-weight: 720; letter-spacing: -.02em; }
.apa-plans__time small { color: var(--apa-plans-muted); font-size: 12px; font-variant-numeric: tabular-nums; }
.apa-plans__agree { display: flex; gap: 10px; align-items: flex-start; margin-top: 22px; font-size: 13.5px; color: var(--apa-plans-muted); cursor: pointer; text-wrap: pretty; }
.apa-plans__agree input { width: 17px; height: 17px; margin: 1px 0 0; flex: none; }
.apa-plans__agree:has(input:checked) { color: var(--apa-plans-ink); }
.apa-plans__agreeerr { margin-top: 8px; }
.apa-plans__step.is-shake .apa-plans__agree { animation: apa-plans-shake .44s cubic-bezier(.36, .07, .19, .97) both; }

/* done */
.apa-plans__todo { display: grid; gap: 8px; margin-top: 20px; }
.apa-plans__todo li { animation: apa-plans-rise .55s var(--apa-plans-ease) both; animation-delay: calc(240ms + var(--i) * 70ms); }
.apa-plans__todo label { display: grid; grid-template-columns: auto 1fr; gap: 12px; align-items: start; padding: 13px 15px; border-radius: 12px; background: var(--apa-plans-card); box-shadow: inset 0 0 0 1px var(--apa-plans-line); cursor: pointer; transition: box-shadow .25s, background-color .25s; }
.apa-plans__todo input { width: 18px; height: 18px; margin: 1px 0 0; }
.apa-plans__todo b { display: block; font-weight: 620; transition: color .25s; }
.apa-plans__todo small { display: block; font-size: 12.5px; color: var(--apa-plans-muted); }
.apa-plans__todo label:has(input:checked) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-plans-accent) 45%, transparent); }
.apa-plans__todo label:has(input:checked) b { color: var(--apa-plans-muted); text-decoration: line-through; text-decoration-color: var(--apa-plans-accent); }
.apa-plans__todostat { margin-top: 12px; font-size: 12.5px; color: var(--apa-plans-muted); font-variant-numeric: tabular-nums; }

/* step enter */
.apa-plans__step:not([hidden]) > :is(.apa-plans__kicker, .apa-plans__h, .apa-plans__sub, .apa-plans__planhead) { animation: apa-plans-rise .5s var(--apa-plans-ease) both; }
.apa-plans__step:not([hidden]) > .apa-plans__h { animation-delay: 40ms; }
.apa-plans__step:not([hidden]) > .apa-plans__sub { animation-delay: 80ms; }

/* ---------- footer ---------- */
.apa-plans__foot { display: flex; align-items: center; gap: 12px; padding: 12px clamp(18px, 3cqi, 32px) 16px; border-top: 1px solid var(--apa-plans-line); }
.apa-plans__back { display: inline-flex; align-items: center; gap: 4px; height: 40px; padding: 0 12px 0 8px; border-radius: 10px; font-weight: 600; color: var(--apa-plans-muted); transition: color .2s, background-color .2s; }
.apa-plans__back:hover { color: var(--apa-plans-ink); background: var(--apa-plans-line); }
.apa-plans[data-step="1"] .apa-plans__back, .apa-plans[data-step="4"] .apa-plans__back { visibility: hidden; }
.apa-plans__hint { flex: 1; display: flex; justify-content: center; align-items: center; gap: 5px; flex-wrap: wrap; font-size: 11.5px; color: var(--apa-plans-faint); }
.apa-plans__hint i { font-style: normal; margin-right: 8px; }
.apa-plans__mini { display: none; flex: 1; align-items: center; justify-content: center; gap: 8px; height: 40px; border-radius: 10px; font-size: 12.5px; color: var(--apa-plans-muted); background: var(--apa-plans-line); }
.apa-plans__miniamt { color: var(--apa-plans-ink); font-weight: 700; font-size: 14px; }
.apa-plans__next {
  margin-left: auto;
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 10px; height: 42px; padding: 0 16px 0 18px; border-radius: 11px;
  background: var(--apa-plans-accent); color: var(--apa-plans-on); font-weight: 700; font-size: 14px;
  box-shadow: 0 10px 26px -14px var(--apa-plans-accent);
  transition: scale .3s var(--apa-plans-spring), filter .2s, background-color .3s;
}
.apa-plans__next:hover { filter: brightness(1.06); }
.apa-plans__next:active { scale: .97; }
.apa-plans__next[aria-busy="true"]::after { content: ""; position: absolute; inset: auto 0 0; height: 3px; background: var(--apa-plans-on); transform-origin: 0 50%; animation: apa-plans-fill 1s var(--apa-plans-ease) both; }
.apa-plans[data-step="4"] .apa-plans__next { background: var(--apa-plans-ink); box-shadow: none; }

/* ---------- receipt pane ---------- */
.apa-plans__printer {
  display: flex; align-items: center; gap: 10px; margin: 18px 18px 0; padding: 0 14px; height: 44px; border-radius: 12px 12px 4px 4px;
  background: color-mix(in oklch, var(--apa-plans-ink) 7%, var(--apa-plans-side)); box-shadow: inset 0 0 0 1px var(--apa-plans-line), inset 0 -8px 0 -4px color-mix(in oklch, black 45%, transparent);
  font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--apa-plans-muted);
}
.apa-plans__led { width: 8px; height: 8px; border-radius: 50%; background: var(--apa-plans-accent); box-shadow: 0 0 10px var(--apa-plans-accent); }
.apa-plans__side.is-printing .apa-plans__led { animation: apa-plans-blink .18s steps(2) 4; }
.apa-plans__close { display: none; margin-left: auto; width: 32px; height: 32px; place-items: center; border-radius: 8px; color: var(--apa-plans-ink); }
.apa-plans__slot { position: relative; min-height: 0; overflow: auto; padding: 0 30px 26px; margin-top: -6px; scrollbar-width: none; overscroll-behavior: contain; }
.apa-plans__slot::before { content: ""; position: sticky; top: 0; z-index: 2; display: block; height: 8px; margin: 0 -12px; background: linear-gradient(var(--apa-plans-side), transparent); }
.apa-plans__paper {
  --z: 9px;
  position: relative; padding: 18px 18px calc(22px + var(--z)); color: var(--apa-plans-print); background: var(--apa-plans-paper);
  font: 400 12px/1.5 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  mask: conic-gradient(from -45deg at 50% 100%, #0000, #000 1deg 89deg, #0000 90deg) 50% 100% / calc(var(--z) * 2) 100%;
  filter: drop-shadow(0 18px 18px color-mix(in oklch, black 35%, transparent));
  transform-origin: 50% 0;
}
.apa-plans__side.is-printing .apa-plans__paper { animation: apa-plans-feed .5s var(--apa-plans-ease); }
.apa-plans__rhead { display: flex; justify-content: space-between; align-items: center; font-size: 10.5px; letter-spacing: .14em; text-transform: uppercase; }
.apa-plans__rlogo { display: inline-flex; align-items: center; gap: 6px; font-weight: 800; font-size: 13px; letter-spacing: .2em; }
.apa-plans__rlogo svg { width: 18px; height: 18px; stroke-width: 2; }
.apa-plans__rmeta { margin-top: 14px; display: grid; }
.apa-plans__rmeta b { font-weight: 700; font-size: 12.5px; }
.apa-plans__rmeta2 { display: flex; justify-content: space-between; margin-top: 6px; font-size: 11px; opacity: .8; }
.apa-plans__paper hr { border: 0; border-top: 1.5px dashed color-mix(in oklch, var(--apa-plans-print) 45%, transparent); margin: 12px 0; }
.apa-plans__paper hr.apa-plans__dbl { border-top: 3px double color-mix(in oklch, var(--apa-plans-print) 65%, transparent); }
.apa-plans__rl { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows .55s var(--apa-plans-ease), opacity .35s; }
.apa-plans__rl > div { min-height: 0; overflow: hidden; }
.apa-plans__rl[data-on] { grid-template-rows: 1fr; opacity: 1; }
.apa-plans__rl[data-on] > div { padding-bottom: 8px; }
.apa-plans__rlines .apa-plans__rl[data-on] > div > :first-child { animation: apa-plans-ink .7s var(--apa-plans-ease); }
.apa-plans__rrow { display: flex; align-items: baseline; gap: 8px; }
.apa-plans__rrow > span:first-child { display: flex; gap: 6px; align-items: baseline; flex: 1; min-width: 0; }
.apa-plans__rrow > span:first-child::after { content: ""; flex: 1; border-bottom: 1px dotted color-mix(in oklch, var(--apa-plans-print) 40%, transparent); translate: 0 -3px; min-width: 12px; }
.apa-plans__rrow small { font-size: 10.5px; opacity: .7; white-space: nowrap; }
.apa-plans__rcalc { font-size: 11px; opacity: .65; }
.apa-plans__rsub { font-weight: 700; }
.apa-plans__rmuted { opacity: .65; font-size: 11px; margin-top: 2px; }
.apa-plans__rdue { font-size: 15px; font-weight: 800; letter-spacing: -.01em; margin-bottom: 4px; }
.apa-plans__save { display: block; width: 100%; margin-top: 6px; padding: 6px 8px; border-radius: 6px; text-align: left; font: 600 11px/1.35 ui-monospace, Menlo, monospace; color: var(--apa-plans-print); background: color-mix(in oklch, var(--apa-plans-accent) 55%, var(--apa-plans-paper)); }
.apa-plans__save:disabled { cursor: default; }
.apa-plans__save:not(:disabled):hover { background: color-mix(in oklch, var(--apa-plans-accent) 80%, var(--apa-plans-paper)); }
.apa-plans__barcode { height: 34px; margin: 16px 6px 6px; background: repeating-linear-gradient(90deg, var(--apa-plans-print) 0 2px, transparent 2px 4px, var(--apa-plans-print) 4px 5px, transparent 5px 8px, var(--apa-plans-print) 8px 11px, transparent 11px 12px, var(--apa-plans-print) 12px 13px, transparent 13px 16px); opacity: .85; }
.apa-plans__thanks { font-size: 11px; text-align: center; text-wrap: balance; opacity: .75; }
.apa-plans__stamp {
  position: absolute; right: 12px; bottom: 112px; display: grid; background: color-mix(in oklch, var(--apa-plans-paper) 82%, transparent); justify-items: center; gap: 2px; padding: 8px 12px; border-radius: 8px;
  border: 3px double color-mix(in oklch, var(--apa-plans-bg) 80%, var(--apa-plans-accent)); color: color-mix(in oklch, var(--apa-plans-bg) 80%, var(--apa-plans-accent));
  font: 800 15px/1 system-ui, sans-serif; letter-spacing: .08em; text-transform: uppercase; rotate: -11deg; mix-blend-mode: multiply;
  opacity: 0; scale: 2.4; filter: blur(4px); pointer-events: none;
  transition: opacity .18s, scale .42s cubic-bezier(.3, 1.4, .5, 1), filter .3s;
}
.apa-plans__stamp span { font: 700 10px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; }
.apa-plans[data-step="4"] .apa-plans__stamp { opacity: .9; scale: 1; filter: none; transition-delay: .25s; }

/* odometer */
.apa-plans__amt { white-space: nowrap; }
.apa-plans__odo { display: inline-flex; line-height: 1.2; height: 1.2em; overflow: hidden; vertical-align: bottom; }
.apa-plans__odo > span { display: block; height: 1.2em; }
.apa-plans__dg > span { display: flex; flex-direction: column; translate: 0 calc(var(--d, 0) * -1.2em); transition: translate .8s var(--apa-plans-spring); transition-delay: calc(var(--i, 0) * 32ms); }
.apa-plans__dg > span > span { display: block; height: 1.2em; }
.apa-plans__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

.apa-plans__scrim { position: absolute; inset: 0; z-index: 4; background: color-mix(in oklch, black 45%, transparent); transition: opacity .3s; }
@starting-style { .apa-plans__scrim { opacity: 0; } }

/* ---------- keyframes ---------- */
@keyframes apa-plans-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes apa-plans-shake { 15%, 85% { translate: -2px 0; } 30%, 70% { translate: 5px 0; } 45%, 55% { translate: -7px 0; } }
@keyframes apa-plans-fill { from { scale: 0 1; } to { scale: 1 1; } }
@keyframes apa-plans-blink { 50% { opacity: .25; } }
@keyframes apa-plans-feed { 0% { translate: 0 -10px; } 60% { translate: 0 2px; } 100% { translate: 0 0; } }
@keyframes apa-plans-ink { from { opacity: 0; filter: blur(2px); clip-path: inset(0 100% 0 0); } to { opacity: 1; filter: none; clip-path: inset(0 0 0 0); } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-plans__app { grid-template-columns: minmax(0, 1fr) 300px; }
  .apa-plans__slot { padding: 0 18px 22px; }
  .apa-plans__printer { margin: 14px 12px 0; }
  .apa-plans__plans { grid-template-columns: 1fr; }
  .apa-plans__plan { grid-template-columns: minmax(0, 1fr) auto; column-gap: 14px; }
  .apa-plans__plan :is(ul, .apa-plans__pdesc) { grid-column: 1 / -1; }
  .apa-plans__plan ul { grid-template-columns: repeat(3, auto); justify-content: start; gap: 4px 14px; }
  .apa-plans__pdesc { min-height: 0; }
  .apa-plans__ptop { justify-content: flex-start; gap: 8px; }
  .apa-plans__ptop kbd { margin-right: 0; }
  .apa-plans__opts { grid-template-columns: 1fr; }
  .apa-plans__hint { display: none; }
  .apa-plans__steps span { display: none; }
  .apa-plans__steps button { padding: 0 4px; }
}
/* ---------- container: single pane, receipt as a sheet ---------- */
@container (max-width: 759px) {
  .apa-plans__app { grid-template: "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-plans__side {
    position: absolute; z-index: 5; left: 0; right: 0; bottom: 0; height: 86%; border: 0; border-radius: 18px 18px 0 0;
    translate: 0 102%; visibility: hidden; transition: translate .5s var(--apa-plans-ease), visibility 0s .5s;
    box-shadow: 0 -20px 50px -20px black;
  }
  .apa-plans[data-sheet] .apa-plans__side { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apa-plans__close { display: grid; }
  .apa-plans__hint { display: none; }
  .apa-plans__mini { display: inline-flex; }
  .apa-plans[data-step="4"] .apa-plans__mini { visibility: hidden; }
  .apa-plans__steps span { display: none; }
  .apa-plans__steps button { padding: 0 2px; }
  .apa-plans__plans { grid-template-columns: 1fr; }
  .apa-plans__plan { grid-template-columns: minmax(0, 1fr) auto; column-gap: 14px; }
  .apa-plans__plan :is(ul, .apa-plans__pdesc) { grid-column: 1 / -1; }
  .apa-plans__plan ul { display: none; }
  .apa-plans__pdesc { min-height: 0; }
  .apa-plans__ptop { justify-content: flex-start; gap: 8px; }
  .apa-plans__ptop kbd { margin-right: 0; }
  .apa-plans__opts { grid-template-columns: 1fr; }
}
@container (max-width: 520px) {
  .apa-plans__grid { grid-template-columns: 1fr; }
  .apa-plans__head { padding-top: 14px; }
  .apa-plans__review > div { grid-template-columns: minmax(0, 1fr) auto; }
  .apa-plans__review dt { grid-column: 1 / -1; margin-bottom: -8px; }
  .apa-plans__time span { font-size: 15px; }
  .apa-plans__back { padding: 0 6px; font-size: 0; }
  .apa-plans__back svg { width: 20px; height: 20px; }
  .apa-plans__minil { display: none; }
  .apa-plans__plan .apa-plans__ptop kbd { display: none; }
  .apa-plans__bill { width: 100%; grid-auto-columns: 1fr; }
  .apa-plans__bill span { justify-content: center; }
}

/* ---------- reduced motion: no rolling, no stamp slam ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-plans *, .apa-plans *::before, .apa-plans *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
  .apa-plans__stamp { filter: none; scale: 1; }
}

