// Presentational only: no account is created and no payment details are asked for or sent.
root.addEventListener('submit', (e) => e.preventDefault());
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);

const form = $('.apa-plans__body');
const E = form.elements;
const side = $('.apa-plans__side');
const PLANS = {
  plot: { name: 'Plot', month: 0, year: 0, min: 1, max: 2 },
  acre: { name: 'Acre', month: 14, year: 12, min: 1, max: 100 },
  estate: { name: 'Estate', month: 29, year: 24, min: 3, max: 500 },
};
const ADDONS = { imagery: { name: 'Satellite imagery', month: 35, year: 29 }, soil: { name: 'Soil lab sync', month: 9, year: 7 } };
const ORDER = ['plot', 'acre', 'estate'];
const S = { step: 1, max: 1, plan: null, picked: false, bill: 'year', seats: 6, sheet: false, busy: false, note: '' };

const usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
const usd0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const int = new Intl.NumberFormat('en-US');
const now = new Date();
const addDays = (n) => new Date(now.getFullYear(), now.getMonth(), now.getDate() + n);
const short = (d) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const long = (d) => d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const T1 = addDays(11), T2 = addDays(14);
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const emailOk = (v) => /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v);
const bind = (k, v) => $$(`[data-bind="${k}"]`).forEach((el) => { el.textContent = v; });

const acres = () => Math.max(0, Number(E.acres.value) || 0);
const rec = () => { const a = acres(); return a < 150 ? 'plot' : a <= 2500 ? 'acre' : 'estate'; };
const plan = () => S.plan || rec();

/* ---------- odometer: one rolling column per digit, staggered from the right ---------- */
function odo(el, text) {
  if (el.dataset.v === text) return;
