  const adds = key === 'plot' ? [] : Object.keys(ADDONS).filter((k) => E[k].checked);
  const planAmt = S.seats * p[S.bill] * months;
  const addAmts = {}; adds.forEach((k) => { addAmts[k] = ADDONS[k][S.bill] * months; });
