  odo($('[data-amt="due"]'), usd.format(0));
  odo($('[data-amt="first"]'), usd.format(c.sub));
  odo($('[data-amt="mini"]'), usd.format(c.sub));
  bind('t2long', long(T2)); bind('stamp', long(now).toUpperCase());
  bind('thanks', c.key === 'plot' ? 'Plot is free for good. Upgrade whenever the farm grows.' : `Cancel any time before ${short(T2)} and you pay nothing.`);

  // review + done
  bind('farmmeta', `${int.format(acres())} acres · ${E.op.value}`);
  bind('plan', `${c.p.name} · ${S.seats} seat${S.seats > 1 ? 's' : ''}`);
  bind('planmeta', [c.key === 'plot' ? 'Free' : S.bill === 'year' ? 'Billed annually' : 'Billed monthly', ...c.adds.map((k) => ADDONS[k].name)].join(' · '));
  bind('t0', short(now)); bind('t1', short(T1)); bind('t2', short(T2));
  bind('t2amt', c.key === 'plot' ? 'Nothing — Plot is free' : `${usd.format(c.sub)} ${S.bill === 'year' ? 'for the year' : 'for the month'}`);
  bind('planname', c.p.name);
  bind('seats', `${S.seats} seat${S.seats > 1 ? 's' : ''}`);
