    if (!emailOk(E.email.value.trim())) errs.email = E.email.value.trim() ? 'Check the address — it needs an @ and a domain.' : 'Add your work email.';
    if (E.farm.value.trim().length < 2) errs.farm = 'Name your farm or business.';
    if (!(Number(E.acres.value) >= 1)) errs.acres = 'Roughly is fine.';
    ['name', 'email', 'farm', 'acres'].forEach((k) => setErr(k, errs[k]));
