/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const goBtn = e.target.closest('[data-go]');
  if (goBtn && !goBtn.disabled) { go(Number(goBtn.dataset.go)); return; }
  const a = e.target.closest('[data-act]'); if (!a) return;
  switch (a.dataset.act) {
    case 'next': next(); break;
    case 'back': if (S.step > 1 && S.step < 4) go(S.step - 1); break;
    case 'seat-': seat(-1); break;
    case 'seat+': seat(1); break;
    case 'annual': setBill('year'); break;
    case 'sheet': toggleSheet(!S.sheet); break;
