  const t = e.target;
  const typing = t.matches && t.matches('input:not([type="radio"]):not([type="checkbox"]), select, textarea');
  if (e.key === 'Enter' && !e.metaKey && !e.ctrlKey && !e.altKey && !e.shiftKey) {
