/* Airmail magic link. Re-theme with --apa-magic-sky, -paper, -ink, -red and -blue. */
@property --apa-magic-cool { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@property --apa-magic-left { syntax: "<number>"; inherits: true; initial-value: 1; }

.apa-magic {
  --apa-magic-sky: oklch(0.935 0.028 232);
  --apa-magic-paper: oklch(0.986 0.009 88);
  --apa-magic-ink: oklch(0.28 0.055 258);
  --apa-magic-red: oklch(0.6 0.2 27);
  --apa-magic-blue: oklch(0.5 0.15 256);

  --apa-magic-paper2: color-mix(in oklch, var(--apa-magic-paper) 90%, var(--apa-magic-ink));
  --apa-magic-muted: color-mix(in oklch, var(--apa-magic-ink) 64%, var(--apa-magic-paper));
  --apa-magic-faint: color-mix(in oklch, var(--apa-magic-ink) 42%, var(--apa-magic-paper));
  --apa-magic-rule: color-mix(in oklch, var(--apa-magic-ink) 13%, transparent);
  --apa-magic-rule2: color-mix(in oklch, var(--apa-magic-ink) 22%, transparent);
  --apa-magic-stripes: repeating-linear-gradient(-45deg, var(--apa-magic-red) 0 12px, var(--apa-magic-paper) 12px 18px, var(--apa-magic-blue) 18px 30px, var(--apa-magic-paper) 30px 36px);
  --apa-magic-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-magic-spring: linear(0, 0.08 4%, 0.3 9%, 0.72 17%, 0.97 24%, 1.07 30%, 1.08 36%, 1.05 44%, 1.01 55%, 0.995 70%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-magic-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-magic-sky);
  color: var(--apa-magic-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apa-magic-red);
  outline: none;
}
:where(.apa-magic) *, :where(.apa-magic) *::before, :where(.apa-magic) *::after { box-sizing: border-box; }
:where(.apa-magic) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-magic) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-magic) :is(p, h1, h2, h3, ul, dl, dd) { margin: 0; padding: 0; }
:where(.apa-magic) ul { list-style: none; }
:where(.apa-magic) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-magic) :focus-visible { outline: 2px solid var(--apa-magic-red); outline-offset: 2px; }
:where(.apa-magic) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 11%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 16%, transparent);
}
.apa-magic [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-magic__app { display: grid; height: 100%; grid-template: "main side" minmax(0, 1fr) / minmax(0, 1fr) 384px; }
.apa-magic__tabs { display: none; }
.apa-magic__main { grid-area: main; position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.apa-magic__side { grid-area: side; display: grid; place-items: center; padding: 16px; min-height: 0; background: color-mix(in oklch, var(--apa-magic-sky) 88%, var(--apa-magic-ink)); }

/* faint flight route behind the stage */
.apa-magic__main::before {
  content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .5;
  background: radial-gradient(circle at 85% 20%, color-mix(in oklch, var(--apa-magic-paper) 70%, transparent) 0 22%, transparent 45%),
    repeating-linear-gradient(0deg, transparent 0 31px, color-mix(in oklch, var(--apa-magic-ink) 5%, transparent) 31px 32px);
}

.apa-magic__brand { position: relative; display: flex; align-items: baseline; gap: 8px; padding: 20px clamp(18px, 3.4cqi, 34px) 0; }
.apa-magic__brand svg { width: 22px; height: 22px; color: var(--apa-magic-red); align-self: center; stroke-width: 1.9; }
.apa-magic__brand span { font-weight: 800; font-size: 17px; letter-spacing: -.03em; }
.apa-magic__brand small { font: 500 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em; text-transform: uppercase; color: var(--apa-magic-muted); }

.apa-magic__stage { position: relative; display: grid; place-items: center; min-height: 0; overflow: auto; padding: 16px clamp(16px, 4cqi, 44px); scrollbar-width: thin; overscroll-behavior: contain; }
.apa-magic__stage > section { width: min(100%, 448px); }

/* ---------- letter ---------- */
.apa-magic__letter {
  position: relative; padding: 30px 30px 24px; border: 8px solid transparent; border-radius: 5px;
  background: linear-gradient(var(--apa-magic-paper), var(--apa-magic-paper)) padding-box, var(--apa-magic-stripes) border-box;
  box-shadow: 0 34px 60px -38px color-mix(in oklch, var(--apa-magic-ink) 75%, transparent), 0 2px 0 color-mix(in oklch, var(--apa-magic-ink) 8%, transparent);
  animation: apa-magic-in .6s var(--apa-magic-ease) both;
}
.apa-magic__stamp {
  position: absolute; top: 16px; right: 16px; width: 60px; height: 70px; padding: 5px; rotate: 4deg;
  background: radial-gradient(circle, var(--apa-magic-paper) 2.4px, transparent 2.9px) -4px -4px / 8px 8px, oklch(0.95 0.06 96);
  display: grid;
}
.apa-magic__stamp::before { content: ""; position: absolute; inset: 5px; border: 1.5px solid var(--apa-magic-red); background: oklch(0.95 0.06 96); }
.apa-magic__stamp svg { position: relative; width: 100%; height: 100%; color: var(--apa-magic-blue); stroke-width: 2.2; }
.apa-magic__stamp b { position: absolute; left: 9px; top: 8px; font: 800 11px/1 system-ui, sans-serif; color: var(--apa-magic-red); }
.apa-magic__par { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: var(--apa-magic-red); }
.apa-magic__h { margin-top: 12px; font-size: clamp(26px, 1rem + 1.9cqi, 36px); line-height: 1.04; font-weight: 790; letter-spacing: -.038em; text-wrap: balance; outline: none; max-width: 16ch; }
.apa-magic__p { margin-top: 10px; color: var(--apa-magic-muted); font-size: 14.5px; text-wrap: pretty; max-width: 40ch; }
.apa-magic__p b { color: var(--apa-magic-ink); font-weight: 650; overflow-wrap: anywhere; }

.apa-magic__form { display: grid; gap: 8px; margin-top: 22px; }
.apa-magic__lbl { font-size: 12.5px; font-weight: 640; }
.apa-magic__in {
  width: 100%; height: 46px; padding: 0 14px; border-radius: 9px; border: 1.5px solid var(--apa-magic-rule2); background: white; font-size: 15px; outline: none;
  transition: border-color .2s, box-shadow .25s var(--apa-magic-ease);
}
.apa-magic__in:hover { border-color: color-mix(in oklch, var(--apa-magic-ink) 38%, transparent); }
.apa-magic__in:focus { border-color: var(--apa-magic-blue); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-magic-blue) 16%, transparent); }
.apa-magic__in[aria-invalid="true"] { border-color: var(--apa-magic-red); }
.apa-magic__pwwrap { display: grid; grid-template-rows: 0fr; opacity: 0; visibility: hidden; margin-top: -8px; transition: grid-template-rows .45s var(--apa-magic-ease), opacity .3s, margin .45s var(--apa-magic-ease), visibility 0s .45s; }
.apa-magic__pwwrap > div { min-height: 0; overflow: hidden; padding: 2px; margin: -2px; }
.apa-magic[data-pw] .apa-magic__pwwrap { grid-template-rows: 1fr; opacity: 1; visibility: visible; margin-top: 0; transition-delay: 0s; }
.apa-magic__err { font-size: 12.5px; color: var(--apa-magic-red); font-weight: 550; }
.apa-magic__err:empty { display: none; }
