/* ---------- device + inbox ---------- */
.apa-magic__device {
  position: relative; width: min(100%, 336px); height: min(100%, 644px); padding: 9px; border-radius: 40px;
  background: var(--apa-magic-ink); box-shadow: 0 40px 60px -40px color-mix(in oklch, var(--apa-magic-ink) 90%, transparent), inset 0 0 0 2px color-mix(in oklch, white 12%, transparent);
