.apa-magic__mrow {
  position: relative; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 1px 10px; width: 100%; padding: 11px 16px 11px 14px; text-align: left;
  transition: background-color .5s;
}
.apa-magic__mrow:hover { background: color-mix(in oklch, var(--apa-magic-sky) 50%, white); }
.apa-magic__mrow:focus-visible { outline-offset: -2px; }
.apa-magic__mrow.is-new { animation: apa-magic-new 2.4s ease-out; }
.apa-magic__mav { grid-row: span 3; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; color: white; font: 700 12px/1 system-ui, sans-serif; background: var(--c, var(--apa-magic-blue)); }
.apa-magic__mav svg { width: 18px; height: 18px; stroke-width: 2; }
.apa-magic__mfrom { font-size: 13.5px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-magic__mtime { font-size: 11.5px; color: var(--apa-magic-faint); font-variant-numeric: tabular-nums; }
.apa-magic__msub { grid-column: 2 / -1; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-magic__mpre { grid-column: 2 / -1; font-size: 12px; color: var(--apa-magic-muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.apa-magic__mrow[data-unread] .apa-magic__mfrom, .apa-magic__mrow[data-unread] .apa-magic__msub { font-weight: 720; }
.apa-magic__mrow[data-unread]::before { content: ""; position: absolute; left: 5px; top: 24px; width: 7px; height: 7px; border-radius: 50%; background: var(--apa-magic-blue); }
.apa-magic__mrow[data-state="old"] .apa-magic__msub::after, .apa-magic__mrow[data-state="used"] .apa-magic__msub::after { content: " · expired"; color: var(--apa-magic-faint); font-weight: 500; }
.apa-magic__mrow[data-state="used"] .apa-magic__msub::after { content: " · used"; }
.apa-magic__simnote { padding: 10px 16px 14px; font-size: 11px; color: var(--apa-magic-faint); text-align: center; border-top: 1px solid var(--apa-magic-rule); }

.apa-magic__banner {
  position: absolute; z-index: 8; left: 16px; right: 16px; top: 44px; display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 16px; cursor: pointer;
  background: color-mix(in oklch, var(--apa-magic-paper) 92%, var(--apa-magic-ink)); box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--apa-magic-ink) 70%, transparent), 0 0 0 1px var(--apa-magic-rule);
  font-size: 12.5px; transition: translate .55s var(--apa-magic-spring), opacity .3s;
}
@starting-style { .apa-magic__banner { translate: 0 -120%; opacity: 0; } }
.apa-magic__banner b { display: block; }
.apa-magic__banner small { color: var(--apa-magic-muted); font-size: 11.5px; }
.apa-magic__bicon { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; background: var(--apa-magic-red); color: white; }

.apa-magic__rhead { padding: 8px 10px; border-bottom: 1px solid var(--apa-magic-rule); }
.apa-magic__rback { display: inline-flex; align-items: center; gap: 2px; height: 32px; padding: 0 10px 0 4px; border-radius: 8px; color: var(--apa-magic-blue); font-weight: 600; font-size: 13.5px; }
.apa-magic__rback:hover { background: color-mix(in oklch, var(--apa-magic-blue) 8%, transparent); }
.apa-magic__mail { overflow: auto; padding: 16px 18px 22px; scrollbar-width: none; font-size: 13px; }
.apa-magic__mail h3 { font-size: 18px; font-weight: 760; letter-spacing: -.02em; text-wrap: balance; }
.apa-magic__mmeta { display: grid; grid-template-columns: 34px 1fr; gap: 0 10px; align-items: center; margin-top: 12px; padding-bottom: 14px; border-bottom: 1px solid var(--apa-magic-rule); font-size: 12px; color: var(--apa-magic-muted); }
.apa-magic__mmeta .apa-magic__mav { grid-row: span 2; }
