.apa-magic__mbody { display: grid; gap: 12px; margin-top: 16px; color: color-mix(in oklch, var(--apa-magic-ink) 85%, white); text-wrap: pretty; }
.apa-magic__mlogo { display: flex; align-items: center; gap: 6px; font-weight: 800; letter-spacing: -.02em; color: var(--apa-magic-ink); }
