.apa-magic__mcode { font: 500 11.5px/1.4 ui-monospace, Menlo, monospace; color: var(--apa-magic-muted); overflow-wrap: anywhere; }
.apa-magic__mstate { justify-self: start; display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 650; background: color-mix(in oklch, var(--apa-magic-blue) 10%, white); color: var(--apa-magic-blue); }
.apa-magic__mstate[data-s="old"], .apa-magic__mstate[data-s="expired"] { background: color-mix(in oklch, var(--apa-magic-red) 10%, white); color: var(--apa-magic-red); }
