.apa-magic__mfoot { font-size: 11.5px; color: var(--apa-magic-faint); border-top: 1px solid var(--apa-magic-rule); padding-top: 12px; }

.apa-magic__foot { position: relative; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 4px; padding: 10px 16px 16px; font-size: 11.5px; color: var(--apa-magic-faint); }
.apa-magic__foot kbd:not(:first-child) { margin-left: 8px; }

/* ---------- keyframes ---------- */
@keyframes apa-magic-in { from { opacity: 0; translate: 0 12px; } }
@keyframes apa-magic-shake { 15%, 85% { translate: -2px 0; } 30%, 70% { translate: 5px 0; } 45%, 55% { translate: -7px 0; } }
@keyframes apa-magic-float { from { translate: 0 0; rotate: -3deg; } to { translate: 0 -6px; rotate: -1deg; } }
@keyframes apa-magic-pop { from { scale: .4; opacity: 0; } }
@keyframes apa-magic-draw { to { stroke-dashoffset: 0; } }
@keyframes apa-magic-new { 0%, 30% { background-color: oklch(0.96 0.07 95); } 100% { background-color: transparent; } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-magic__app { grid-template-columns: minmax(0, 1fr) 316px; }
  .apa-magic__side { padding: 12px; }
  .apa-magic__foot { display: none; }
  .apa-magic__letter { padding: 26px 22px 20px; }
}
/* ---------- container: single pane with tabs ---------- */
@container (max-width: 759px) {
  .apa-magic__app { grid-template: "tabs" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-magic__tabs { grid-area: tabs; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 12px 12px 0; padding: 4px; border-radius: 12px; background: color-mix(in oklch, var(--apa-magic-ink) 7%, transparent); }
  .apa-magic__tabs button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 34px; border-radius: 9px; font-weight: 640; font-size: 13px; color: var(--apa-magic-muted); }
  .apa-magic__tabs button[aria-selected="true"] { background: var(--apa-magic-paper); color: var(--apa-magic-ink); box-shadow: 0 1px 3px var(--apa-magic-rule2); }
  .apa-magic__badge { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: var(--apa-magic-red); color: white; font-size: 11px; font-variant-numeric: tabular-nums; animation: apa-magic-pop .5s var(--apa-magic-spring); }
  .apa-magic__side { grid-area: main; background: none; padding: 12px; }
  .apa-magic[data-tab="signin"] .apa-magic__side { display: none; }
  .apa-magic[data-tab="inbox"] .apa-magic__main { display: none; }
  .apa-magic__device { width: min(100%, 400px); height: 100%; }
  .apa-magic__foot { display: none; }
  .apa-magic__brand { padding-top: 14px; }
  .apa-magic__stage { place-items: start center; }
  .apa-magic__toast { display: flex; }
}
@container (max-width: 460px) {
  .apa-magic__letter { padding: 22px 18px 18px; border-width: 6px; }
  .apa-magic__stamp { width: 46px; height: 54px; top: 10px; right: 10px; }
  .apa-magic__brand small { display: none; }
  .apa-magic__stage { padding: 12px; }
  .apa-magic__btn kbd, .apa-magic__resend kbd, .apa-magic__ghost kbd { display: none; }
  .apa-magic__device { padding: 6px; border-radius: 30px; }
  .apa-magic__device::before { inset: 6px; border-radius: 25px; }
}

/* ---------- reduced motion: no flight, no float ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-magic *, .apa-magic *::before, .apa-magic *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
  .apa-magic__seal svg { stroke-dashoffset: 0; }
  .apa-magic__sealed { animation: none; rotate: -2deg; }
}

