/* Authenticator setup. Re-theme with --apa-2fa-bg, -ink, -accent and -ok. */
@property --apa-2fa-r { syntax: "<percentage>"; inherits: true; initial-value: 0%; }
@property --apa-2fa-t { syntax: "<angle>"; inherits: false; initial-value: 360deg; }

.apa-2fa {
  --apa-2fa-bg: oklch(0.185 0.022 205);
  --apa-2fa-ink: oklch(0.94 0.016 190);
  --apa-2fa-accent: oklch(0.83 0.15 76);
  --apa-2fa-ok: oklch(0.79 0.14 160);

  --apa-2fa-bad: oklch(0.7 0.17 28);
  --apa-2fa-panel: color-mix(in oklch, var(--apa-2fa-ink) 4%, var(--apa-2fa-bg));
  --apa-2fa-deep: color-mix(in oklch, var(--apa-2fa-bg) 75%, black);
  --apa-2fa-line: color-mix(in oklch, var(--apa-2fa-ink) 11%, transparent);
  --apa-2fa-line2: color-mix(in oklch, var(--apa-2fa-ink) 20%, transparent);
  --apa-2fa-muted: color-mix(in oklch, var(--apa-2fa-ink) 62%, var(--apa-2fa-bg));
  --apa-2fa-faint: color-mix(in oklch, var(--apa-2fa-ink) 40%, var(--apa-2fa-bg));
  --apa-2fa-on: color-mix(in oklch, var(--apa-2fa-accent) 22%, black);
  --apa-2fa-mono: ui-monospace, Menlo, monospace;
  --apa-2fa-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-2fa-spring: linear(0, 0.08 4%, 0.3 9%, 0.7 16%, 0.96 23%, 1.07 29%, 1.09 35%, 1.05 43%, 1.01 54%, 0.995 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-2fa-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-2fa-bg);
  color: var(--apa-2fa-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apa-2fa-accent);
  outline: none;
}
:where(.apa-2fa) *, :where(.apa-2fa) *::before, :where(.apa-2fa) *::after { box-sizing: border-box; }
:where(.apa-2fa) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-2fa) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-2fa) :is(p, h2, ol, ul, dl, dd, figure) { margin: 0; padding: 0; }
:where(.apa-2fa) :is(ol, ul) { list-style: none; }
:where(.apa-2fa) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-2fa) :focus-visible { outline: 2px solid var(--apa-2fa-accent); outline-offset: 2px; }
:where(.apa-2fa) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 var(--apa-2fa-mono); color: inherit;
  background: color-mix(in oklch, currentColor 12%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 18%, transparent);
}
.apa-2fa [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-2fa__app { display: grid; height: 100%; grid-template: "rail main auth" minmax(0, 1fr) / 214px minmax(0, 1fr) 340px; }
.apa-2fa__tabs { display: none; }
.apa-2fa__rail { grid-area: rail; display: grid; grid-template-rows: auto 1fr auto; gap: 18px; padding: 22px 16px 16px 20px; border-right: 1px solid var(--apa-2fa-line); }
.apa-2fa__main { grid-area: main; display: grid; grid-template-rows: minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.apa-2fa__auth { grid-area: auth; position: relative; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; background: var(--apa-2fa-deep); border-left: 1px solid var(--apa-2fa-line); }

/* ---------- rail ---------- */
.apa-2fa__crumb { font: 500 11px/1.3 var(--apa-2fa-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--apa-2fa-faint); }
.apa-2fa__crumb span { color: var(--apa-2fa-accent); font-weight: 700; }
.apa-2fa__steps { position: relative; display: grid; align-content: start; align-self: start; gap: 4px; }
.apa-2fa__steps::before { content: ""; position: absolute; left: 15px; top: 18px; bottom: 18px; width: 2px; background: var(--apa-2fa-line); border-radius: 2px; }
.apa-2fa__steps::after { content: ""; position: absolute; left: 15px; top: 18px; width: 2px; height: calc((100% - 36px) * var(--p, 0)); background: var(--apa-2fa-accent); border-radius: 2px; transition: height .7s var(--apa-2fa-ease); }
.apa-2fa__steps button { position: relative; z-index: 1; display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 8px 6px 4px; border-radius: 10px; text-align: left; font-size: 13px; color: var(--apa-2fa-muted); transition: background-color .2s, color .2s; }
.apa-2fa__steps button:not(:disabled):hover { background: var(--apa-2fa-line); color: var(--apa-2fa-ink); }
.apa-2fa__steps button:disabled { cursor: default; color: var(--apa-2fa-faint); }
.apa-2fa__steps b { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; flex: none; font: 700 11px/1 var(--apa-2fa-mono); background: var(--apa-2fa-bg); box-shadow: inset 0 0 0 1.5px currentColor; transition: background-color .3s, color .3s, box-shadow .3s; }
.apa-2fa__steps li.is-done b { background: var(--apa-2fa-accent); color: var(--apa-2fa-on); box-shadow: none; }
.apa-2fa__steps button[aria-current="step"] { color: var(--apa-2fa-ink); font-weight: 650; }
.apa-2fa__steps button[aria-current="step"] b { background: var(--apa-2fa-ink); color: var(--apa-2fa-bg); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-2fa-ink) 14%, transparent); }
.apa-2fa__who { display: flex; align-items: center; gap: 10px; padding: 10px; border-radius: 12px; background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line); min-width: 0; }
.apa-2fa__who b { display: block; font-size: 13px; }
.apa-2fa__who small { display: block; font-size: 11.5px; color: var(--apa-2fa-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-2fa__who > span:last-child { min-width: 0; }
.apa-2fa__av { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; flex: none; background: color-mix(in oklch, var(--apa-2fa-accent) 22%, var(--apa-2fa-bg)); color: var(--apa-2fa-accent); font-weight: 750; font-size: 12px; }

/* ---------- main ---------- */
.apa-2fa__scroll { min-height: 0; overflow: auto; padding: 26px clamp(18px, 3.4cqi, 40px) 20px; scrollbar-width: thin; scrollbar-color: var(--apa-2fa-line2) transparent; overscroll-behavior: contain; }
.apa-2fa__step { display: grid; align-content: start; max-width: 560px; animation: apa-2fa-in .5s var(--apa-2fa-ease) both; }
.apa-2fa__kick { font: 600 11px/1 var(--apa-2fa-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--apa-2fa-accent); }
.apa-2fa__h { margin-top: 10px; font-size: clamp(23px, 0.9rem + 1.6cqi, 30px); line-height: 1.08; font-weight: 720; letter-spacing: -.03em; text-wrap: balance; outline: none; }
.apa-2fa__p { margin-top: 10px; color: var(--apa-2fa-muted); text-wrap: pretty; max-width: 54ch; }
.apa-2fa__p b { color: var(--apa-2fa-ink); font-weight: 620; }

.apa-2fa__methods { display: grid; gap: 10px; margin-top: 22px; }
.apa-2fa__method {
  position: relative; display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center; padding: 14px 16px; border-radius: 14px; cursor: pointer;
  background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line);
  transition: box-shadow .25s, background-color .25s; animation: apa-2fa-in .5s var(--apa-2fa-ease) both; animation-delay: calc(80ms + var(--i) * 60ms);
}
.apa-2fa__method input { position: absolute; opacity: 0; pointer-events: none; }
.apa-2fa__method:hover { box-shadow: inset 0 0 0 1px var(--apa-2fa-line2); }
.apa-2fa__method:has(input:checked) { box-shadow: inset 0 0 0 1.5px var(--apa-2fa-accent); background: color-mix(in oklch, var(--apa-2fa-accent) 6%, var(--apa-2fa-panel)); }
.apa-2fa__method:has(input:focus-visible) { outline: 2px solid var(--apa-2fa-accent); outline-offset: 2px; }
.apa-2fa__method:has(input:disabled) { cursor: not-allowed; opacity: .5; }
.apa-2fa__micon { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 11px; background: var(--apa-2fa-line); color: var(--apa-2fa-muted); transition: background-color .25s, color .25s; }
.apa-2fa__micon svg { width: 22px; height: 22px; }
.apa-2fa__method:has(input:checked) .apa-2fa__micon { background: var(--apa-2fa-accent); color: var(--apa-2fa-on); }
.apa-2fa__mtext b { display: flex; align-items: center; gap: 8px; font-weight: 650; }
.apa-2fa__mtext em { font-style: normal; font-size: 10.5px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; padding: 2px 6px; border-radius: 5px; background: color-mix(in oklch, var(--apa-2fa-ok) 18%, transparent); color: var(--apa-2fa-ok); }
.apa-2fa__mtext small { display: block; font-size: 12.5px; color: var(--apa-2fa-muted); margin-top: 2px; }

/* scan */
.apa-2fa__scan { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 24px; align-items: start; margin-top: 20px; }
.apa-2fa__qrbox { display: grid; gap: 8px; justify-items: center; }
.apa-2fa__qrbox figcaption { font: 500 10.5px/1.3 var(--apa-2fa-mono); color: var(--apa-2fa-faint); text-align: center; max-width: 190px; }
.apa-2fa__qr {
  --apa-2fa-r: 0%;
  position: relative; width: 196px; aspect-ratio: 1; border-radius: 14px; background: oklch(0.985 0.005 190); overflow: hidden;
  box-shadow: 0 0 0 1px var(--apa-2fa-line2), 0 22px 40px -24px black;
  transition: --apa-2fa-r 1.15s cubic-bezier(.3, .7, .2, 1);
}
.apa-2fa__qr.is-on { --apa-2fa-r: 80%; }
.apa-2fa__qrsvg { position: absolute; inset: 0; width: 100%; height: 100%; color: oklch(0.2 0.03 210); mask: radial-gradient(circle at 50% 50%, #000 calc(var(--apa-2fa-r) - 9%), transparent var(--apa-2fa-r)); }
.apa-2fa__mods { fill: currentColor; stroke: none; }
.apa-2fa__qrlogo { position: absolute; left: 50%; top: 50%; translate: -50% -50%; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 10px; background: oklch(0.985 0.005 190); color: var(--apa-2fa-bg); box-shadow: 0 0 0 4px oklch(0.985 0.005 190); scale: 0; transition: scale .5s .7s var(--apa-2fa-spring); }
.apa-2fa__qr.is-on .apa-2fa__qrlogo { scale: 1; }
.apa-2fa__qrlogo svg { width: 24px; height: 24px; stroke-width: 2; }
.apa-2fa__laser { position: absolute; left: 6%; right: 6%; top: 0; height: 2px; border-radius: 2px; background: var(--apa-2fa-accent); box-shadow: 0 0 12px 2px var(--apa-2fa-accent); opacity: 0; }
.apa-2fa__qr.is-scan .apa-2fa__laser { animation: apa-2fa-laser .9s cubic-bezier(.45, 0, .55, 1) 2 alternate both; }
.apa-2fa__corners { position: absolute; inset: 8px; opacity: 0; transition: opacity .3s; background:
  linear-gradient(var(--apa-2fa-accent) 0 0) 0 0 / 22px 3px, linear-gradient(var(--apa-2fa-accent) 0 0) 0 0 / 3px 22px,
  linear-gradient(var(--apa-2fa-accent) 0 0) 100% 0 / 22px 3px, linear-gradient(var(--apa-2fa-accent) 0 0) 100% 0 / 3px 22px,
  linear-gradient(var(--apa-2fa-accent) 0 0) 0 100% / 22px 3px, linear-gradient(var(--apa-2fa-accent) 0 0) 0 100% / 3px 22px,
  linear-gradient(var(--apa-2fa-accent) 0 0) 100% 100% / 22px 3px, linear-gradient(var(--apa-2fa-accent) 0 0) 100% 100% / 3px 22px; background-repeat: no-repeat; }
.apa-2fa__qr.is-scan .apa-2fa__corners { opacity: 1; animation: apa-2fa-brk .9s ease-in-out infinite alternate; }
.apa-2fa__how { display: grid; gap: 16px; align-content: start; }
.apa-2fa__list { display: grid; gap: 10px; counter-reset: s; }
.apa-2fa__list li { counter-increment: s; display: grid; grid-template-columns: 24px 1fr; gap: 10px; color: var(--apa-2fa-muted); text-wrap: pretty; }
.apa-2fa__list li::before { content: counter(s); display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; background: var(--apa-2fa-line); color: var(--apa-2fa-ink); font: 700 11px/1 var(--apa-2fa-mono); }
.apa-2fa__list b { color: var(--apa-2fa-ink); font-weight: 620; }
.apa-2fa__btn, .apa-2fa__next {
  display: inline-flex; align-items: center; justify-content: center; gap: 9px; height: 42px; padding: 0 16px; border-radius: 11px; justify-self: start;
  background: var(--apa-2fa-accent); color: var(--apa-2fa-on); font-weight: 700; font-size: 14px;
  transition: filter .2s, scale .3s var(--apa-2fa-spring), opacity .2s;
}
.apa-2fa__btn:hover, .apa-2fa__next:hover { filter: brightness(1.07); }
.apa-2fa__btn:active, .apa-2fa__next:active { scale: .97; }
.apa-2fa__btn:disabled, .apa-2fa__next:disabled { opacity: .4; cursor: not-allowed; filter: none; }
.apa-2fa__btn svg { stroke-width: 2; }
.apa-2fa__manual { border-radius: 12px; background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line); }
.apa-2fa__manual summary { cursor: pointer; padding: 11px 14px; font-size: 13px; font-weight: 600; color: var(--apa-2fa-muted); list-style: none; display: flex; align-items: center; gap: 8px; border-radius: 12px; }
.apa-2fa__manual summary::-webkit-details-marker { display: none; }
.apa-2fa__manual summary::before { content: ""; width: 6px; height: 6px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; rotate: -45deg; transition: rotate .25s var(--apa-2fa-ease); }
.apa-2fa__manual[open] summary::before { rotate: 45deg; }
.apa-2fa__manual[open] summary { color: var(--apa-2fa-ink); }
.apa-2fa__keyrow { display: flex; align-items: center; gap: 10px; padding: 0 14px; }
.apa-2fa__secret { flex: 1; font: 600 15px/1.3 var(--apa-2fa-mono); letter-spacing: .12em; color: var(--apa-2fa-accent); word-spacing: .3em; overflow-wrap: anywhere; }
.apa-2fa__copy { height: 30px; padding: 0 12px; border-radius: 8px; font-size: 12.5px; font-weight: 650; background: var(--apa-2fa-line); transition: background-color .2s; }
.apa-2fa__copy:hover { background: var(--apa-2fa-line2); }
.apa-2fa__fine { padding: 8px 14px 12px; font-size: 11.5px; color: var(--apa-2fa-faint); }
.apa-2fa__fine b { color: var(--apa-2fa-muted); font-weight: 600; }

/* verify */
.apa-2fa__otp { display: flex; align-items: center; gap: 8px; margin-top: 24px; }
.apa-2fa__otp input {
  width: 52px; height: 64px; padding: 0; border-radius: 12px; border: 1.5px solid var(--apa-2fa-line2); background: var(--apa-2fa-panel); text-align: center;
  font: 650 28px/1 var(--apa-2fa-mono); caret-color: var(--apa-2fa-accent); outline: none; transition: border-color .2s, box-shadow .25s, background-color .2s, translate .3s var(--apa-2fa-spring);
}
.apa-2fa__otp input:focus { border-color: var(--apa-2fa-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-2fa-accent) 16%, transparent); }
.apa-2fa__otp input:not(:placeholder-shown), .apa-2fa__otp input.is-full { background: color-mix(in oklch, var(--apa-2fa-ink) 8%, var(--apa-2fa-bg)); }
.apa-2fa__otp input::placeholder { color: var(--apa-2fa-faint); }
.apa-2fa__gap { width: 12px; height: 2px; border-radius: 2px; background: var(--apa-2fa-line2); }
.apa-2fa__otp.is-bad input { border-color: var(--apa-2fa-bad); }
.apa-2fa__otp.is-bad { animation: apa-2fa-shake .44s cubic-bezier(.36, .07, .19, .97); }
.apa-2fa__otp.is-ok input { border-color: var(--apa-2fa-ok); color: var(--apa-2fa-ok); animation: apa-2fa-hop .5s var(--apa-2fa-spring) both; animation-delay: calc(var(--i, 0) * 45ms); }
.apa-2fa__msg { min-height: 1.45em; margin-top: 12px; font-size: 13px; font-weight: 550; }
.apa-2fa__msg[data-tone="bad"] { color: var(--apa-2fa-bad); }
.apa-2fa__msg[data-tone="ok"] { color: var(--apa-2fa-ok); }
.apa-2fa__hint { margin-top: 6px; font-size: 12.5px; color: var(--apa-2fa-faint); text-wrap: pretty; max-width: 50ch; }

/* codes */
.apa-2fa__codes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0; margin-top: 20px; border-radius: 14px; background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line); counter-reset: c; padding: 8px; }
.apa-2fa__codes li { counter-increment: c; display: flex; align-items: center; gap: 12px; padding: 8px 12px; border-radius: 8px; font: 600 15px/1.2 var(--apa-2fa-mono); letter-spacing: .08em; font-variant-numeric: tabular-nums; }
.apa-2fa__codes li::before { content: counter(c, decimal-leading-zero); font-size: 10.5px; font-weight: 500; letter-spacing: 0; color: var(--apa-2fa-faint); }
.apa-2fa__codes li.is-scr { color: var(--apa-2fa-accent); }
.apa-2fa__codes li:hover { background: var(--apa-2fa-line); }
.apa-2fa__coderow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 12px; }
.apa-2fa__ghost { display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 12px; border-radius: 10px; font-size: 13px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--apa-2fa-line2); transition: background-color .2s; }
.apa-2fa__ghost:hover { background: var(--apa-2fa-line); }
.apa-2fa__ghost svg { width: 16px; height: 16px; }
.apa-2fa__left { margin-left: auto; font-size: 12px; color: var(--apa-2fa-faint); font-variant-numeric: tabular-nums; }
.apa-2fa__saved { display: flex; gap: 10px; align-items: center; margin-top: 18px; padding: 12px 14px; border-radius: 12px; cursor: pointer; box-shadow: inset 0 0 0 1px var(--apa-2fa-line); font-size: 13.5px; transition: box-shadow .25s, background-color .25s; }
.apa-2fa__saved input { width: 18px; height: 18px; margin: 0; }
.apa-2fa__saved:has(input:checked) { box-shadow: inset 0 0 0 1.5px var(--apa-2fa-ok); background: color-mix(in oklch, var(--apa-2fa-ok) 7%, transparent); }

/* done */
.apa-2fa__shield { display: grid; place-items: center; width: 64px; height: 64px; margin-bottom: 18px; border-radius: 18px; background: color-mix(in oklch, var(--apa-2fa-ok) 16%, transparent); color: var(--apa-2fa-ok); animation: apa-2fa-pop .6s var(--apa-2fa-spring) both; }
.apa-2fa__shield svg { width: 34px; height: 34px; stroke-width: 1.6; }
.apa-2fa__shield svg path:last-child { stroke-dasharray: 12; stroke-dashoffset: 12; animation: apa-2fa-draw .5s .35s var(--apa-2fa-ease) forwards; }
.apa-2fa__sum { display: grid; margin-top: 20px; border-radius: 14px; background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line); }
.apa-2fa__sum div { display: flex; justify-content: space-between; gap: 14px; padding: 12px 16px; font-size: 13px; }
.apa-2fa__sum div + div { border-top: 1px solid var(--apa-2fa-line); }
.apa-2fa__sum dt { color: var(--apa-2fa-muted); }
.apa-2fa__sum dd { font-weight: 620; text-align: right; }

/* footer */
.apa-2fa__foot { display: flex; align-items: center; gap: 12px; padding: 12px clamp(18px, 3.4cqi, 40px) 16px; border-top: 1px solid var(--apa-2fa-line); }
.apa-2fa__back { height: 40px; padding: 0 12px; border-radius: 10px; font-weight: 600; color: var(--apa-2fa-muted); transition: background-color .2s, color .2s; }
.apa-2fa__back:hover { background: var(--apa-2fa-line); color: var(--apa-2fa-ink); }
.apa-2fa[data-step="method"] .apa-2fa__back, .apa-2fa[data-step="done"] .apa-2fa__back { visibility: hidden; }
.apa-2fa__keys { flex: 1; display: flex; justify-content: center; align-items: center; gap: 4px; flex-wrap: wrap; font-size: 11.5px; color: var(--apa-2fa-faint); }
.apa-2fa__keys i { font-style: normal; margin-right: 8px; }
.apa-2fa__next { margin-left: auto; }
.apa-2fa__next kbd { background: color-mix(in oklch, var(--apa-2fa-on) 14%, transparent); box-shadow: none; }

/* ---------- authenticator ---------- */
.apa-2fa__ahead { display: flex; align-items: center; gap: 10px; padding: 18px 16px 10px 18px; }
.apa-2fa__ahead b { display: block; font-weight: 750; letter-spacing: -.01em; }
.apa-2fa__ahead small { display: block; font-size: 11.5px; color: var(--apa-2fa-faint); }
.apa-2fa__alogo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--apa-2fa-ink); color: var(--apa-2fa-bg); }
.apa-2fa__alogo svg { stroke-width: 2.2; }
.apa-2fa__add { margin-left: auto; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--apa-2fa-line); transition: background-color .2s, rotate .4s var(--apa-2fa-spring); }
.apa-2fa__add:hover { background: var(--apa-2fa-line2); rotate: 90deg; }
.apa-2fa__synced { display: flex; align-items: center; gap: 8px; padding: 0 18px 10px; font-size: 11.5px; color: var(--apa-2fa-faint); }
.apa-2fa__pulse { width: 7px; height: 7px; border-radius: 50%; background: var(--apa-2fa-ok); box-shadow: 0 0 0 0 color-mix(in oklch, var(--apa-2fa-ok) 60%, transparent); animation: apa-2fa-beat 2s ease-out infinite; }
.apa-2fa__accts { min-height: 0; overflow: auto; padding: 0 10px 14px; display: grid; align-content: start; gap: 6px; scrollbar-width: none; }
.apa-2fa__acct { animation: apa-2fa-in .45s var(--apa-2fa-ease) both; }
.apa-2fa__acct.is-new { animation: apa-2fa-drop .7s var(--apa-2fa-spring) both; }
.apa-2fa__code {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; align-items: center; width: 100%; padding: 12px 14px; border-radius: 12px; text-align: left;
  background: var(--apa-2fa-panel); box-shadow: inset 0 0 0 1px var(--apa-2fa-line); transition: box-shadow .25s, background-color .25s;
}
.apa-2fa__code:hover { box-shadow: inset 0 0 0 1px var(--apa-2fa-line2); }
.apa-2fa__acct.is-new .apa-2fa__code { box-shadow: inset 0 0 0 1.5px var(--apa-2fa-accent); }
.apa-2fa__iss { font-size: 12.5px; font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-2fa__acc { grid-column: 1; font-size: 11.5px; color: var(--apa-2fa-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-2fa__digits { grid-column: 1; display: flex; gap: 1px; margin-top: 4px; font: 600 25px/1 var(--apa-2fa-mono); letter-spacing: .02em; color: var(--apa-2fa-ink); font-variant-numeric: tabular-nums; }
.apa-2fa__digits span { display: inline-block; }
.apa-2fa__digits span:nth-child(3) { margin-right: 10px; }
.apa-2fa__digits.is-flip span { animation: apa-2fa-flip .5s var(--apa-2fa-ease) both; animation-delay: calc(var(--i) * 35ms); }
.apa-2fa__code[data-late] .apa-2fa__digits { color: var(--apa-2fa-bad); }
.apa-2fa__ring {
  grid-column: 2; grid-row: 1 / span 3; width: 30px; height: 30px; border-radius: 50%;
  background: conic-gradient(var(--apa-2fa-accent) var(--apa-2fa-t), var(--apa-2fa-line) 0);
  mask: radial-gradient(circle, transparent 9.5px, #000 10px);
  animation: apa-2fa-ring 30s linear infinite;
}
