// Presentational only: the QR pattern, setup key, codes and "authenticator" are all simulated in this component.
root.addEventListener('submit', (e) => e.preventDefault());
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const bind = (k, v) => $$(`[data-bind="${k}"]`).forEach((el) => { el.textContent = v; });

const STEPS = ['method', 'scan', 'verify', 'codes', 'done'];
const S = { step: 'method', max: 0, method: 'app', linked: false, tab: 'setup', codes: [], verified: false, busy: false, layer: false };
