}
const ACCTS = [
  { id: 'lm', iss: 'Larchmont Mail', acc: 'dana.ruiz@larchmont.email', sec: rand(16, A32) },
  { id: 'pw', iss: 'Pipewright CI', acc: 'druiz', sec: rand(16, A32) },
  { id: 'os', iss: 'Ostara Cloud', acc: 'dana@coldframe.dev · prod', sec: rand(16, A32) },
