const CF = { id: 'cf', iss: 'Coldframe', acc: 'dana.ruiz@coldframe.dev', sec: secret };
const list = $('.apa-2fa__accts');

function digitsHTML(c) { return Array.from(c).map((d, i) => `<span style="--i:${i}">${d}</span>`).join(''); }
