  list.innerHTML = ACCTS.map((a) => `<li class="apa-2fa__acct${a.id === newId ? ' is-new' : ''}" data-id="${a.id}">
    <button type="button" class="apa-2fa__code" data-acct="${a.id}" aria-label="${a.iss}, ${a.acc}. Copy code">
