}
function syncRings() { const ms = Date.now() % WIN; $$('.apa-2fa__ring').forEach((r) => { const a = r.getAnimations && r.getAnimations()[0]; if (a) a.currentTime = ms; }); }
function late() { const on = WIN - (Date.now() % WIN) <= 5000; $$('.apa-2fa__code').forEach((b) => b.toggleAttribute('data-late', on)); }
