  $$('.apa-2fa__code').forEach((b) => {
    const a = ACCTS.find((x) => x.id === b.dataset.acct); const d = b.querySelector('.apa-2fa__digits');
    d.innerHTML = digitsHTML(code(a.sec, w));
    if (!reduce) { d.classList.remove('is-flip'); void d.offsetWidth; d.classList.add('is-flip'); }
  });
  syncRings();
}
let curW = win(), visible = true;
const iv = setInterval(() => {
  if (!root.isConnected) return void clearInterval(iv);
  if (document.hidden || !visible) return;
  const w = win(); if (w !== curW) { curW = w; rollCodes(); }
  late();
}, 250);
const io = new IntersectionObserver((ents) => {
  if (!root.isConnected) { io.disconnect(); return; }
