/* ---------- render + navigation ---------- */
const NEXT = { method: 'Continue', scan: 'I’ve scanned it', verify: 'Verify code', codes: 'Finish setup', done: 'Start over' };
const KEYS = {
  method: '<kbd>↑</kbd><kbd>↓</kbd><i>method</i><kbd>↵</kbd> continue',
  scan: '<kbd>S</kbd><i>scan</i><kbd>↵</kbd> continue',
  verify: '<kbd>0</kbd>–<kbd>9</kbd><i>digits</i><kbd>⌫</kbd><i>back</i><kbd>↵</kbd> verify',
  codes: '<kbd>Space</kbd><i>tick saved</i><kbd>↵</kbd> finish', done: '',
