function render() {
  root.dataset.step = S.step;
  const idx = STEPS.indexOf(S.step);
  $$('.apa-2fa__step').forEach((s) => { s.hidden = s.dataset.s !== S.step; });
  $$('.apa-2fa__steps li').forEach((li, i) => {
    const b = li.querySelector('button');
