/* Strength-tinted reset. One registered hue drives every accent; re-theme with --apa-reset-paper, -ink and the two hue stops. */
@property --apa-reset-hue { syntax: "<number>"; inherits: true; initial-value: 25; }
@property --apa-reset-s { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --apa-reset-c { syntax: "<number>"; inherits: true; initial-value: 0.03; }

.apa-reset {
  --apa-reset-paper: oklch(0.984 0.005 85);
  --apa-reset-ink: oklch(0.22 0.02 265);
  --apa-reset-hue-weak: 25;
  --apa-reset-hue-strong: 152;

  --apa-reset-hue: var(--apa-reset-hue-weak);
  --apa-reset-s: 0;
  --apa-reset-c: 0.03;
  --apa-reset-accent: oklch(0.6 var(--apa-reset-c) var(--apa-reset-hue));
  --apa-reset-accent-ink: oklch(0.42 calc(var(--apa-reset-c) * 0.78) var(--apa-reset-hue));
  --apa-reset-tint: oklch(0.955 calc(var(--apa-reset-c) * 0.2) var(--apa-reset-hue));
  --apa-reset-muted: color-mix(in oklch, var(--apa-reset-ink) 62%, var(--apa-reset-paper));
  --apa-reset-faint: color-mix(in oklch, var(--apa-reset-ink) 40%, var(--apa-reset-paper));
  --apa-reset-rule: color-mix(in oklch, var(--apa-reset-ink) 11%, transparent);
  --apa-reset-rule2: color-mix(in oklch, var(--apa-reset-ink) 20%, transparent);
  --apa-reset-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-reset-spring: linear(0, 0.08 4%, 0.3 9%, 0.7 16%, 0.96 23%, 1.07 29%, 1.09 35%, 1.05 43%, 1.01 54%, 0.995 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-reset-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-reset-paper);
  color: var(--apa-reset-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apa-reset-accent);
  outline: none;
  transition: --apa-reset-hue .9s var(--apa-reset-ease), --apa-reset-c .6s var(--apa-reset-ease), --apa-reset-s .9s var(--apa-reset-spring);
}
:where(.apa-reset) *, :where(.apa-reset) *::before, :where(.apa-reset) *::after { box-sizing: border-box; }
:where(.apa-reset) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-reset) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-reset) :is(p, h1, ul, ol) { margin: 0; padding: 0; }
:where(.apa-reset) :is(ul, ol) { list-style: none; }
:where(.apa-reset) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-reset) :focus-visible { outline: 2px solid var(--apa-reset-accent); outline-offset: 2px; }
:where(.apa-reset) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 10%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 16%, transparent);
}
.apa-reset [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-reset__app { display: grid; height: 100%; grid-template: "side main" minmax(0, 1fr) / minmax(300px, 0.78fr) minmax(0, 1.22fr); }
.apa-reset__side {
  grid-area: side; position: relative; display: grid; grid-template-rows: auto auto auto 1fr; gap: 0; min-height: 0; overflow: hidden;
  padding: 22px 26px 22px; margin: 10px 0 10px 10px; border-radius: 14px;
  background: radial-gradient(120% 70% at 50% 18%, color-mix(in oklch, var(--apa-reset-accent) 20%, transparent), transparent 65%), var(--apa-reset-tint);
}
.apa-reset__main { grid-area: main; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }

/* ---------- side ---------- */
.apa-reset__brand { display: flex; align-items: center; gap: 8px; }
.apa-reset__mark { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--apa-reset-ink); color: var(--apa-reset-paper); font: 800 17px/1 ui-serif, Georgia, serif; padding-bottom: 3px; }
