.apa-reset__body { fill: var(--apa-reset-accent); stroke: none; filter: drop-shadow(0 10px 14px color-mix(in oklch, var(--apa-reset-accent) 45%, transparent)); }
.apa-reset__hole { fill: var(--apa-reset-ink); stroke: none; }
.apa-reset__slot { stroke: var(--apa-reset-ink); stroke-width: 6; }
.apa-reset[data-view="done"] .apa-reset__shackle { translate: 0 0; transition: translate .5s var(--apa-reset-spring); }
.apa-reset__crack { text-align: center; }
.apa-reset__cracklbl { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--apa-reset-accent-ink); }
.apa-reset__crackval { margin-top: 8px; font-size: clamp(24px, 1rem + 1.7cqi, 34px); line-height: 1.05; font-weight: 780; letter-spacing: -.035em; text-wrap: balance; font-variant-numeric: tabular-nums; }
.apa-reset__crackval.is-tick { animation: apa-reset-tick .45s var(--apa-reset-ease); }
.apa-reset__crackfine { margin: 8px auto 0; max-width: 30ch; font-size: 12.5px; color: var(--apa-reset-muted); text-wrap: balance; }

.apa-reset__sessions { align-self: end; margin-top: 18px; padding: 12px; border-radius: 12px; background: color-mix(in oklch, var(--apa-reset-paper) 82%, transparent); box-shadow: 0 0 0 1px var(--apa-reset-rule); }
.apa-reset__sh { font-size: 11.5px; font-weight: 650; color: var(--apa-reset-muted); text-transform: uppercase; letter-spacing: .07em; padding: 0 4px 6px; }
.apa-reset__sess li { position: relative; display: flex; align-items: center; gap: 10px; padding: 6px 4px; font-size: 12.5px; transition: opacity .4s, filter .4s; }
