.apa-reset__sess small { display: block; color: var(--apa-reset-muted); font-size: 11.5px; }
.apa-reset__dev { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; background: color-mix(in oklch, var(--apa-reset-ink) 6%, transparent); flex: none; }
.apa-reset__dev svg { width: 17px; height: 17px; }
.apa-reset__sess li.is-this b::after { content: "this one"; margin-left: 6px; padding: 1px 6px; border-radius: 5px; font-size: 10px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; background: var(--apa-reset-ink); color: var(--apa-reset-paper); }
.apa-reset__sess li:not(.is-this) b { position: relative; width: fit-content; }
.apa-reset__sess li:not(.is-this) b::before { content: ""; position: absolute; left: -3px; right: -3px; top: 54%; height: 1.5px; background: var(--apa-reset-accent-ink); transform-origin: 0 50%; scale: 0 1; transition: scale .45s var(--apa-reset-ease); }
.apa-reset:has(.apa-reset__signout input:checked) .apa-reset__sess li:not(.is-this) { opacity: .5; }
.apa-reset:has(.apa-reset__signout input:checked) .apa-reset__sess li:not(.is-this) b::before { scale: 1 1; }
.apa-reset:has(.apa-reset__signout input:checked) .apa-reset__sess li:nth-child(3) b::before { transition-delay: 60ms; }
.apa-reset:has(.apa-reset__signout input:checked) .apa-reset__sess li:nth-child(4) b::before { transition-delay: 120ms; }

/* ---------- main ---------- */
.apa-reset__top { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 20px clamp(18px, 4cqi, 48px) 0; }
.apa-reset__trail { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--apa-reset-faint); flex-wrap: wrap; }
.apa-reset__trail li { display: inline-flex; align-items: center; gap: 6px; }
.apa-reset__trail li + li::before { content: ""; width: 14px; height: 1.5px; background: var(--apa-reset-rule2); }
.apa-reset__trail li.is-done { color: var(--apa-reset-muted); }
.apa-reset__trail li.is-done::after { content: ""; width: 7px; height: 4px; border: solid var(--apa-reset-accent-ink); border-width: 0 0 1.5px 1.5px; rotate: -45deg; translate: 0 -1px; }
.apa-reset__trail li[aria-current] { color: var(--apa-reset-ink); font-weight: 650; }
.apa-reset__expiry { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--apa-reset-muted); }
.apa-reset__expiry svg { width: 15px; height: 15px; }
.apa-reset__expiry b { font-variant-numeric: tabular-nums; color: var(--apa-reset-ink); font-weight: 650; }

.apa-reset__stage { min-height: 0; overflow: auto; padding: 18px clamp(18px, 4cqi, 48px) 18px; scrollbar-width: thin; overscroll-behavior: contain; }
.apa-reset__form, .apa-reset__done { max-width: 470px; display: grid; animation: apa-reset-in .5s var(--apa-reset-ease) both; }
.apa-reset__h { font-size: clamp(25px, 1rem + 1.8cqi, 33px); line-height: 1.06; font-weight: 760; letter-spacing: -.035em; text-wrap: balance; outline: none; }
.apa-reset__p { margin-top: 8px; color: var(--apa-reset-muted); text-wrap: pretty; }
.apa-reset__p b { color: var(--apa-reset-ink); font-weight: 620; }

.apa-reset__field { display: grid; gap: 7px; margin-top: 20px; }
.apa-reset__lblrow { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.apa-reset__lbl { font-size: 12.5px; font-weight: 650; }
.apa-reset__suggest { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px; border-radius: 7px; font-size: 12.5px; font-weight: 620; color: var(--apa-reset-accent-ink); transition: background-color .2s; }
.apa-reset__suggest:hover { background: var(--apa-reset-tint); }
.apa-reset__suggest svg { width: 16px; height: 16px; }
.apa-reset__suggest:active svg { rotate: 90deg; transition: rotate .3s var(--apa-reset-spring); }
.apa-reset__box { position: relative; }
.apa-reset__box input {
  width: 100%; height: 46px; padding: 0 48px 0 14px; border-radius: 10px; border: 1.5px solid var(--apa-reset-rule2); background: white;
  font: 500 15px/1 ui-monospace, Menlo, monospace; letter-spacing: .04em; outline: none;
  transition: border-color .25s, box-shadow .3s var(--apa-reset-ease);
}
.apa-reset__box input:hover { border-color: color-mix(in oklch, var(--apa-reset-ink) 34%, transparent); }
.apa-reset__box input:focus { border-color: var(--apa-reset-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-reset-accent) 18%, transparent); }
.apa-reset__box input[aria-invalid="true"] { border-color: oklch(0.58 0.19 27); }
.apa-reset__eye { position: absolute; right: 5px; top: 5px; width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center; color: var(--apa-reset-muted); transition: background-color .2s, color .2s; }
.apa-reset__eye:hover { background: color-mix(in oklch, var(--apa-reset-ink) 6%, transparent); color: var(--apa-reset-ink); }
.apa-reset__eyeslash { stroke-dasharray: 23; stroke-dashoffset: 0; transition: stroke-dashoffset .35s var(--apa-reset-ease); }
.apa-reset__eye[aria-pressed="true"] .apa-reset__eyeslash { stroke-dashoffset: 23; }

.apa-reset__meter { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
