.apa-reset[data-score="1"] .apa-reset__meter i:nth-child(-n+1)::after,
.apa-reset[data-score="2"] .apa-reset__meter i:nth-child(-n+2)::after,
.apa-reset[data-score="3"] .apa-reset__meter i:nth-child(-n+3)::after,
