.apa-reset__rules li[data-bad] { color: oklch(0.52 0.17 27); }
.apa-reset__rules li[data-bad] i { box-shadow: inset 0 0 0 1.5px oklch(0.6 0.18 27); }

.apa-reset__strip { display: flex; flex-wrap: wrap; gap: 3px; min-height: 6px; }
