.apa-reset__match { min-height: 1.4em; font-size: 12.5px; color: var(--apa-reset-muted); }
.apa-reset__match[data-tone="ok"] { color: var(--apa-reset-accent-ink); font-weight: 620; }
.apa-reset__match[data-tone="bad"] { color: oklch(0.52 0.17 27); }

.apa-reset__signout { display: flex; align-items: flex-start; gap: 10px; margin-top: 12px; font-size: 13.5px; cursor: pointer; text-wrap: pretty; }
