.apa-reset__actions { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-top: 18px; }
.apa-reset__btn {
  display: inline-flex; align-items: center; gap: 10px; height: 46px; padding: 0 18px; border-radius: 11px;
  background: var(--apa-reset-ink); color: var(--apa-reset-paper); font-weight: 680; font-size: 14.5px;
