  transition: scale .3s var(--apa-reset-spring), background-color .25s;
}
.apa-reset__btn:hover { background: color-mix(in oklch, var(--apa-reset-ink) 84%, var(--apa-reset-accent)); }
.apa-reset__btn:active { scale: .98; }
