.apa-reset__btn[aria-busy="true"] { cursor: progress; }
.apa-reset__btn--ghost { background: none; color: var(--apa-reset-ink); box-shadow: inset 0 0 0 1.5px var(--apa-reset-rule2); }
.apa-reset__btn--ghost:hover { background: color-mix(in oklch, var(--apa-reset-ink) 5%, transparent); }
.apa-reset__link { font-size: 13px; font-weight: 600; color: var(--apa-reset-muted); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--apa-reset-rule2); }
.apa-reset__link:hover { color: var(--apa-reset-ink); }

.apa-reset__out { display: grid; gap: 6px; margin-top: 18px; }
.apa-reset__out li { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 12px; row-gap: 1px; padding: 10px 12px; border-radius: 10px; background: white; box-shadow: 0 0 0 1px var(--apa-reset-rule); font-size: 13px; animation: apa-reset-in .45s var(--apa-reset-ease) both; animation-delay: calc(200ms + var(--i) * 90ms); }
