.apa-reset__out li small { grid-column: 1; grid-row: 2; font-size: 11.5px; color: var(--apa-reset-muted); }
.apa-reset__out li span { grid-column: 2; grid-row: 1 / span 2; white-space: nowrap; font-size: 12px; color: var(--apa-reset-accent-ink); font-weight: 650; }

.apa-reset__foot { display: flex; align-items: center; gap: 4px; padding: 10px clamp(18px, 4cqi, 48px) 16px; font-size: 11.5px; color: var(--apa-reset-faint); }
.apa-reset__foot kbd + kbd { margin-left: 2px; }
.apa-reset__foot kbd:nth-of-type(3), .apa-reset__foot kbd:nth-of-type(5) { margin-left: 10px; }

/* ---------- keyframes ---------- */
@keyframes apa-reset-in { from { opacity: 0; translate: 0 10px; } }
@keyframes apa-reset-shake { 15%, 85% { translate: -2px 0; } 30%, 70% { translate: 5px 0; } 45%, 55% { translate: -7px 0; } }
@keyframes apa-reset-tick { from { opacity: .3; translate: 0 6px; filter: blur(2px); } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-reset__app { grid-template-columns: 280px minmax(0, 1fr); }
  .apa-reset__side { padding: 18px; }
  .apa-reset__rules { grid-template-columns: 1fr; }
  .apa-reset__sess small { display: none; }
}
/* ---------- container: single pane ---------- */
@container (max-width: 759px) {
  .apa-reset__app { grid-template: "side" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-reset__side { grid-template: "brand brand" auto "lock crack" auto / auto 1fr; align-items: center; gap: 4px 14px; margin: 8px 8px 0; padding: 12px 16px; }
  .apa-reset__brand { grid-area: brand; }
  .apa-reset__lockwrap { grid-area: lock; padding: 4px 0 0; }
  .apa-reset__lock { width: 52px; }
  .apa-reset__crack { grid-area: crack; text-align: left; }
  .apa-reset__crackval { font-size: 22px; margin-top: 4px; }
  .apa-reset__crackfine, .apa-reset__sessions { display: none; }
  .apa-reset__top { padding-top: 14px; }
  .apa-reset__trail li:not([aria-current]) { display: none; }
  .apa-reset__foot { display: none; }
}
@container (max-width: 480px) {
  .apa-reset__rules { grid-template-columns: 1fr; }
  .apa-reset__suggest kbd { display: none; }
  .apa-reset__stage { padding-inline: 16px; }
  .apa-reset__btn kbd { display: none; }
}

/* ---------- reduced motion: colour changes snap, nothing slides ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-reset, .apa-reset *, .apa-reset *::before, .apa-reset *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
}

