// Presentational only: the password never leaves this component and the "history" check is against invented sample values.
root.addEventListener('submit', (e) => e.preventDefault());
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const bind = (k, v) => $$(`[data-bind="${k}"]`).forEach((el) => { el.textContent = v; });
const uid = 'apa-reset-' + Math.random().toString(36).slice(2, 8);

const form = $('.apa-reset__form');
const pw = form.elements.pw, cf = form.elements.confirm, signout = form.elements.signout;
const errEl = $('.apa-reset__err'), strip = $('.apa-reset__strip'), matchEl = $('.apa-reset__match'), btn = $('.apa-reset__btn');
$$('[data-for]').forEach((l) => { const inp = form.elements[l.dataset.for]; inp.id = uid + '-' + l.dataset.for; l.htmlFor = inp.id; });

const S = { view: 'set', busy: false, expired: false, typing: 0 };
const COMMON = ['password', 'passw0rd', '123456', '12345678', 'qwerty', 'qwertyuiop', 'letmein', 'welcome', 'iloveyou', 'admin', 'monkey', 'dragon', 'football', 'sunshine', 'princess', 'abc123', 'trustno1', 'summer', 'winter', 'changeme', 'payroll', 'coffee'];
const PERSONAL = ['theo', 'marsh', 'saltgrass', 'halden'];
const HISTORY = ['saltgrass2024!', 'harbourlight#9', 'marsh-theo-2023'];
const WORDS = ['copper', 'lantern', 'ferry', 'thistle', 'orchard', 'gravel', 'pigeon', 'velvet', 'harbour', 'quarry', 'saffron', 'tundra', 'walnut', 'meadow', 'cobalt', 'ember', 'falcon', 'juniper', 'kettle', 'lagoon', 'marble', 'nutmeg', 'oyster', 'pebble', 'quill', 'rhubarb', 'sable', 'timber', 'umber', 'violet', 'willow', 'yarrow', 'zephyr', 'anchor', 'bramble', 'cinder', 'drizzle', 'fennel', 'garnet', 'hollow', 'ivory', 'jasper', 'kelp', 'lichen', 'mortar', 'nimbus', 'ochre', 'parsnip', 'russet', 'spindle'];
const LABELS = ['Too weak', 'Weak', 'Fair', 'Strong', 'Excellent'];

/* ---------- estimate ---------- */
function analyse(p) {
  const low = p.toLowerCase();
  const lower = /[a-z]/.test(p), upper = /[A-Z]/.test(p), digit = /\d/.test(p), sym = /[^A-Za-z0-9]/.test(p);
  const pool = (lower ? 26 : 0) + (upper ? 26 : 0) + (digit ? 10 : 0) + (sym ? 33 : 0);
  let bits = p.length ? p.length * Math.log2(Math.max(pool, 2)) : 0;
  const rows = ['abcdefghijklmnopqrstuvwxyz', 'qwertyuiopasdfghjklzxcvbnm', '01234567890'];
  let seq = 0;
  for (let i = 0; i < low.length - 2; i++) { const t = low.slice(i, i + 3), r = t.split('').reverse().join(''); if (rows.some((s) => s.includes(t) || s.includes(r))) seq++; }
  const rep = (low.match(/(.)\1{2,}/g) || []).reduce((a, m) => a + m.length, 0);
  bits -= seq * 3.2 + rep * 2.5;
  const bare = low.replace(/[^a-z0-9]/g, '');
  const common = COMMON.some((w) => bare.includes(w) && bare.length < w.length + 5) || seq >= 3 || rep >= 4;
  const personal = PERSONAL.some((w) => low.includes(w));
  const history = HISTORY.includes(low);
  // passphrases are scored by words, not characters (as a cracker with a word list would)
  const parts = p.split(/[-_ .]+/).filter(Boolean);
  if (parts.length >= 3 && parts.filter((x) => /^[a-z]{3,}$/i.test(x)).length >= 3) {
    const words = parts.filter((x) => /^[a-z]{3,}$/i.test(x)).length;
    bits = Math.min(bits, words * 12.9 + (digit ? 6.6 : 0) + (upper ? 4 : 0) + (sym && !/^[a-z0-9-_ .]+$/i.test(p) ? 4 : 0));
  }
  if (common) bits = Math.min(bits, 18);
  if (personal) bits = Math.min(bits * 0.5, bits - 14);
  if (history) bits = Math.min(bits, 10);
  bits = Math.max(0, bits);
  const score = !p ? -1 : bits < 28 ? 0 : bits < 42 ? 1 : bits < 58 ? 2 : bits < 75 ? 3 : 4;
  return {
    bits, score,
    rules: { len: p.length >= 12, mix: /[a-z]/i.test(p) && (digit || sym), common: !!p && !common, personal: !!p && !personal, history: !!p && !history },
  };
}
function human(bits) {
  const sec = Math.pow(2, bits - 1) / 1e10;
  if (sec < 1) return 'Instantly';
  const yr = sec / 31557600;
  if (yr >= 13.8e9) return 'Longer than the universe is old';
  const n = (v, u, us) => { const r = Math.round(v); return `About ${r.toLocaleString('en-GB')} ${r === 1 ? u : us}`; };
  if (yr >= 1e9) return `About ${(yr / 1e9).toFixed(1)} billion years`;
  if (yr >= 1e6) return `About ${Math.round(yr / 1e6).toLocaleString('en-GB')} million years`;
  if (yr >= 100) return n(yr / 100, 'century', 'centuries');
  if (yr >= 1) return n(yr, 'year', 'years');
  if (sec >= 2629800) return n(sec / 2629800, 'month', 'months');
  if (sec >= 86400) return n(sec / 86400, 'day', 'days');
  if (sec >= 3600) return n(sec / 3600, 'hour', 'hours');
  if (sec >= 60) return n(sec / 60, 'minute', 'minutes');
  return n(sec, 'second', 'seconds');
}

/* ---------- render ---------- */
let lastCrack = '';
function update() {
  const p = pw.value, c = cf.value, a = analyse(p);
  root.dataset.score = a.score;
  const s = Math.min(1, a.bits / 80);
  root.style.setProperty('--apa-reset-hue', p ? (25 + s * 127).toFixed(1) : 25);
  root.style.setProperty('--apa-reset-c', p ? 0.17 : 0.03);
  root.style.setProperty('--apa-reset-s', p ? s.toFixed(3) : 0);
  bind('label', p ? LABELS[a.score] : 'Not set');
  bind('bits', p ? `≈ ${Math.round(a.bits)} bits` : '');
  bind('count', `${Math.min(p.length, 99)} / 12`);
  const crack = p ? human(a.bits) : '—';
  if (crack !== lastCrack) {
    bind('crack', crack); lastCrack = crack;
    const el = $('.apa-reset__crackval'); if (!reduce) { el.classList.remove('is-tick'); void el.offsetWidth; el.classList.add('is-tick'); }
  }
  bind('crackfine', p ? `${Math.round(a.bits)} bits of guesswork, at ten billion guesses a second on stolen hashes.` : 'Start typing and we’ll estimate it at ten billion guesses a second.');
  $$('.apa-reset__rules li').forEach((li) => {
    const ok = a.rules[li.dataset.rule];
    li.toggleAttribute('data-ok', ok);
    if (ok) li.removeAttribute('data-bad');
  });
  // per-character match strip
  const n = Math.min(40, Math.max(p.length, c.length));
  let html = '';
  for (let i = 0; i < n; i++) {
    const st = i >= p.length ? 'extra' : i >= c.length ? '' : c[i] === p[i] ? 'ok' : 'bad';
    html += `<i${st ? ` data-s="${st}"` : ''}></i>`;
  }
  strip.innerHTML = html;
  if (!c) { matchEl.textContent = ''; delete matchEl.dataset.tone; }
  else if (c === p) { matchEl.textContent = 'Both match'; matchEl.dataset.tone = 'ok'; }
  else {
    const k = Array.from(c).findIndex((ch, i) => ch !== p[i]);
    if (k === -1) { matchEl.textContent = `${c.length} of ${p.length} characters match so far`; delete matchEl.dataset.tone; }
    else { matchEl.textContent = k >= p.length ? `${c.length - p.length} character${c.length - p.length > 1 ? 's' : ''} too many` : `Character ${k + 1} doesn’t match`; matchEl.dataset.tone = 'bad'; }
  }
  return a;
}

function setView(v) {
  S.view = v; root.dataset.view = v;
  $$('[data-v]').forEach((x) => { x.hidden = x.dataset.v !== v; });
  const trail = $$('.apa-reset__trail li');
  trail.forEach((li, i) => { li.classList.toggle('is-done', i < 2 || (v === 'done' && i < 4)); if ((v === 'done' ? 3 : 2) === i) li.setAttribute('aria-current', 'step'); else li.removeAttribute('aria-current'); });
  const h = $(`[data-v="${v}"] .apa-reset__h`); if (h) h.focus({ preventScroll: true });
}

/* ---------- actions ---------- */
function suggest() {
  if (S.view !== 'set' || S.expired) return;
  const pick = []; while (pick.length < 4) { const w = WORDS[Math.floor(Math.random() * WORDS.length)]; if (!pick.includes(w)) pick.push(w); }
  const phrase = pick.map((w) => w[0].toUpperCase() + w.slice(1)).join('-') + '-' + (10 + Math.floor(Math.random() * 90));
  setReveal(true);
  const id = ++S.typing;
  if (reduce) { pw.value = phrase; cf.value = phrase; update(); return; }
  pw.value = ''; cf.value = ''; let i = 0;
  const step = () => {
    if (id !== S.typing) return;
    i++; pw.value = phrase.slice(0, i); update();
    if (i < phrase.length) later(step, 22 + Math.random() * 26);
    else later(() => { if (id === S.typing) { cf.value = phrase; update(); matchEl.textContent = 'Both match — save it in your password manager'; } }, 220);
  };
  later(step, 60);
  pw.focus();
}
function setReveal(on) {
  const b = $('[data-act="reveal"]'); b.setAttribute('aria-pressed', String(on)); b.setAttribute('aria-label', on ? 'Hide passwords' : 'Show passwords');
  pw.type = cf.type = on ? 'text' : 'password';
}
function submit() {
  if (S.busy) return;
  S.typing++;
  if (S.expired) { errEl.textContent = 'This reset link has expired. Request a new one from the sign-in page.'; return; }
  const a = update();
  const order = ['len', 'mix', 'common', 'personal', 'history'];
  const fail = order.filter((k) => !a.rules[k]);
  $$('.apa-reset__rules li').forEach((li) => li.toggleAttribute('data-bad', fail.includes(li.dataset.rule)));
  const MSG = { len: 'Make it at least 12 characters.', mix: 'Add a number or a symbol.', common: 'That one is on every cracking list — try a phrase.', personal: 'Leave your name and company out of it.', history: 'You’ve used that one before. Pick something new.' };
  let msg = fail.length ? MSG[fail[0]] : cf.value !== pw.value ? (cf.value ? 'The two passwords don’t match yet.' : 'Type the password a second time to confirm it.') : '';
  if (msg) {
    errEl.textContent = msg; form.classList.remove('is-shake'); void form.offsetWidth; form.classList.add('is-shake');
    (fail.length ? pw : cf).setAttribute('aria-invalid', 'true'); (fail.length ? pw : cf).focus(); return;
  }
  errEl.textContent = ''; S.busy = true; btn.setAttribute('aria-busy', 'true'); $('.apa-reset__btnl').textContent = 'Updating…';
  later(() => {
    S.busy = false; btn.setAttribute('aria-busy', 'false'); $('.apa-reset__btnl').textContent = 'Update password';
    const others = $$('.apa-reset__sess li:not(.is-this)');
    const out = $('.apa-reset__out');
    out.innerHTML = signout.checked
      ? others.map((li, i) => `<li style="--i:${i}"><b>${li.querySelector('b').textContent}</b><small>${li.querySelector('small').textContent}</small><span>Signed out</span></li>`).join('') + `<li style="--i:${others.length}"><b>This device</b><span>Still signed in</span></li>`
      : `<li style="--i:0"><b>Other sessions</b><span>Left signed in</span></li>`;
    bind('doneline', signout.checked ? `Use it next time you sign in. ${others.length} other sessions were signed out, and we emailed theo.marsh@saltgrass.co to confirm the change.` : 'Use it next time you sign in. Your other sessions stay signed in, and we emailed theo.marsh@saltgrass.co to confirm the change.');
    setView('done');
  }, reduce ? 200 : 950);
}

/* ---------- link expiry ---------- */
const deadline = Date.now() + 59 * 60000;
function tick() {
  const left = Math.max(0, deadline - Date.now());
  const m = Math.floor(left / 60000), s = Math.floor((left % 60000) / 1000);
  bind('left', left ? `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : 'expired');
  if (!left && !S.expired) { S.expired = true; }
}
const iv = setInterval(() => { if (!root.isConnected) return void clearInterval(iv); tick(); }, 1000);

/* ---------- events ---------- */
form.addEventListener('submit', submit);
[pw, cf].forEach((inp) => inp.addEventListener('input', () => { S.typing++; inp.removeAttribute('aria-invalid'); if (errEl.textContent) errEl.textContent = ''; update(); }));
root.addEventListener('click', (e) => {
  const a = e.target.closest('[data-act]'); if (!a) return;
  switch (a.dataset.act) {
    case 'suggest': suggest(); break;
    case 'reveal': setReveal(a.getAttribute('aria-pressed') !== 'true'); break;
    case 'notme': setView('cancel'); break;
    case 'undo': setView('set'); pw.focus(); break;
    case 'restart': pw.value = ''; cf.value = ''; setReveal(false); update(); setView('set'); pw.focus(); break;
  }
});
root.addEventListener('keydown', (e) => {
  if (!e.altKey || e.metaKey || e.ctrlKey) return;
  if (e.code === 'KeyG') { e.preventDefault(); suggest(); }
  else if (e.code === 'KeyV') { e.preventDefault(); setReveal(pw.type === 'password'); }
});

update(); tick();

