/* Team invite. Re-theme with --apa-invite-bg, -card, -ink and -accent. */
.apa-invite {
  --apa-invite-bg: oklch(0.962 0.048 98);
  --apa-invite-card: oklch(0.995 0.006 95);
  --apa-invite-ink: oklch(0.2 0.022 270);
  --apa-invite-accent: oklch(0.49 0.2 263);

  --apa-invite-muted: color-mix(in oklch, var(--apa-invite-ink) 62%, var(--apa-invite-bg));
  --apa-invite-faint: color-mix(in oklch, var(--apa-invite-ink) 42%, var(--apa-invite-bg));
  --apa-invite-rule: color-mix(in oklch, var(--apa-invite-ink) 11%, transparent);
  --apa-invite-rule2: color-mix(in oklch, var(--apa-invite-ink) 20%, transparent);
  --apa-invite-side: color-mix(in oklch, var(--apa-invite-bg) 70%, var(--apa-invite-card));
  --apa-invite-warn: oklch(0.55 0.19 28);
  --apa-invite-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-invite-spring: linear(0, 0.08 4%, 0.3 9%, 0.7 16%, 0.96 23%, 1.07 29%, 1.09 35%, 1.05 43%, 1.01 54%, 0.995 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-invite-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-invite-bg);
  color: var(--apa-invite-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apa-invite-accent);
  outline: none;
}
:where(.apa-invite) *, :where(.apa-invite) *::before, :where(.apa-invite) *::after { box-sizing: border-box; }
:where(.apa-invite) :is(button, input, select) { font: inherit; color: inherit; }
:where(.apa-invite) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-invite) :is(p, h1, ul, dl, dd, blockquote, fieldset) { margin: 0; padding: 0; }
:where(.apa-invite) ul { list-style: none; }
:where(.apa-invite) fieldset { border: 0; min-width: 0; }
:where(.apa-invite) legend { padding: 0; }
:where(.apa-invite) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-invite) :focus-visible { outline: 2px solid var(--apa-invite-accent); outline-offset: 2px; }
:where(.apa-invite) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 11%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 16%, transparent);
}
.apa-invite [hidden] { display: none !important; }
.apa-invite__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- shell ---------- */
.apa-invite__app { display: grid; height: 100%; grid-template: "team flow" minmax(0, 1fr) / minmax(0, 1fr) minmax(420px, 0.95fr); }
.apa-invite__tabs { display: none; }
.apa-invite__team { grid-area: team; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; margin: 10px 0 10px 10px; border-radius: 14px; background: var(--apa-invite-side); box-shadow: inset 0 0 0 1px var(--apa-invite-rule); }
.apa-invite__flow { grid-area: flow; display: grid; grid-template-rows: minmax(0, 1fr) auto; min-height: 0; min-width: 0; }

/* ---------- team pane ---------- */
.apa-invite__ws { display: flex; align-items: center; gap: 12px; padding: 16px 18px 12px; border-bottom: 1px solid var(--apa-invite-rule); }
.apa-invite__wslogo { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 11px; background: var(--apa-invite-accent); color: white; font-weight: 800; font-size: 14px; letter-spacing: .02em; flex: none; }
.apa-invite__wsname b { display: block; font-weight: 750; font-size: 15.5px; letter-spacing: -.015em; }
.apa-invite__wsname small { display: block; font-size: 12.5px; color: var(--apa-invite-muted); font-variant-numeric: tabular-nums; }
.apa-invite__num { display: inline-block; }
.apa-invite__num.is-bump { animation: apa-invite-bump .6s var(--apa-invite-spring); color: var(--apa-invite-accent); font-weight: 700; }
.apa-invite__plinth { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; color: var(--apa-invite-muted); }
.apa-invite__plinth svg { width: 16px; height: 16px; }
.apa-invite__scroll { min-height: 0; overflow: auto; padding: 12px 14px 18px; scrollbar-width: thin; overscroll-behavior: contain; }
.apa-invite__sh { font-size: 11px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--apa-invite-faint); padding: 4px 4px 8px; }
.apa-invite__roster { display: grid; grid-template-columns: repeat(auto-fill, minmax(158px, 1fr)); gap: 8px; margin-bottom: 18px; }
.apa-invite__tile {
  position: relative; display: grid; grid-template-columns: 38px minmax(0, 1fr); grid-template-rows: auto auto; column-gap: 10px; align-items: center;
  padding: 10px 12px 10px 10px; border-radius: 12px; background: var(--apa-invite-card); box-shadow: 0 0 0 1px var(--apa-invite-rule), 0 1px 0 var(--apa-invite-rule);
  transition: box-shadow .25s, translate .3s var(--apa-invite-spring);
}
.apa-invite__roster .apa-invite__tile { animation: apa-invite-in .5s var(--apa-invite-ease) both; animation-delay: calc(var(--i, 0) * 28ms); }
.apa-invite__roster.is-settled .apa-invite__tile { animation: none; }
.apa-invite__tile:hover { box-shadow: 0 0 0 1px var(--apa-invite-rule2), 0 6px 14px -10px var(--apa-invite-ink); translate: 0 -1px; }
.apa-invite__tav { grid-row: span 2; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; background: var(--c, var(--apa-invite-accent)); color: white; font-weight: 750; font-size: 13px; letter-spacing: .02em; transition: background-color .35s; }
.apa-invite__tname { font-size: 13px; font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; align-self: end; }
.apa-invite__ttitle { font-size: 11.5px; color: var(--apa-invite-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; align-self: start; }
.apa-invite__presence { position: absolute; left: 38px; top: 36px; width: 11px; height: 11px; border-radius: 50%; background: oklch(0.7 0.16 150); box-shadow: 0 0 0 2.5px var(--apa-invite-card); scale: 0; }
.apa-invite__tile[data-online] .apa-invite__presence, .apa-invite__tile--me .apa-invite__presence { scale: 1; }
.apa-invite__tile.is-you { box-shadow: 0 0 0 2px var(--apa-invite-accent), 0 10px 22px -14px var(--apa-invite-accent); }
.apa-invite__tile.is-you .apa-invite__tname::after { content: "You"; margin-left: 6px; font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--apa-invite-accent); }
.apa-invite__tile.is-ghost { opacity: 0; }
.apa-invite__flyer { position: absolute; z-index: 20; margin: 0; pointer-events: none; transform-origin: 0 0; box-shadow: 0 0 0 2px var(--apa-invite-accent), 0 24px 40px -18px var(--apa-invite-ink); }
.apa-invite__feed { display: grid; gap: 2px; }
.apa-invite__feed li { display: flex; gap: 10px; align-items: baseline; padding: 7px 6px; border-radius: 8px; font-size: 12.5px; color: var(--apa-invite-muted); text-wrap: pretty; }
.apa-invite__feed li b { color: var(--apa-invite-ink); font-weight: 620; }
.apa-invite__feed li time { margin-left: auto; flex: none; font-size: 11.5px; color: var(--apa-invite-faint); font-variant-numeric: tabular-nums; }
.apa-invite__feed li.is-new { animation: apa-invite-feed 1.8s var(--apa-invite-ease); }

/* ---------- flow pane ---------- */
.apa-invite__view { min-height: 0; overflow: auto; padding: 26px clamp(18px, 3.4cqi, 40px) 18px; display: grid; align-content: start; scrollbar-width: thin; overscroll-behavior: contain; animation: apa-invite-in .5s var(--apa-invite-ease) both; }
.apa-invite__view:is([data-v="invite"], [data-v="joined"], [data-v="declined"]) { align-content: safe center; }
.apa-invite__card { display: grid; gap: 0; padding: 22px 24px 22px; border-radius: 18px; background: var(--apa-invite-card); box-shadow: 0 0 0 1px var(--apa-invite-rule), 0 30px 50px -40px var(--apa-invite-ink); }
.apa-invite__from { display: flex; align-items: center; gap: 12px; }
.apa-invite__from b { display: block; font-weight: 650; }
.apa-invite__from small { display: block; font-size: 12.5px; color: var(--apa-invite-muted); }
.apa-invite__av { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--c); color: white; font-weight: 750; font-size: 13px; flex: none; }
.apa-invite__h { margin-top: 18px; font-size: clamp(27px, 1rem + 2cqi, 38px); line-height: 1.04; font-weight: 780; letter-spacing: -.04em; text-wrap: balance; outline: none; }
.apa-invite__h u {
  text-decoration: none; padding: 0 .05em; margin: 0 -.05em;
  background: linear-gradient(transparent 58%, color-mix(in oklch, var(--apa-invite-accent) 26%, transparent) 0 90%, transparent 0) no-repeat 0 0 / 100% 100%;
  -webkit-box-decoration-break: clone; box-decoration-break: clone;
  transition: background-size .9s .25s cubic-bezier(.2, .8, .2, 1);
  @starting-style { background-size: 0% 100%; }
}
.apa-invite__h--sm { font-size: clamp(23px, 0.9rem + 1.5cqi, 30px); margin-top: 8px; }
.apa-invite__note { position: relative; margin-top: 16px; padding: 12px 14px 12px 16px; border-radius: 4px 12px 12px 12px; background: color-mix(in oklch, var(--apa-invite-bg) 70%, var(--apa-invite-card)); font-size: 14px; line-height: 1.5; text-wrap: pretty; }
.apa-invite__note::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; border-radius: 3px; background: oklch(0.6 0.16 30); }
.apa-invite__meta { display: grid; grid-template-columns: repeat(3, auto); justify-content: start; gap: 4px 24px; margin: 16px 0 0; }
.apa-invite__meta dt { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apa-invite-faint); }
.apa-invite__meta dd { margin: 2px 0 0; font-size: 13px; font-weight: 560; overflow-wrap: anywhere; }
.apa-invite__role { display: inline-block; padding: 1px 8px; border-radius: 6px; background: color-mix(in oklch, var(--apa-invite-accent) 12%, transparent); color: var(--apa-invite-accent); font-weight: 700; }
.apa-invite__faces { display: flex; align-items: center; gap: 12px; margin-top: 18px; padding-top: 16px; border-top: 1px dashed var(--apa-invite-rule2); font-size: 13px; color: var(--apa-invite-muted); }
.apa-invite__faces b { color: var(--apa-invite-ink); font-weight: 620; }
.apa-invite__stack { display: flex; }
.apa-invite__stack i { display: grid; place-items: center; width: 30px; height: 30px; margin-left: -8px; border-radius: 50%; background: var(--c); color: white; font: 750 10.5px/1 system-ui, sans-serif; font-style: normal; box-shadow: 0 0 0 2.5px var(--apa-invite-card); animation: apa-invite-pop .5s var(--apa-invite-spring) both; animation-delay: calc(200ms + var(--i) * 70ms); }
.apa-invite__stack i:first-child { margin-left: 0; }
.apa-invite__actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 20px; }
.apa-invite__btn {
  display: inline-flex; align-items: center; gap: 10px; height: 46px; padding: 0 18px; border-radius: 12px;
  background: var(--apa-invite-accent); color: white; font-weight: 700; font-size: 14.5px;
  box-shadow: 0 12px 24px -14px var(--apa-invite-accent), inset 0 1px 0 color-mix(in oklch, white 25%, transparent);
  transition: scale .3s var(--apa-invite-spring), filter .2s;
}
.apa-invite__btn:hover { filter: brightness(1.08); }
.apa-invite__btn:active { scale: .97; }
.apa-invite__btn kbd { background: color-mix(in oklch, white 20%, transparent); box-shadow: none; }
.apa-invite__btn--warn { background: var(--apa-invite-warn); box-shadow: 0 12px 24px -14px var(--apa-invite-warn); height: 40px; }
.apa-invite__ghost { display: inline-flex; align-items: center; gap: 8px; height: 46px; padding: 0 16px; border-radius: 12px; font-weight: 620; box-shadow: inset 0 0 0 1.5px var(--apa-invite-rule2); transition: background-color .2s; }
.apa-invite__ghost:hover { background: color-mix(in oklch, var(--apa-invite-ink) 5%, transparent); }
.apa-invite__link { margin-left: auto; font-size: 13px; font-weight: 600; color: var(--apa-invite-muted); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--apa-invite-rule2); }
.apa-invite__link:hover { color: var(--apa-invite-ink); }
.apa-invite__notme { margin-top: 12px; padding: 10px 12px; border-radius: 10px; font-size: 13px; color: var(--apa-invite-muted); background: color-mix(in oklch, var(--apa-invite-bg) 60%, var(--apa-invite-card)); text-wrap: pretty; transition: opacity .3s, translate .4s var(--apa-invite-ease); }
@starting-style { .apa-invite__notme { opacity: 0; translate: 0 -6px; } }
.apa-invite__notme b { color: var(--apa-invite-ink); font-weight: 620; overflow-wrap: anywhere; }

/* profile form */
.apa-invite__form { display: grid; }
.apa-invite__kick { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--apa-invite-accent); }
.apa-invite__preview { display: grid; grid-template-columns: minmax(170px, 210px) 1fr; gap: 16px; align-items: center; margin-top: 16px; padding: 14px; border-radius: 14px; background: var(--apa-invite-side); box-shadow: inset 0 0 0 1px var(--apa-invite-rule); }
.apa-invite__tile--me { box-shadow: 0 0 0 2px var(--apa-invite-accent), 0 10px 22px -14px var(--apa-invite-accent); }
.apa-invite__prevnote { font-size: 12.5px; color: var(--apa-invite-muted); text-wrap: pretty; }
.apa-invite__prevnote b { color: var(--apa-invite-ink); font-weight: 620; }
.apa-invite__grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 16px; }
.apa-invite__field { display: grid; gap: 6px; }
.apa-invite__field > span, .apa-invite legend { font-size: 12.5px; font-weight: 650; }
.apa-invite__field input { height: 42px; padding: 0 12px; border-radius: 10px; border: 1.5px solid var(--apa-invite-rule2); background: var(--apa-invite-card); outline: none; transition: border-color .2s, box-shadow .25s; }
.apa-invite__field input:focus { border-color: var(--apa-invite-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-invite-accent) 15%, transparent); }
.apa-invite__field input[aria-invalid="true"] { border-color: var(--apa-invite-warn); }
.apa-invite__swatches { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.apa-invite__swatches legend { margin-bottom: 8px; }
.apa-invite__swatches label { position: relative; width: 30px; height: 30px; border-radius: 50%; background: var(--c); cursor: pointer; transition: scale .3s var(--apa-invite-spring), box-shadow .25s; }
.apa-invite__swatches label:hover { scale: 1.1; }
.apa-invite__swatches input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
.apa-invite__swatches label:has(input:checked) { box-shadow: 0 0 0 3px var(--apa-invite-bg), 0 0 0 5px var(--c); }
.apa-invite__swatches label:has(input:focus-visible) { outline: 2px solid var(--apa-invite-ink); outline-offset: 5px; }
.apa-invite__spaces { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: 14px; }
.apa-invite__spaces legend { margin-bottom: 8px; }
.apa-invite__spaces label { display: flex; gap: 10px; align-items: flex-start; padding: 9px 11px; border-radius: 10px; cursor: pointer; background: var(--apa-invite-card); box-shadow: inset 0 0 0 1px var(--apa-invite-rule); transition: box-shadow .2s; }
.apa-invite__spaces label:has(input:checked) { box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apa-invite-accent) 55%, transparent); }
.apa-invite__spaces label:has(input:disabled) { cursor: default; }
.apa-invite__spaces input { width: 16px; height: 16px; margin: 2px 0 0; flex: none; }
.apa-invite__spaces b { display: block; font-size: 13px; font-weight: 650; }
.apa-invite__spaces small { display: block; font-size: 11.5px; color: var(--apa-invite-muted); }
.apa-invite__err { margin-top: 10px; font-size: 13px; color: var(--apa-invite-warn); font-weight: 560; }
.apa-invite__err:empty { display: none; }

/* joined */
.apa-invite__card--done { gap: 0; }
.apa-invite__card--done .apa-invite__h { margin-top: 8px; }
.apa-invite__p { margin-top: 10px; color: var(--apa-invite-muted); text-wrap: pretty; }
.apa-invite__p b { color: var(--apa-invite-ink); font-variant-numeric: tabular-nums; }
.apa-invite__joined { display: grid; gap: 6px; margin-top: 16px; }
.apa-invite__joined li { display: flex; justify-content: space-between; gap: 10px; padding: 10px 12px; border-radius: 10px; background: color-mix(in oklch, var(--apa-invite-bg) 55%, var(--apa-invite-card)); font-size: 13px; animation: apa-invite-in .45s var(--apa-invite-ease) both; animation-delay: calc(300ms + var(--i) * 70ms); }
.apa-invite__joined b { font-weight: 650; }
.apa-invite__joined span { color: var(--apa-invite-muted); font-variant-numeric: tabular-nums; }

.apa-invite__foot { display: flex; align-items: center; justify-content: center; gap: 4px; padding: 8px 16px 14px; font-size: 11.5px; color: var(--apa-invite-faint); }
.apa-invite__foot kbd:nth-of-type(2), .apa-invite__foot kbd:nth-of-type(3) { margin-left: 10px; }
.apa-invite__foot kbd:nth-of-type(4) { margin-left: 2px; }

/* decline sheet + toast */
.apa-invite__layer { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, var(--apa-invite-ink) 32%, transparent); transition: opacity .3s; }
@starting-style { .apa-invite__layer { opacity: 0; } }
.apa-invite__sheet { width: min(380px, 100%); display: grid; gap: 6px; padding: 22px; border-radius: 18px; background: var(--apa-invite-card); box-shadow: 0 30px 60px -30px var(--apa-invite-ink); transition: translate .5s var(--apa-invite-spring), scale .5s var(--apa-invite-spring), opacity .3s; }
@starting-style { .apa-invite__sheet { translate: 0 18px; scale: .97; opacity: 0; } }
.apa-invite__sheett { font-size: 17px; font-weight: 750; letter-spacing: -.015em; }
.apa-invite__sheetm { font-size: 13px; color: var(--apa-invite-muted); }
.apa-invite__reasons { display: grid; gap: 6px; margin: 10px 0 6px; }
.apa-invite__reasons label { display: flex; gap: 10px; align-items: center; padding: 9px 11px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--apa-invite-rule); font-size: 13.5px; cursor: pointer; }
.apa-invite__reasons label:has(input:checked) { box-shadow: inset 0 0 0 1.5px var(--apa-invite-warn); }
.apa-invite__reasons input { accent-color: var(--apa-invite-warn); margin: 0; }
.apa-invite__sheetact { display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px; }
.apa-invite__sheetact .apa-invite__ghost { height: 40px; }
.apa-invite__toast {
  position: absolute; z-index: 25; left: 50%; bottom: 18px; translate: -50% 0; overflow: hidden; display: flex; align-items: center; gap: 14px; padding: 10px 10px 12px 16px; border-radius: 12px;
  background: var(--apa-invite-ink); color: var(--apa-invite-card); font-size: 13.5px; box-shadow: 0 18px 34px -18px var(--apa-invite-ink); white-space: nowrap;
  transition: translate .5s var(--apa-invite-spring), opacity .3s;
}
@starting-style { .apa-invite__toast { translate: -50% 16px; opacity: 0; } }
.apa-invite__toast button { height: 30px; padding: 0 12px; border-radius: 8px; background: var(--apa-invite-card); color: var(--apa-invite-ink); font-weight: 700; font-size: 12.5px; }
.apa-invite__drain { position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: oklch(0.82 0.15 95); transform-origin: 0 50%; animation: apa-invite-drain 6s linear forwards; }

/* ---------- keyframes ---------- */
@keyframes apa-invite-in { from { opacity: 0; translate: 0 10px; } }
@keyframes apa-invite-pop { from { scale: .3; opacity: 0; } }
@keyframes apa-invite-bump { 30% { scale: 1.35; } }
@keyframes apa-invite-feed { 0%, 35% { background: color-mix(in oklch, var(--apa-invite-accent) 12%, transparent); } }
@keyframes apa-invite-drain { to { scale: 0 1; } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-invite__app { grid-template-columns: minmax(0, .8fr) minmax(400px, 1fr); }
  .apa-invite__roster { grid-template-columns: 1fr; }
  .apa-invite__meta { grid-template-columns: repeat(2, auto); }
  .apa-invite__preview { grid-template-columns: 1fr; }
  .apa-invite__spaces { grid-template-columns: 1fr; }
  .apa-invite__plinth { display: none; }
}
/* ---------- container: single pane ---------- */
@container (max-width: 759px) {
  .apa-invite__app { grid-template: "tabs" auto "flow" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-invite__tabs { grid-area: tabs; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 12px 12px 0; padding: 4px; border-radius: 12px; background: color-mix(in oklch, var(--apa-invite-ink) 7%, transparent); }
  .apa-invite__tabs button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 34px; border-radius: 9px; font-size: 13px; font-weight: 640; color: var(--apa-invite-muted); }
  .apa-invite__tabs button b { font-variant-numeric: tabular-nums; font-size: 11.5px; padding: 1px 6px; border-radius: 6px; background: var(--apa-invite-rule); }
  .apa-invite__tabs button[aria-selected="true"] { background: var(--apa-invite-card); color: var(--apa-invite-ink); box-shadow: 0 1px 3px var(--apa-invite-rule2); }
  .apa-invite__team { grid-area: flow; margin: 10px; }
  .apa-invite[data-tab="flow"] .apa-invite__team, .apa-invite[data-tab="team"] .apa-invite__flow { display: none; }
  .apa-invite__foot { display: none; }
  .apa-invite__view { padding: 14px 12px 14px; }
}
@container (max-width: 520px) {
  .apa-invite__card { padding: 18px 16px; }
  .apa-invite__meta { grid-template-columns: 1fr 1fr; }
  .apa-invite__meta div:nth-child(2) { grid-column: 1 / -1; grid-row: 2; }
  .apa-invite__grid, .apa-invite__spaces, .apa-invite__preview { grid-template-columns: 1fr; }
  .apa-invite__roster { grid-template-columns: 1fr; }
  .apa-invite__link { margin-left: 0; }
  .apa-invite__btn kbd { display: none; }
  .apa-invite__ws { padding: 12px 14px; }
}

/* ---------- reduced motion: the tile appears in place, nothing flies ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-invite *, .apa-invite *::before, .apa-invite *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
  .apa-invite__drain { animation: none !important; }
}

