// Presentational only: accepting or declining changes nothing outside this component.
root.addEventListener('submit', (e) => e.preventDefault());
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const bind = (k, v) => $$(`[data-bind="${k}"]`).forEach((el) => { el.textContent = v; });
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const narrow = () => root.getBoundingClientRect().width < 760;

const COLORS = ['oklch(0.5 0.2 263)', 'oklch(0.6 0.19 35)', 'oklch(0.6 0.13 165)', 'oklch(0.7 0.14 80)', 'oklch(0.62 0.15 355)', 'oklch(0.42 0.03 260)'];
const TEAM = [
  { id: 'ade', name: 'Ade Bankole', title: 'Fleet manager', c: 'oklch(0.55 0.13 165)', online: true },
  { id: 'bea', name: 'Bea Lindqvist', title: 'Yard supervisor', c: 'oklch(0.68 0.14 80)' },
  { id: 'carmen', name: 'Carmen Ruiz', title: 'Driver pay', c: 'oklch(0.6 0.15 355)' },
  { id: 'dmitri', name: 'Dmitri Vole', title: 'Workshop lead', c: 'oklch(0.45 0.04 260)', online: true },
  { id: 'elif', name: 'Elif Kaya', title: 'Customer desk', c: 'oklch(0.6 0.17 40)' },
  { id: 'hugo', name: 'Hugo Brandt', title: 'Night dispatcher', c: 'oklch(0.5 0.18 263)' },
  { id: 'joel', name: 'Joel Achterberg', title: 'Ops analyst', c: 'oklch(0.58 0.11 205)' },
  { id: 'mina', name: 'Mina Park', title: 'Route planner', c: 'oklch(0.62 0.14 140)', online: true },
  { id: 'priya', name: 'Priya Raman', title: 'Ops lead · admin', c: 'oklch(0.6 0.16 30)', online: true, admin: true },
  { id: 'rafael', name: 'Rafael Sousa', title: 'Day dispatcher', c: 'oklch(0.52 0.13 330)' },
  { id: 'tomasz', name: 'Tomasz Wilk', title: 'Safety & compliance', c: 'oklch(0.64 0.12 60)' },
];
const FEED0 = [
  ['<b>Priya Raman</b> invited <b>sam.okoro@marlowefreight.com</b> as Dispatcher', '2d'],
  ['<b>Mina Park</b> created <b>#yard-ops</b>', '6d'],
  ['<b>Hugo Brandt</b> pinned the night handover checklist', '1w'],
];
const SPACES = { 'night-dispatch': 4, 'fleet-status': 11, 'driver-pay': 6, 'yard-ops': 5 };
const S = { view: 'invite', tab: 'flow', joined: false, busy: false, layer: false, feed: FEED0.slice() };
const form = $('.apa-invite__form');
const F = form.elements;
const rosterEl = $('.apa-invite__roster'), feedEl = $('.apa-invite__feed');

const initials = (n) => n.trim().split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0].toUpperCase()).join('') || '?';
const first = (n) => n.trim().split(/\s+/)[0] || 'there';
const me = () => ({ id: 'me', name: F.name.value.trim() || 'New member', title: F.title.value.trim() || 'Dispatcher', c: COLORS[Number(form.querySelector('[name="color"]:checked').value)], online: true, you: true });
const members = () => (S.joined ? TEAM.concat(me()) : TEAM.slice()).sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }));

/* ---------- render ---------- */
function tileHTML(m, i) {
  return `<li><div class="apa-invite__tile${m.you ? ' is-you' : ''}" data-id="${m.id}" style="--c:${m.c};--i:${i}"${m.online ? ' data-online' : ''}${m.admin ? ' data-admin' : ''}>
    <span class="apa-invite__tav">${esc(initials(m.name))}</span><span class="apa-invite__tname">${esc(m.name)}</span><span class="apa-invite__ttitle">${esc(m.title)}</span><i class="apa-invite__presence" aria-hidden="true"></i></div></li>`;
}
function renderRoster() {
  const list = members();
  rosterEl.innerHTML = list.map(tileHTML).join('');
  bind('count', list.length);
  bind('online', list.filter((m) => m.online).length);
}
function renderFeed(fresh) {
  feedEl.innerHTML = S.feed.map((f, i) => `<li${fresh && i === 0 ? ' class="is-new"' : ''}><span>${f[0]}</span><time>${f[1]}</time></li>`).join('');
}
function renderPreview() {
  const m = me();
  const tile = $('[data-me]'), av = tile.querySelector('.apa-invite__tav');
  av.textContent = initials(m.name); tile.style.setProperty('--c', m.c);
  bind('mename', m.name); bind('metitle', m.title); bind('first', first(m.name));
  const sorted = TEAM.concat(m).sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }));
  const i = sorted.indexOf(m), prev = sorted[i - 1], next = sorted[i + 1];
  bind('slot', !prev ? `first, before ${first(next.name)}` : !next ? `last, after ${first(prev.name)}` : `between ${first(prev.name)} and ${first(next.name)}`);
}
function setView(v, focus = true) {
  S.view = v; root.dataset.view = v;
  $$('.apa-invite__view').forEach((x) => { x.hidden = x.dataset.v !== v; });
  $('.apa-invite__tabs [data-tab="flow"]').textContent = { invite: 'Invitation', profile: 'Your profile', joined: 'Welcome', declined: 'Invitation' }[v];
