/* SSO organisation picker. Re-theme with --apa-sso-bg, -ink, -accent and -ok. */
.apa-sso {
  --apa-sso-bg: oklch(0.165 0.004 60);
  --apa-sso-ink: oklch(0.965 0.004 80);
  --apa-sso-accent: oklch(0.66 0.21 33);
  --apa-sso-ok: oklch(0.8 0.15 152);

  --apa-sso-panel: color-mix(in oklch, var(--apa-sso-ink) 4%, var(--apa-sso-bg));
  --apa-sso-line: color-mix(in oklch, var(--apa-sso-ink) 12%, transparent);
  --apa-sso-line2: color-mix(in oklch, var(--apa-sso-ink) 22%, transparent);
  --apa-sso-muted: color-mix(in oklch, var(--apa-sso-ink) 60%, var(--apa-sso-bg));
  --apa-sso-faint: color-mix(in oklch, var(--apa-sso-ink) 38%, var(--apa-sso-bg));
  --apa-sso-bad: oklch(0.7 0.18 25);
  --apa-sso-mono: ui-monospace, Menlo, monospace;
  --apa-sso-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-sso-spring: linear(0, 0.08 4%, 0.3 9%, 0.7 16%, 0.96 23%, 1.07 29%, 1.09 35%, 1.05 43%, 1.01 54%, 0.995 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-sso-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-sso-bg);
  color: var(--apa-sso-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
  accent-color: var(--apa-sso-accent);
  outline: none;
}
:where(.apa-sso) *, :where(.apa-sso) *::before, :where(.apa-sso) *::after { box-sizing: border-box; }
:where(.apa-sso) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-sso) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-sso) :is(p, h1, h2, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
:where(.apa-sso) :is(ul, ol) { list-style: none; }
:where(.apa-sso) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-sso) :focus-visible { outline: 2px solid var(--apa-sso-accent); outline-offset: 2px; }
:where(.apa-sso) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 4px;
  font: 500 10.5px/1 var(--apa-sso-mono); color: inherit;
  background: color-mix(in oklch, currentColor 12%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 18%, transparent);
}
.apa-sso [hidden] { display: none !important; }
.apa-sso mark { background: none; color: var(--apa-sso-accent); text-decoration: underline; text-decoration-thickness: 1.5px; text-underline-offset: 3px; }

/* ---------- shell ---------- */
.apa-sso__app { display: grid; height: 100%; grid-template: "list detail" minmax(0, 1fr) / minmax(330px, 400px) minmax(0, 1fr); }
.apa-sso__list { grid-area: list; display: flex; flex-direction: column; min-height: 0; min-width: 0; padding: 22px 0 0; border-right: 1px solid var(--apa-sso-line); }
.apa-sso__list > * { flex: none; }
.apa-sso__list > .apa-sso__results { flex: 1 1 0; }
.apa-sso__detail { grid-area: detail; position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 0; min-width: 0; }

/* ---------- list pane ---------- */
.apa-sso__brand { display: flex; align-items: center; gap: 8px; padding: 0 22px; }
.apa-sso__brand b { font-weight: 800; font-size: 16px; letter-spacing: -.02em; }
.apa-sso__logo { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--apa-sso-accent); color: var(--apa-sso-bg); }
.apa-sso__logo svg { width: 18px; height: 18px; stroke-width: 2.4; }
.apa-sso__tag { margin-left: auto; font: 600 10.5px/1 var(--apa-sso-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--apa-sso-faint); }
.apa-sso__h { padding: 22px 22px 14px; font-size: clamp(22px, 0.9rem + 1.3cqi, 28px); line-height: 1.05; font-weight: 780; letter-spacing: -.035em; text-wrap: balance; }
