.apa-sso__detect { margin: 10px 22px 0; padding: 9px 12px; border-radius: 8px; font-size: 12.5px; background: color-mix(in oklch, var(--apa-sso-ok) 12%, transparent); color: var(--apa-sso-ink); text-wrap: pretty; transition: opacity .3s, translate .4s var(--apa-sso-ease); }
@starting-style { .apa-sso__detect { opacity: 0; translate: 0 -4px; } }
