.apa-sso__detect[data-tone="warn"] b { color: var(--apa-sso-accent); }
.apa-sso__results { min-height: 0; overflow: auto; padding: 14px 12px 12px; scrollbar-width: thin; scrollbar-color: var(--apa-sso-line2) transparent; overscroll-behavior: contain; }
.apa-sso__sect { padding: 6px 10px 6px; font: 600 10.5px/1 var(--apa-sso-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--apa-sso-faint); }
.apa-sso__sect + .apa-sso__opt, .apa-sso__opt + .apa-sso__sect { margin-top: 0; }
.apa-sso__opt + .apa-sso__sect { margin-top: 12px; }
.apa-sso__opt {
  position: relative; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 9px 10px; border-radius: 10px; cursor: pointer;
  transition: background-color .15s;
  animation: apa-sso-in .35s var(--apa-sso-ease) both; animation-delay: calc(var(--i, 0) * 25ms);
}
.apa-sso__opt:hover { background: color-mix(in oklch, var(--apa-sso-ink) 4%, transparent); }
.apa-sso__opt[data-active] { background: color-mix(in oklch, var(--apa-sso-ink) 8%, transparent); }
.apa-sso__opt[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--apa-sso-accent); }
.apa-sso__otext { min-width: 0; }
