.apa-sso__forget { position: absolute; right: 8px; top: 50%; translate: 0 -50%; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--apa-sso-muted); background: var(--apa-sso-bg); opacity: 0; transition: opacity .15s, background-color .15s; }
.apa-sso__forget svg { width: 14px; height: 14px; }
.apa-sso__opt:hover .apa-sso__forget, .apa-sso__opt[data-active] .apa-sso__forget { opacity: 1; }
.apa-sso__opt:has(.apa-sso__forget):is(:hover, [data-active]) .apa-sso__ometa { opacity: 0; }
