.apa-sso__node[data-ok] rect { stroke: var(--apa-sso-ok); fill: color-mix(in oklch, var(--apa-sso-ok) 12%, var(--apa-sso-bg)); }
.apa-sso__node[data-wait] rect { animation: apa-sso-wait 1s ease-in-out infinite alternate; }
.apa-sso__lane { stroke: var(--apa-sso-line2); stroke-width: 1.2; stroke-dasharray: 3 5; fill: none; }
.apa-sso__lane[data-done] { stroke: color-mix(in oklch, var(--apa-sso-accent) 70%, transparent); stroke-dasharray: none; }
.apa-sso__arrow { fill: var(--apa-sso-line2); stroke: none; }
.apa-sso__pkt { fill: var(--apa-sso-accent); stroke: none; filter: drop-shadow(0 0 6px var(--apa-sso-accent)); opacity: 0; }
.apa-sso__pktl { fill: var(--apa-sso-accent); stroke: none; font: 600 9.5px/1 var(--apa-sso-mono); letter-spacing: .04em; opacity: 0; }

.apa-sso__steps { display: grid; gap: 2px; counter-reset: st; }
.apa-sso__steps li { counter-increment: st; display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 5px 0; font-size: 13px; color: var(--apa-sso-faint); transition: color .3s; }
.apa-sso__steps li::before { content: counter(st); display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; font: 600 10.5px/1 var(--apa-sso-mono); box-shadow: inset 0 0 0 1.2px currentColor; transition: background-color .3s, color .3s, box-shadow .3s; }
.apa-sso__steps li small { font: 500 11px/1 var(--apa-sso-mono); color: var(--apa-sso-faint); font-variant-numeric: tabular-nums; }
.apa-sso__steps li[data-s="run"] { color: var(--apa-sso-ink); }
.apa-sso__steps li[data-s="run"]::before { box-shadow: inset 0 0 0 1.2px var(--apa-sso-accent); color: var(--apa-sso-accent); animation: apa-sso-pulse 1s ease-in-out infinite; }
.apa-sso__steps li[data-s="ok"] { color: var(--apa-sso-muted); }
.apa-sso__steps li[data-s="ok"]::before { content: "✓"; background: color-mix(in oklch, var(--apa-sso-ok) 18%, transparent); color: var(--apa-sso-ok); box-shadow: none; font-family: system-ui, sans-serif; }
.apa-sso__steps li[data-s="bad"] { color: var(--apa-sso-bad); }
.apa-sso__steps li[data-s="bad"]::before { content: "!"; background: var(--apa-sso-bad); color: var(--apa-sso-bg); box-shadow: none; font-family: system-ui, sans-serif; font-weight: 800; }

.apa-sso__cta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.apa-sso__go {
  display: inline-flex; align-items: center; gap: 10px; height: 46px; padding: 0 18px; border-radius: 10px;
  background: var(--apa-sso-accent); color: var(--apa-sso-bg); font-weight: 750; font-size: 14.5px;
  transition: filter .2s, scale .3s var(--apa-sso-spring);
}
.apa-sso__go:hover { filter: brightness(1.08); }
.apa-sso__go:active { scale: .97; }
.apa-sso__go kbd { background: color-mix(in oklch, var(--apa-sso-bg) 18%, transparent); box-shadow: none; }
.apa-sso__ghost { height: 46px; padding: 0 16px; border-radius: 10px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--apa-sso-line2); transition: background-color .2s; }
.apa-sso__ghost:hover { background: var(--apa-sso-line); }
.apa-sso__note { font-size: 12.5px; color: var(--apa-sso-muted); text-wrap: pretty; }
.apa-sso__note b { color: var(--apa-sso-ink); }
.apa-sso__done { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; align-items: center; padding: 14px 16px; border-radius: 12px; background: color-mix(in oklch, var(--apa-sso-ok) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-sso-ok) 35%, transparent); animation: apa-sso-in .5s var(--apa-sso-ease) both; }
.apa-sso__done i { grid-row: span 2; display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: var(--apa-sso-ok); color: var(--apa-sso-bg); font-style: normal; font-weight: 800; }
.apa-sso__done b { font-weight: 700; }
.apa-sso__done span { font-size: 12.5px; color: var(--apa-sso-muted); }

.apa-sso__toast { position: absolute; z-index: 10; left: 50%; bottom: 18px; translate: -50% 0; display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 14px; border-radius: 10px; background: var(--apa-sso-ink); color: var(--apa-sso-bg); font-size: 13px; font-weight: 550; white-space: nowrap; box-shadow: 0 16px 30px -14px black; transition: translate .45s var(--apa-sso-spring), opacity .3s; }
@starting-style { .apa-sso__toast { translate: -50% 14px; opacity: 0; } }
.apa-sso__toast button { height: 28px; padding: 0 10px; border-radius: 7px; background: var(--apa-sso-accent); color: var(--apa-sso-bg); font-weight: 750; font-size: 12.5px; }

/* ---------- keyframes ---------- */
@keyframes apa-sso-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apa-sso-pulse { 50% { background-color: color-mix(in oklch, var(--apa-sso-accent) 25%, transparent); } }
@keyframes apa-sso-wait { to { stroke-width: 3; } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-sso__app { grid-template-columns: 320px minmax(0, 1fr); }
  .apa-sso__facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .apa-sso__facts div:nth-child(3) { padding-left: 0; border-left: 0; }
  .apa-sso__facts div:nth-child(n+3) { border-top: 1px solid var(--apa-sso-line); }
  .apa-sso__mark--lg { width: 64px; height: 64px; }
  .apa-sso__ometa { display: none; }
}
/* ---------- container: single pane, list then detail ---------- */
@container (max-width: 759px) {
  .apa-sso__app { grid-template: "pane" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-sso__list, .apa-sso__detail { grid-area: pane; border: 0; }
  .apa-sso[data-pane="list"] .apa-sso__detail, .apa-sso[data-pane="detail"] .apa-sso__list { display: none; }
  .apa-sso[data-pane="detail"] .apa-sso__detail { animation: apa-sso-in .4s var(--apa-sso-ease); }
  .apa-sso__back { display: inline-flex; }
  .apa-sso__card { padding-top: 12px; }
  .apa-sso__keys { display: none; }
  .apa-sso__facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .apa-sso__facts div:nth-child(3) { padding-left: 0; border-left: 0; }
  .apa-sso__facts div:nth-child(n+3) { border-top: 1px solid var(--apa-sso-line); }
}
@container (max-width: 440px) {
  .apa-sso__head { grid-template-columns: 1fr; gap: 14px; }
  .apa-sso__mark--lg { width: 56px; height: 56px; border-radius: 12px; }
  .apa-sso__brand, .apa-sso__h { padding-inline: 16px; }
  .apa-sso__search, .apa-sso__detect { margin-inline: 16px; }
  .apa-sso__results { padding-inline: 6px; }
  .apa-sso__ometa { display: none; }
  .apa-sso__go kbd { display: none; }
}

/* ---------- reduced motion: steps tick over without packets flying ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-sso *, .apa-sso *::before, .apa-sso *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
}

