// Presentational only: no identity provider is contacted; the handoff is a simulation of the SAML / OIDC round trip.
const $ = (s) => root.querySelector(s);
const $$ = (s) => Array.from(root.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const later = (fn, ms) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const uid = 'apa-sso-' + Math.random().toString(36).slice(2, 8);
const narrow = () => root.getBoundingClientRect().width < 760;
const nf = new Intl.NumberFormat('en-GB');
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };

const IDP = { K: 'Keystone ID', B: 'Bastion SSO', L: 'Lattice Directory' };
// [id, name, domains, idp, protocol, members, session hours, note]
const RAW = [
  ['halberd', 'Halberd Logistics', ['halberd.io', 'halberd-freight.com'], 'K', 'SAML', 1240, 12, ''],
  ['ostrander', 'Ostrander & Pike LLP', ['ostranderpike.law'], 'B', 'SAML', 86, 8, 'Managed devices only'],
  ['vireo', 'Vireo Health Partners', ['vireohealth.org'], 'L', 'OIDC', 312, 10, ''],
  ['tidewater', 'Tidewater Port Authority', ['tidewaterport.gov'], 'B', 'SAML', 2980, 9, 'Smart card required'],
  ['brightwater', 'Brightwater Transit', ['brightwater-transit.com'], 'K', 'OIDC', 640, 12, ''],
  ['cinderford', 'Cinderford Mills', ['cinderfordmills.co.uk'], 'L', 'SAML', 155, 12, ''],
  ['delacroix', 'Delacroix Fine Foods', ['delacroixfoods.fr'], 'K', 'OIDC', 98, 24, ''],
  ['eastmoor', 'Eastmoor University Hospital', ['eastmoorhospital.org'], 'B', 'SAML', 4210, 8, 'Smart card required'],
  ['fennick', 'Fennick & Daughters', ['fennick.co'], 'L', 'OIDC', 23, 24, ''],
  ['greywell', 'Greywell Insurance Group', ['greywell.com'], 'K', 'SAML', 1875, 10, 'Managed devices only'],
  ['harbinger', 'Harbinger Media', ['harbinger.media'], 'L', 'OIDC', 410, 12, ''],
  ['iverson', 'Iverson Steel', ['iversonsteel.com'], 'B', 'SAML', 730, 12, ''],
  ['juniper', 'Juniper Ridge Schools', ['juniperridge.edu'], 'L', 'OIDC', 1320, 12, ''],
  ['kestrel', 'Kestrel Aerial Survey', ['kestrelsurvey.ie'], 'K', 'OIDC', 57, 24, ''],
  ['lowmoor', 'Lowmoor Energy Co-op', ['lowmoor.coop'], 'L', 'SAML', 212, 12, ''],
  ['meridale', 'Meridale County Council', ['meridale.gov.example'], 'B', 'SAML', 2650, 9, 'Smart card required'],
  ['northgate', 'Northgate Credit Union', ['northgatecu.org'], 'K', 'SAML', 380, 8, 'Managed devices only'],
  ['orrin', 'Orrin Biotech', ['orrinbio.com'], 'L', 'OIDC', 265, 12, ''],
  ['pellham', 'Pellham Architects', ['pellham.studio'], 'K', 'OIDC', 44, 24, ''],
  ['rookwood', 'Rookwood Distillers', ['rookwood.scot'], 'L', 'OIDC', 61, 24, ''],
  ['saltmarsh', 'Saltmarsh Conservancy', ['saltmarsh.org'], 'K', 'OIDC', 120, 12, ''],
  ['thornbury', 'Thornbury Logistics', ['thornbury.co'], 'B', 'SAML', 960, 12, ''],
  ['valecrest', 'Valecrest Dental', ['valecrest.dental'], 'L', 'OIDC', 140, 12, ''],
  ['yarrow', 'Yarrow Seed Bank', ['yarrowseeds.org'], 'K', 'SAML', 35, 24, ''],
];
const ORGS = RAW.map(([id, name, domains, idp, proto, members, hours, note]) => ({ id, name, domains, idp: IDP[idp], proto, members, hours, note }));
const byId = (id) => ORGS.find((o) => o.id === id);
const RECENT0 = [['halberd', '2 days ago'], ['ostrander', 'yesterday'], ['vireo', '3 weeks ago']];
const S = { q: '', recent: RECENT0.slice(), sel: 'halberd', active: 0, pane: 'list', phase: 'idle', attempt: 0, run: 0, opts: [], undo: null };

/* ---------- generated org mark ---------- */
function markSVG(seed) {
  let h = hash(seed), h2 = hash(seed + '#');
  let out = '', filled = 0;
  for (let i = 0; i < 9; i++) {
    if (i === 5) h = hash(seed + '!');
    const t = (h >>> ((i % 5) * 6)) & 7, cls = (h2 >>> i) & 1 ? 'a' : 'b';
    const x = (i % 3) * 10, y = Math.floor(i / 3) * 10;
    let d = '';
    if (t === 1) d = `M${x} ${y}h10v10h-10z`;
    else if (t === 2) d = `M${x + 5} ${y}a5 5 0 1 1 0 10a5 5 0 1 1 0-10z`;
    else if (t === 3) d = `M${x} ${y}h10a10 10 0 0 1-10 10z`;
    else if (t === 4) d = `M${x + 10} ${y}v10a10 10 0 0 1-10-10z`;
    else if (t === 5) d = `M${x + 10} ${y + 10}h-10a10 10 0 0 1 10-10z`;
    else if (t === 6) d = `M${x} ${y + 10}v-10a10 10 0 0 1 10 10z`;
    else if (t === 7) d = `M${x} ${y}h10l-10 10z`;
    if (d) { out += `<path class="${cls}" d="${d}"/>`; filled++; }
  }
  if (filled < 4) out += `<path class="a" d="M10 10h10v10h-10z"/>`;
  return `<svg viewBox="0 0 30 30" aria-hidden="true">${out}</svg>`;
}

/* ---------- fuzzy match with highlight ---------- */
function fuzzy(text, q) {
  const t = text.toLowerCase(); let ti = 0, score = 0, run = 0; const idx = [];
  for (const ch of q.toLowerCase()) {
    if (ch === ' ') continue;
    const at = t.indexOf(ch, ti); if (at < 0) return null;
    run = at === ti ? run + 1 : 0;
    score += 1 + run * 2 + (at === 0 || /[\s&.-]/.test(t[at - 1]) ? 4 : 0) - Math.min(3, (at - ti) * 0.15);
    idx.push(at); ti = at + 1;
  }
  return { score, idx };
}
function hl(text, idx) { if (!idx) return esc(text); let o = ''; for (let i = 0; i < text.length; i++) o += idx.includes(i) ? `<mark>${esc(text[i])}</mark>` : esc(text[i]); return o; }

/* ---------- list ---------- */
const input = $('.apa-sso__q'), listEl = $('.apa-sso__opts'), detect = $('.apa-sso__detect');
input.setAttribute('aria-controls', uid + '-list'); listEl.id = uid + '-list';
function compute() {
  const q = S.q.trim();
  detect.hidden = true; delete detect.dataset.tone;
  if (!q) {
    return { sections: [['On this device', S.recent.map(([id, when]) => ({ o: byId(id), when }))]], hint: true };
  }
  if (q.includes('@')) {
    const dom = q.split('@').pop().toLowerCase();
    const hit = dom && ORGS.find((o) => o.domains.some((d) => d === dom));
    if (hit) {
      detect.hidden = false; detect.innerHTML = `<b>@${esc(dom)}</b> signs in through ${esc(hit.idp)} for ${esc(hit.name)}.`;
      return { sections: [['Your organisation', [{ o: hit, dom: true }]]], auto: hit.id };
    }
    if (/\.[a-z]{2,}$/.test(dom)) {
      detect.hidden = false; detect.dataset.tone = 'warn';
      detect.innerHTML = `No organisation on Corvane uses <b>@${esc(dom)}</b>. Personal accounts sign in with a password.`;
      return { sections: [], none: true };
    }
    return { sections: [], typing: true };
  }
  const scored = ORGS.map((o) => {
    const n = fuzzy(o.name, q), d = fuzzy(o.domains[0], q);
    const best = n && (!d || n.score >= d.score) ? { o, n } : d ? { o, d, s: d.score - 1 } : null;
    if (!best) return null; best.s = best.n ? best.n.score : best.s;
    if (S.recent.some(([id]) => id === o.id)) best.s += 2;
    best.when = (S.recent.find(([id]) => id === o.id) || [])[1];
    return best;
  }).filter(Boolean).sort((a, b) => b.s - a.s).slice(0, 12);
  return { sections: scored.length ? [['Matches', scored]] : [], none: !scored.length };
}
function renderList(keepActive) {
  const r = compute();
  S.opts = r.sections.flatMap(([, items]) => items.map((it) => it.o.id));
  if (!keepActive) S.active = Math.max(0, S.opts.indexOf(S.sel));
  if (S.active >= S.opts.length) S.active = S.opts.length - 1;
  let html = '', n = 0;
  r.sections.forEach(([title, items]) => {
    html += `<li class="apa-sso__sect" role="presentation">${title}</li>`;
    items.forEach((it) => {
      const o = it.o, i = n++, recent = S.recent.some(([id]) => id === o.id);
      const name = it.n ? hl(o.name, it.n.idx) : esc(o.name);
      const dom = it.d ? hl(o.domains[0], it.d.idx) : esc(o.domains[0]);
      html += `<li class="apa-sso__opt" role="option" id="${uid}-o-${o.id}" data-id="${o.id}" style="--i:${i}" aria-selected="${o.id === S.sel}"${i === S.active ? ' data-active' : ''}>
        <span class="apa-sso__mark">${markSVG(o.name)}</span>
        <span class="apa-sso__otext"><b>${name}</b><small>${dom} · ${esc(o.idp)}</small></span>
        <span class="apa-sso__ometa">${it.when ? esc(it.when) : nf.format(o.members) + ' people'}</span>
        ${recent && !S.q ? `<button type="button" class="apa-sso__forget" data-forget="${o.id}" tabindex="-1" aria-label="Forget ${esc(o.name)} on this device"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg></button>` : ''}
      </li>`;
    });
  });
  if (r.hint) html += `<li class="apa-sso__empty" role="presentation">Not listed? Type your work email or search all <b>${ORGS.length} organisations</b> that use single sign-on with Corvane.</li>`;
  if (r.none && !r.sections.length && !S.q.includes('@')) html += `<li class="apa-sso__empty" role="presentation">No organisation matches “<b>${esc(S.q)}</b>”. Try the domain from your work email.</li>`;
  if (r.typing) html += `<li class="apa-sso__empty" role="presentation">Keep typing your work email…</li>`;
  listEl.innerHTML = html;
  const act = S.opts[S.active];
  if (act) input.setAttribute('aria-activedescendant', `${uid}-o-${act}`); else input.removeAttribute('aria-activedescendant');
  if (r.auto && r.auto !== S.sel) select(r.auto, false);
}
function moveActive(d) {
  if (!S.opts.length) return;
  S.active = (S.active + d + S.opts.length) % S.opts.length;
  $$('.apa-sso__opt').forEach((li, i) => li.toggleAttribute('data-active', i === S.active));
  const li = $$('.apa-sso__opt')[S.active];
  input.setAttribute('aria-activedescendant', li.id);
  const box = $('.apa-sso__results'), lr = li.getBoundingClientRect(), br = box.getBoundingClientRect();
  if (lr.bottom > br.bottom) box.scrollTop += lr.bottom - br.bottom + 8; else if (lr.top < br.top) box.scrollTop -= br.top - lr.top + 8;
}

/* ---------- detail ---------- */
const card = $('.apa-sso__card');
const SAML_STEPS = (o) => [`Corvane builds a signed SAML request`, `Your browser is sent to ${o.idp}`, `${o.idp} checks it’s you`, `${o.idp} returns a signed assertion`, `Corvane verifies the signature and signs you in`];
const OIDC_STEPS = (o) => [`Corvane creates an authorisation request with PKCE`, `Your browser is sent to ${o.idp}`, `${o.idp} checks it’s you`, `An authorisation code comes back`, `Corvane swaps the code for tokens and signs you in`];
const LABELS = { SAML: ['AuthnRequest', 'redirect', 'SAMLResponse', 'POST /acs'], OIDC: ['/authorize', 'redirect', '?code=…', 'POST /token'] };
const CHECK = '<svg viewBox="0 0 24 24"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>';

// geometry for the three-party diagram: wide (left to right) or compact (top to bottom)
function geometry(compact) {
  if (!compact) return {
    vb: '0 0 600 150', w: 130, h: 60,
    nodes: [[95, 75], [300, 75], [505, 75]],
    hops: [[160, 58, 232, 58], [368, 58, 437, 58], [437, 92, 368, 92], [232, 92, 160, 92]],
    lbl: (h, i) => [(h[0] + h[2]) / 2, h[1] + (i < 2 ? -10 : 22), 'middle'],
  };
  return {
    vb: '0 0 300 250', w: 200, h: 52,
    nodes: [[150, 35], [150, 125], [150, 215]],
    hops: [[118, 62, 118, 97], [118, 152, 118, 187], [182, 187, 182, 152], [182, 97, 182, 62]],
    lbl: (h, i) => [i < 2 ? h[0] - 10 : h[0] + 10, (h[1] + h[3]) / 2 + 4, i < 2 ? 'end' : 'start'],
  };
}
let G = geometry(false);
function flowSVG(o) {
  G = geometry(root.getBoundingClientRect().width < 600);
  const names = [['Corvane', 'service'], ['Your browser', 'this device'], [o.idp, 'identity provider']];
  return `<svg viewBox="${G.vb}" role="img" aria-label="Sign-in handoff between Corvane, your browser and ${esc(o.idp)}">
    <defs><marker id="${uid}-ar" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path class="apa-sso__arrow" d="M0 0 8 4 0 8z"/></marker></defs>
    ${G.hops.map((h, i) => `<path class="apa-sso__lane" data-hop="${i}" d="M${h[0]} ${h[1]}L${h[2]} ${h[3]}" marker-end="url(#${uid}-ar)"/>`).join('')}
    ${G.nodes.map(([x, y], i) => `<g class="apa-sso__node" data-node="${i}"><rect x="${x - G.w / 2}" y="${y - G.h / 2}" width="${G.w}" height="${G.h}" rx="12"/><text x="${x}" y="${y - 2}" text-anchor="middle">${esc(names[i][0])}</text><text class="sub" x="${x}" y="${y + 14}" text-anchor="middle">${names[i][1]}</text></g>`).join('')}
    <circle class="apa-sso__pkt" r="5" cx="0" cy="0"/>
    <text class="apa-sso__pktl" x="0" y="0"></text>
  </svg>`;
}
function renderDetail(animate) {
  const o = byId(S.sel); if (!o) { card.innerHTML = ''; return; }
  const when = (S.recent.find(([id]) => id === o.id) || [])[1];
  const steps = (o.proto === 'SAML' ? SAML_STEPS : OIDC_STEPS)(o);
  card.innerHTML = `
    <div class="apa-sso__head" style="--i:0"><span class="apa-sso__mark apa-sso__mark--lg">${markSVG(o.name)}</span>
      <div><p class="apa-sso__eyebrow">${when ? `Used on this device ${esc(when)}` : 'In the Corvane directory'}</p><h2 class="apa-sso__name">${esc(o.name)}</h2>
      <p class="apa-sso__domains">${o.domains.map((d) => `<span>${CHECK}${esc(d)}</span>`).join('')}</p>
      ${o.note ? `<span class="apa-sso__warn"><svg viewBox="0 0 24 24"><path d="M12 4 2.5 20h19z"/><path d="M12 10v4M12 17v.5"/></svg>${esc(o.note)}</span>` : ''}</div></div>
    <dl class="apa-sso__facts" style="--i:1">
      <div><dt>Identity provider</dt><dd>${esc(o.idp)}</dd></div><div><dt>Protocol</dt><dd>${o.proto === 'SAML' ? 'SAML 2.0' : 'OpenID Connect'}</dd></div>
      <div><dt>Members</dt><dd>${nf.format(o.members)}</dd></div><div><dt>Session</dt><dd>${o.hours} hours</dd></div></dl>
    <figure class="apa-sso__flow" style="--i:2">${flowSVG(o)}</figure>
    <ol class="apa-sso__steps" style="--i:3">${steps.map((s) => `<li><span>${esc(s)}</span><small></small></li>`).join('')}</ol>
    <div class="apa-sso__cta" style="--i:4"></div>`;
  card.classList.toggle('is-swap', !!animate && !reduce);
  renderCTA();
}
function renderCTA() {
  const o = byId(S.sel), cta = card.querySelector('.apa-sso__cta'); if (!cta) return;
  root.dataset.phase = S.phase;
  if (S.phase === 'idle') cta.innerHTML = `<button type="button" class="apa-sso__go" data-act="go">Continue to ${esc(o.idp)} <kbd>↵</kbd></button><p class="apa-sso__note">You’ll come straight back here. Corvane never sees your ${esc(o.name.split(' ')[0])} password.</p>`;
  else if (S.phase === 'run') cta.innerHTML = `<button type="button" class="apa-sso__ghost" data-act="cancel">Cancel <kbd>Esc</kbd></button><p class="apa-sso__note">Handing off to <b>${esc(o.idp)}</b>…</p>`;
  else if (S.phase === 'fail') cta.innerHTML = `<button type="button" class="apa-sso__go" data-act="go">Try again <kbd>↵</kbd></button><p class="apa-sso__note"><b>No smart card detected.</b> Insert your ${esc(o.name.split(' ')[0])} card, then try again.</p>`;
  else {
    const ends = new Date(Date.now() + o.hours * 3600000).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    cta.innerHTML = `<div class="apa-sso__done"><i>✓</i><b>Signed in to ${esc(o.name)}</b><span>dana@${esc(o.domains[0])} · session ends at ${ends}</span></div><button type="button" class="apa-sso__ghost" data-act="switch">Switch organisation</button>`;
  }
}
function select(id, focusDetail) {
  if (S.phase === 'run') cancel(true);
  const changed = id !== S.sel;
  S.sel = id; S.phase = 'idle'; S.attempt = 0;
  $$('.apa-sso__opt').forEach((li) => li.setAttribute('aria-selected', String(li.dataset.id === id)));
  if (changed || !card.innerHTML) renderDetail(true); else renderCTA();
  if (narrow()) { S.pane = 'detail'; root.dataset.pane = 'detail'; }
  if (focusDetail) later(() => { const b = card.querySelector('.apa-sso__go'); if (b) b.focus({ preventScroll: true }); }, 30);
}

/* ---------- the handoff ---------- */
const STEP_MS = [700, 800, 1300, 800, 700];
function hop(i, label) {
  const lane = card.querySelector(`[data-hop="${i}"]`), pkt = card.querySelector('.apa-sso__pkt'), lbl = card.querySelector('.apa-sso__pktl');
  if (!lane) return;
  const h = G.hops[i], [lx, ly, anchor] = G.lbl(h, i);
  lbl.textContent = label; lbl.setAttribute('text-anchor', anchor);
  if (reduce) { lane.setAttribute('data-done', ''); return; }
  pkt.animate([{ transform: `translate(${h[0]}px, ${h[1]}px)`, opacity: 0 }, { opacity: 1, offset: 0.15 }, { opacity: 1, offset: 0.85 }, { transform: `translate(${h[2]}px, ${h[3]}px)`, opacity: 0 }], { duration: 640, easing: 'cubic-bezier(.45,0,.25,1)', fill: 'forwards' });
  lbl.animate([{ transform: `translate(${lx}px, ${ly}px)`, opacity: 0 }, { opacity: 1, offset: 0.2 }, { opacity: 1, offset: 0.8 }, { transform: `translate(${lx}px, ${ly}px)`, opacity: 0 }], { duration: 700, fill: 'forwards' });
  later(() => lane.setAttribute('data-done', ''), 500);
}
function go() {
  if (S.phase === 'run') return;
  const o = byId(S.sel);
  if (S.phase === 'done') return;
  S.attempt++; S.phase = 'run'; const run = ++S.run;
  renderDetail(false);
  const lis = $$('.apa-sso__steps li'), nodes = $$('.apa-sso__node');
  const labels = LABELS[o.proto];
  const fail = o.note === 'Smart card required' && S.attempt === 1;
  const t0 = performance.now();
  const stamp = (li) => { li.querySelector('small').textContent = `${Math.round(performance.now() - t0)} ms`; };
  const step = (i) => {
    if (run !== S.run) return;
    if (i > 0) { lis[i - 1].dataset.s = 'ok'; stamp(lis[i - 1]); }
    if (i === 5) {
      nodes[0].removeAttribute('data-on'); nodes[0].setAttribute('data-ok', '');
      S.phase = 'done';
      S.recent = [[o.id, 'just now']].concat(S.recent.filter(([id]) => id !== o.id));
      const eb = card.querySelector('.apa-sso__eyebrow'); if (eb) eb.textContent = 'Used on this device just now';
      renderCTA(); renderList(true);
      const sw = card.querySelector('[data-act="switch"]'); if (sw) sw.focus({ preventScroll: true });
      return;
    }
    lis[i].dataset.s = 'run';
    nodes.forEach((n) => n.removeAttribute('data-on'));
    if (i === 0) { nodes[0].setAttribute('data-on', ''); hop(0, labels[0]); }
    if (i === 1) { nodes[1].setAttribute('data-on', ''); hop(1, labels[1]); }
    if (i === 2) {
      nodes[2].setAttribute('data-on', ''); nodes[2].setAttribute('data-wait', '');
      if (fail) {
        later(() => {
          if (run !== S.run) return;
          nodes[2].removeAttribute('data-wait'); nodes[2].removeAttribute('data-on'); nodes[2].setAttribute('data-bad', '');
          lis[2].dataset.s = 'bad'; lis[2].querySelector('span').textContent = `${o.idp} couldn’t find a smart card`; stamp(lis[2]);
          S.phase = 'fail'; renderCTA(); const b = card.querySelector('[data-act="go"]'); if (b) b.focus({ preventScroll: true });
        }, reduce ? 300 : 1500);
        return;
      }
      later(() => { nodes[2].removeAttribute('data-wait'); }, STEP_MS[2] - 100);
    }
    if (i === 3) { nodes[2].setAttribute('data-ok', ''); nodes[1].setAttribute('data-on', ''); hop(2, labels[2]); }
    if (i === 4) { nodes[0].setAttribute('data-on', ''); hop(3, labels[3]); }
    later(() => step(i + 1), reduce ? 250 : STEP_MS[i]);
  };
  later(() => { renderCTA(); const c = card.querySelector('[data-act="cancel"]'); if (c && root.contains(document.activeElement)) c.focus({ preventScroll: true }); step(0); }, 30);
}
function cancel(silent) {
  if (S.phase !== 'run') return;
  S.run++; S.phase = 'idle'; renderDetail(false);
  if (!silent) toast('Sign-in cancelled — nothing was sent');
}

/* ---------- forget + undo ---------- */
let toastT = 0;
function toast(msg, undoable) {
  const t = $('.apa-sso__toast'); t.querySelector('span').textContent = msg; t.querySelector('button').hidden = !undoable; t.hidden = false;
  clearTimeout(toastT); toastT = later(() => { t.hidden = true; S.undo = null; }, 5000);
}
function forget(id) {
  const i = S.recent.findIndex(([x]) => x === id); if (i < 0) return;
  const row = $(`.apa-sso__opt[data-id="${id}"]`);
  const done = () => {
    S.undo = { entry: S.recent[i], at: i };
    S.recent.splice(i, 1); renderList(true);
    toast(`${byId(id).name} forgotten on this device`, true);
  };
  if (row && !reduce) row.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(-16px)' }], { duration: 200, easing: 'ease-in' }).onfinish = () => { if (root.isConnected) done(); };
  else done();
}
function undoForget() { if (!S.undo) return; S.recent.splice(S.undo.at, 0, S.undo.entry); S.undo = null; $('.apa-sso__toast').hidden = true; renderList(true); }

/* ---------- events ---------- */
input.addEventListener('input', () => { S.q = input.value; S.active = 0; renderList(true); });
listEl.addEventListener('pointerdown', (e) => { if (e.target.closest('.apa-sso__opt')) e.preventDefault(); });
root.addEventListener('click', (e) => {
  const f = e.target.closest('[data-forget]'); if (f) { e.stopPropagation(); forget(f.dataset.forget); return; }
  const opt = e.target.closest('.apa-sso__opt');
  if (opt) { S.active = S.opts.indexOf(opt.dataset.id); select(opt.dataset.id, true); $$('.apa-sso__opt').forEach((li, i) => li.toggleAttribute('data-active', i === S.active)); return; }
  const a = e.target.closest('[data-act]'); if (!a) return;
  switch (a.dataset.act) {
    case 'go': go(); break;
    case 'cancel': cancel(); break;
    case 'switch': S.phase = 'idle'; renderDetail(false); if (narrow()) { S.pane = 'list'; root.dataset.pane = 'list'; } input.focus(); break;
    case 'back': S.pane = 'list'; root.dataset.pane = 'list'; input.focus(); break;
    case 'undo': undoForget(); break;
  }
});
root.addEventListener('keydown', (e) => {
  const t = e.target, inInput = t === input;
  if (e.key === 'Escape') {
    if (S.phase === 'run') { e.preventDefault(); cancel(); return; }
    if (narrow() && S.pane === 'detail') { e.preventDefault(); S.pane = 'list'; root.dataset.pane = 'list'; input.focus(); return; }
    if (inInput && input.value) { e.preventDefault(); input.value = ''; S.q = ''; renderList(); return; }
    return;
  }
  if (e.key === '/' && !inInput && !e.metaKey && !e.ctrlKey) { e.preventDefault(); if (narrow()) { S.pane = 'list'; root.dataset.pane = 'list'; } input.focus(); input.select(); return; }
  if (inInput && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) { e.preventDefault(); moveActive(e.key === 'ArrowDown' ? 1 : -1); return; }
  if (inInput && e.key === 'Enter') { e.preventDefault(); const id = S.opts[S.active]; if (id) select(id, true); return; }
  if (inInput && e.key === 'Delete' && !input.value) { const id = S.opts[S.active]; if (id) { e.preventDefault(); forget(id); } }
});

renderList(); renderDetail(false);

