/* Onboarding questionnaire. Re-theme with --apa-onboard-paper, -ink and -accent (the accent also follows the colour answer). */
@property --apa-onboard-accent { syntax: "<color>"; inherits: true; initial-value: oklch(0.55 0.13 150); }
@property --apa-onboard-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.apa-onboard {
  --apa-onboard-paper: oklch(0.978 0.005 95);
  --apa-onboard-ink: oklch(0.21 0.016 255);
  --apa-onboard-accent: oklch(0.55 0.13 150);

  --apa-onboard-card: oklch(0.997 0.002 95);
  --apa-onboard-tint: color-mix(in oklch, var(--apa-onboard-accent) 10%, var(--apa-onboard-card));
  --apa-onboard-muted: color-mix(in oklch, var(--apa-onboard-ink) 60%, var(--apa-onboard-paper));
  --apa-onboard-faint: color-mix(in oklch, var(--apa-onboard-ink) 40%, var(--apa-onboard-paper));
  --apa-onboard-rule: color-mix(in oklch, var(--apa-onboard-ink) 10%, transparent);
  --apa-onboard-rule2: color-mix(in oklch, var(--apa-onboard-ink) 19%, transparent);
  --apa-onboard-ease: cubic-bezier(.2, .85, .25, 1);
  --apa-onboard-spring: linear(0, 0.08 4%, 0.3 9%, 0.7 16%, 0.96 23%, 1.07 29%, 1.09 35%, 1.05 43%, 1.01 54%, 0.995 68%, 1);

  position: relative;
  isolation: isolate;
  width: 100%;
  height: var(--apa-onboard-h, 680px);
  container-type: inline-size;
  overflow: hidden;
  overflow: clip;
  border-radius: 18px;
  background: var(--apa-onboard-paper);
  color: var(--apa-onboard-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  color-scheme: light;
  accent-color: var(--apa-onboard-accent);
  outline: none;
  transition: --apa-onboard-accent .7s var(--apa-onboard-ease);
}
:where(.apa-onboard) *, :where(.apa-onboard) *::before, :where(.apa-onboard) *::after { box-sizing: border-box; }
:where(.apa-onboard) :is(button, input) { font: inherit; color: inherit; }
:where(.apa-onboard) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.apa-onboard) :is(p, h2, ul, ol) { margin: 0; padding: 0; }
:where(.apa-onboard) :is(ul, ol) { list-style: none; }
:where(.apa-onboard) svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
:where(.apa-onboard) :focus-visible { outline: 2px solid var(--apa-onboard-accent); outline-offset: 2px; }
:where(.apa-onboard) kbd {
  display: inline-grid; place-items: center; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 5px;
  font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: inherit;
  background: color-mix(in oklch, currentColor 10%, transparent); box-shadow: inset 0 -1px 0 color-mix(in oklch, currentColor 16%, transparent);
}
.apa-onboard [hidden] { display: none !important; }

/* ---------- shell ---------- */
.apa-onboard__app { display: grid; height: 100%; grid-template: "q pv" minmax(0, 1fr) / minmax(0, 1fr) minmax(0, 1.05fr); }
.apa-onboard__tabs { display: none; }
.apa-onboard__q { grid-area: q; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.apa-onboard__pv {
  grid-area: pv; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 12px; min-height: 0; min-width: 0; padding: 18px 20px 16px; margin: 10px 10px 10px 0; border-radius: 14px;
  background: radial-gradient(circle at 1px 1px, var(--apa-onboard-rule2) 1px, transparent 1.4px) 0 0 / 16px 16px, color-mix(in oklch, var(--apa-onboard-accent) 7%, var(--apa-onboard-paper));
  box-shadow: inset 0 0 0 1px var(--apa-onboard-rule);
}

/* ---------- question pane ---------- */
.apa-onboard__top { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 16px; padding: 20px clamp(18px, 3.4cqi, 40px) 0; }
.apa-onboard__brand { display: inline-flex; align-items: center; gap: 8px; font-weight: 800; font-size: 15.5px; letter-spacing: -.02em; }
.apa-onboard__brand svg { width: 22px; height: 22px; color: var(--apa-onboard-accent); stroke-width: 2; }
.apa-onboard__prog { height: 4px; border-radius: 4px; background: var(--apa-onboard-rule); overflow: hidden; }
.apa-onboard__prog i { display: block; height: 100%; border-radius: inherit; background: var(--apa-onboard-accent); transform-origin: 0 50%; scale: var(--apa-onboard-p) 1; transition: --apa-onboard-p .7s var(--apa-onboard-spring); }
.apa-onboard__count { font: 600 11.5px/1 ui-monospace, Menlo, monospace; color: var(--apa-onboard-muted); font-variant-numeric: tabular-nums; }

.apa-onboard__stage { min-height: 0; overflow: auto; padding: 22px clamp(18px, 3.4cqi, 40px) 16px; display: grid; align-content: safe center; scrollbar-width: thin; overscroll-behavior: contain; }
.apa-onboard__qwrap { display: grid; max-width: 500px; }
.apa-onboard__qnum { display: inline-flex; align-items: center; gap: 6px; font: 700 12px/1 ui-monospace, Menlo, monospace; color: var(--apa-onboard-accent); }
.apa-onboard__qnum svg { width: 14px; height: 14px; stroke-width: 2.2; }
.apa-onboard__qh { margin-top: 10px; font-size: clamp(23px, 0.9rem + 1.6cqi, 31px); line-height: 1.1; font-weight: 740; letter-spacing: -.032em; text-wrap: balance; outline: none; }
.apa-onboard__qsub { margin-top: 8px; color: var(--apa-onboard-muted); text-wrap: pretty; }
.apa-onboard__opts { display: grid; gap: 7px; margin-top: 20px; }
.apa-onboard__opts--2 { grid-template-columns: 1fr 1fr; }
.apa-onboard__opt {
  position: relative; display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; min-height: 44px; padding: 8px 12px 8px 9px; border-radius: 10px; text-align: left;
  background: var(--apa-onboard-card); box-shadow: inset 0 0 0 1px var(--apa-onboard-rule2);
  transition: box-shadow .2s, background-color .25s, translate .3s var(--apa-onboard-spring);
  animation: apa-onboard-rise .45s var(--apa-onboard-ease) both; animation-delay: calc(60ms + var(--i) * 35ms);
}
.apa-onboard__opt:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-onboard-accent) 55%, transparent); }
.apa-onboard__opt:active { translate: 0 1px; }
.apa-onboard__opt kbd { min-width: 24px; height: 24px; font-size: 11.5px; background: var(--apa-onboard-card); box-shadow: inset 0 0 0 1px var(--apa-onboard-rule2); transition: background-color .25s, color .25s, box-shadow .25s; }
.apa-onboard__opt > span { font-weight: 560; }
.apa-onboard__opt small { display: block; font-size: 12px; font-weight: 400; color: var(--apa-onboard-muted); }
.apa-onboard__opt b.apa-onboard__ord { display: grid; place-items: center; min-width: 22px; height: 22px; border-radius: 50%; font-size: 11.5px; background: var(--apa-onboard-accent); color: white; scale: 0; transition: scale .4s var(--apa-onboard-spring); }
.apa-onboard__opt[aria-checked="true"] { background: var(--apa-onboard-tint); box-shadow: inset 0 0 0 1.5px var(--apa-onboard-accent); }
.apa-onboard__opt[aria-checked="true"] kbd { background: var(--apa-onboard-accent); color: white; box-shadow: none; }
.apa-onboard__opt[aria-checked="true"] b.apa-onboard__ord { scale: 1; }
.apa-onboard__opt.is-blip { animation: apa-onboard-blip .35s var(--apa-onboard-ease); }
.apa-onboard__sw { width: 22px; height: 22px; border-radius: 50%; background: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, black 12%, transparent); }
.apa-onboard__msg { min-height: 1.4em; margin-top: 10px; font-size: 12.5px; color: oklch(0.52 0.17 30); }
.apa-onboard__text { margin-top: 20px; display: grid; gap: 8px; }
.apa-onboard__text input, .apa-onboard__chipbox {
  width: 100%; min-height: 50px; padding: 0 14px; border-radius: 11px; border: 1.5px solid var(--apa-onboard-rule2); background: var(--apa-onboard-card); font-size: 18px; font-weight: 560; outline: none;
  transition: border-color .2s, box-shadow .25s var(--apa-onboard-ease);
}
.apa-onboard__text input:focus, .apa-onboard__chipbox:focus-within { border-color: var(--apa-onboard-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--apa-onboard-accent) 16%, transparent); }
.apa-onboard__slug { font: 500 12.5px/1.4 ui-monospace, Menlo, monospace; color: var(--apa-onboard-muted); overflow-wrap: anywhere; }
.apa-onboard__slug b { color: var(--apa-onboard-accent); font-weight: 650; }
.apa-onboard__sugs { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.apa-onboard__sug { height: 30px; padding: 0 11px; border-radius: 99px; font-size: 12.5px; font-weight: 560; background: color-mix(in oklch, var(--apa-onboard-ink) 5%, transparent); transition: background-color .2s; animation: apa-onboard-rise .4s var(--apa-onboard-ease) both; animation-delay: calc(var(--i) * 40ms); }
.apa-onboard__sug:hover { background: var(--apa-onboard-tint); }
.apa-onboard__chipbox { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 8px 10px; font-size: 15px; cursor: text; }
.apa-onboard__chipbox input { flex: 1; min-width: 160px; height: 32px; border: 0; outline: none; background: none; font-size: 15px; font-weight: 500; padding: 0 4px; }
.apa-onboard__chip { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 4px 0 4px; border-radius: 99px; background: var(--apa-onboard-tint); font-size: 13px; font-weight: 560; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apa-onboard-accent) 30%, transparent); transition: opacity .25s, scale .35s var(--apa-onboard-spring); }
@starting-style { .apa-onboard__chip { opacity: 0; scale: .7; } }
.apa-onboard__chip i { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--apa-onboard-accent); color: white; font-style: normal; font-size: 10px; font-weight: 750; }
.apa-onboard__chip button { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; color: var(--apa-onboard-muted); }
.apa-onboard__chip button:hover { background: color-mix(in oklch, var(--apa-onboard-ink) 8%, transparent); color: var(--apa-onboard-ink); }
.apa-onboard__chip button svg { width: 12px; height: 12px; stroke-width: 2.4; }

/* building + done */
.apa-onboard__build { display: grid; gap: 4px; margin-top: 20px; }
.apa-onboard__build li { display: flex; align-items: center; gap: 12px; padding: 7px 0; color: var(--apa-onboard-faint); transition: color .3s; }
.apa-onboard__build li i { position: relative; width: 20px; height: 20px; border-radius: 50%; flex: none; box-shadow: inset 0 0 0 1.5px var(--apa-onboard-rule2); transition: background-color .3s, box-shadow .3s; }
.apa-onboard__build li i::after { content: ""; position: absolute; left: 7px; top: 4.5px; width: 4.5px; height: 8px; border: solid white; border-width: 0 2px 2px 0; rotate: 45deg; scale: 0; transition: scale .4s var(--apa-onboard-spring); }
.apa-onboard__build li[data-s="run"] { color: var(--apa-onboard-ink); }
.apa-onboard__build li[data-s="run"] i { box-shadow: inset 0 0 0 2px var(--apa-onboard-accent); animation: apa-onboard-spin 0.9s linear infinite; background: conic-gradient(var(--apa-onboard-accent) 0 25%, transparent 0); }
.apa-onboard__build li[data-s="ok"] { color: var(--apa-onboard-ink); }
.apa-onboard__build li[data-s="ok"] i { background: var(--apa-onboard-accent); box-shadow: none; }
.apa-onboard__build li[data-s="ok"] i::after { scale: 1; }
.apa-onboard__sum { display: grid; grid-template-columns: auto 1fr; gap: 6px 16px; margin-top: 18px; padding: 14px 16px; border-radius: 12px; background: var(--apa-onboard-card); box-shadow: inset 0 0 0 1px var(--apa-onboard-rule); font-size: 13px; }
.apa-onboard__sum dt { color: var(--apa-onboard-muted); }
.apa-onboard__sum dd { margin: 0; font-weight: 600; }

/* footer */
.apa-onboard__foot { display: flex; align-items: center; gap: 12px; padding: 12px clamp(18px, 3.4cqi, 40px) 18px; }
.apa-onboard__back { display: inline-flex; align-items: center; gap: 4px; height: 40px; padding: 0 12px 0 8px; border-radius: 10px; font-weight: 600; color: var(--apa-onboard-muted); transition: background-color .2s, color .2s; }
.apa-onboard__back:hover { background: var(--apa-onboard-rule); color: var(--apa-onboard-ink); }
.apa-onboard__back:disabled { visibility: hidden; }
.apa-onboard__hint { flex: 1; display: flex; justify-content: center; flex-wrap: wrap; align-items: center; gap: 4px; font-size: 11.5px; color: var(--apa-onboard-faint); }
.apa-onboard__hint i { font-style: normal; margin-right: 8px; }
.apa-onboard__ok {
  margin-left: auto; display: inline-flex; align-items: center; gap: 10px; height: 44px; padding: 0 16px 0 20px; border-radius: 11px;
  background: var(--apa-onboard-accent); color: white; font-weight: 700; font-size: 14.5px;
  box-shadow: 0 12px 24px -14px var(--apa-onboard-accent); transition: scale .3s var(--apa-onboard-spring), filter .2s, opacity .2s;
}
.apa-onboard__ok:hover { filter: brightness(1.07); }
.apa-onboard__ok:active { scale: .97; }
.apa-onboard__ok kbd { background: color-mix(in oklch, white 22%, transparent); box-shadow: none; }
.apa-onboard[data-phase="build"] .apa-onboard__ok { opacity: .5; pointer-events: none; }

/* ---------- preview window ---------- */
.apa-onboard__pvlabel { display: flex; align-items: center; gap: 8px; font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em; text-transform: uppercase; color: var(--apa-onboard-muted); }
.apa-onboard__pvlabel i { width: 7px; height: 7px; border-radius: 50%; background: var(--apa-onboard-accent); box-shadow: 0 0 0 0 color-mix(in oklch, var(--apa-onboard-accent) 50%, transparent); animation: apa-onboard-beat 2.2s ease-out infinite; }
.apa-onboard__pvlabel span { margin-left: auto; letter-spacing: .02em; text-transform: none; font-weight: 500; }
.apa-onboard__pvnote { font-size: 12px; color: var(--apa-onboard-muted); text-align: center; }
.apa-onboard__win {
  position: relative; display: grid; grid-template-columns: 158px minmax(0, 1fr); min-height: 0; overflow: hidden; border-radius: 12px;
  background: var(--apa-onboard-card); box-shadow: 0 0 0 1px var(--apa-onboard-rule2), 0 30px 50px -34px color-mix(in oklch, var(--apa-onboard-ink) 60%, transparent);
  font-size: 12px;
}
.apa-onboard__wside { display: grid; grid-template-rows: auto auto auto 1fr; align-content: start; gap: 6px; padding: 12px 10px; background: color-mix(in oklch, var(--apa-onboard-ink) 3.5%, var(--apa-onboard-card)); border-right: 1px solid var(--apa-onboard-rule); min-width: 0; }
.apa-onboard__wsh { display: flex; align-items: center; gap: 8px; padding: 2px 4px 8px; min-width: 0; }
.apa-onboard__wsh b { font-size: 12.5px; font-weight: 720; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.apa-onboard__wsi { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 7px; flex: none; background: var(--apa-onboard-accent); color: white; font-weight: 800; font-size: 11.5px; }
.apa-onboard__nav { display: grid; gap: 2px; }
.apa-onboard__nav li { display: flex; align-items: center; gap: 8px; height: 28px; padding: 0 6px; border-radius: 7px; color: var(--apa-onboard-muted); white-space: nowrap; overflow: hidden; transition: opacity .35s, translate .45s var(--apa-onboard-spring), background-color .25s; }
@starting-style { .apa-onboard__nav li { opacity: 0; translate: -10px 0; } }
.apa-onboard__nav li svg { width: 15px; height: 15px; }
.apa-onboard__nav li.is-home { background: var(--apa-onboard-tint); color: var(--apa-onboard-ink); font-weight: 620; }
.apa-onboard__nav li.is-home svg { color: var(--apa-onboard-accent); }
.apa-onboard__nav li.is-ghost { opacity: .35; }
.apa-onboard__nav li.is-ghost i { display: block; height: 7px; flex: 1; border-radius: 4px; background: var(--apa-onboard-rule2); }
.apa-onboard__wsec { margin-top: 10px; padding: 0 6px; font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apa-onboard-faint); }
.apa-onboard__people { display: flex; flex-wrap: wrap; gap: 4px; padding: 0 6px; align-content: start; }
.apa-onboard__people span { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: var(--c, var(--apa-onboard-accent)); color: white; font-size: 9.5px; font-weight: 750; transition: opacity .3s, scale .45s var(--apa-onboard-spring); }
@starting-style { .apa-onboard__people span { opacity: 0; scale: .4; } }
.apa-onboard__people span.is-more { background: var(--apa-onboard-rule); color: var(--apa-onboard-muted); width: auto; padding: 0 7px; border-radius: 12px; }
.apa-onboard__wmain { display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; }
.apa-onboard__wbar { display: flex; align-items: center; gap: 8px; padding: 12px 14px 10px; border-bottom: 1px solid var(--apa-onboard-rule); min-width: 0; }
.apa-onboard__wbar b { font-size: 14px; font-weight: 750; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.apa-onboard__pill { padding: 3px 8px; border-radius: 6px; font-size: 10.5px; font-weight: 650; white-space: nowrap; background: var(--apa-onboard-tint); color: color-mix(in oklch, var(--apa-onboard-accent) 70%, var(--apa-onboard-ink)); }
.apa-onboard__team { margin-left: auto; font-size: 11px; color: var(--apa-onboard-faint); white-space: nowrap; }
.apa-onboard__board { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(118px, 1fr); gap: 8px; padding: 12px; min-height: 0; overflow: auto hidden; overscroll-behavior-x: contain; scrollbar-width: thin; }
.apa-onboard__col { display: grid; align-content: start; gap: 6px; min-width: 0; padding: 8px; border-radius: 9px; background: color-mix(in oklch, var(--apa-onboard-ink) 3%, var(--apa-onboard-card)); transition: opacity .35s, translate .5s var(--apa-onboard-ease); }
@starting-style { .apa-onboard__col { opacity: 0; translate: 0 12px; } }
.apa-onboard__col > b { display: flex; justify-content: space-between; font-size: 10.5px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; color: var(--apa-onboard-muted); padding: 0 2px 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; gap: 6px; }
.apa-onboard__col > b span { font-variant-numeric: tabular-nums; color: var(--apa-onboard-faint); }
.apa-onboard__card { display: grid; gap: 6px; min-width: 0; overflow-wrap: break-word; padding: 8px 9px; border-radius: 7px; background: var(--apa-onboard-card); box-shadow: 0 0 0 1px var(--apa-onboard-rule), 0 2px 3px -2px var(--apa-onboard-rule2); font-size: 11.5px; line-height: 1.3; font-weight: 520; text-wrap: pretty; transition: opacity .35s, translate .5s var(--apa-onboard-spring); }
@starting-style { .apa-onboard__card { opacity: 0; translate: 0 8px; } }
.apa-onboard__card.is-ghost { box-shadow: none; background: color-mix(in oklch, var(--apa-onboard-ink) 5%, transparent); }
.apa-onboard__card.is-ghost i { display: block; height: 6px; border-radius: 3px; background: var(--apa-onboard-rule2); }
.apa-onboard__card.is-ghost i + i { width: 60%; }
.apa-onboard__meta { display: flex; align-items: center; gap: 6px; min-width: 0; }
.apa-onboard__tag { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 1px 6px; border-radius: 4px; font-size: 9.5px; font-weight: 700; background: var(--apa-onboard-tint); color: color-mix(in oklch, var(--apa-onboard-accent) 70%, var(--apa-onboard-ink)); }
.apa-onboard__who { margin-left: auto; flex: none; display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; background: var(--c); color: white; font-size: 8px; font-weight: 750; }
.apa-onboard__ready {
  position: absolute; left: 50%; bottom: 14px; translate: -50% 0; display: flex; align-items: baseline; gap: 6px; padding: 9px 14px; border-radius: 10px; white-space: nowrap;
  background: var(--apa-onboard-ink); color: var(--apa-onboard-card); font-size: 12px; box-shadow: 0 14px 28px -12px var(--apa-onboard-ink);
  opacity: 0; scale: .9; pointer-events: none; transition: opacity .35s, scale .5s var(--apa-onboard-spring);
}
.apa-onboard[data-phase="done"] .apa-onboard__ready { opacity: 1; scale: 1; }
.apa-onboard__win.is-pulse { animation: apa-onboard-pulse .9s var(--apa-onboard-ease); }

/* ---------- keyframes ---------- */
@keyframes apa-onboard-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes apa-onboard-blip { 40% { translate: 4px 0; } 70% { translate: -3px 0; } }
@keyframes apa-onboard-beat { 70%, 100% { box-shadow: 0 0 0 7px transparent; } }
@keyframes apa-onboard-spin { to { rotate: 360deg; } }
@keyframes apa-onboard-pulse { 30% { box-shadow: 0 0 0 4px var(--apa-onboard-accent), 0 30px 50px -34px var(--apa-onboard-ink); } }

/* ---------- container: medium ---------- */
@container (min-width: 760px) and (max-width: 959px) {
  .apa-onboard__app { grid-template-columns: minmax(0, 1fr) minmax(0, .9fr); }
  .apa-onboard__win { grid-template-columns: 1fr; }
  .apa-onboard__wside { display: none; }
  .apa-onboard__hint { display: none; }
  .apa-onboard__opts--2 { grid-template-columns: 1fr; }
}
/* ---------- container: single pane with a preview tab ---------- */
@container (max-width: 759px) {
  .apa-onboard__app { grid-template: "tabs" auto "q" minmax(0, 1fr) / minmax(0, 1fr); }
  .apa-onboard__tabs { grid-area: tabs; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 12px 12px 0; padding: 4px; border-radius: 12px; background: var(--apa-onboard-rule); }
  .apa-onboard__tabs button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 34px; border-radius: 9px; font-size: 13px; font-weight: 640; color: var(--apa-onboard-muted); }
  .apa-onboard__tabs button[aria-selected="true"] { background: var(--apa-onboard-card); color: var(--apa-onboard-ink); box-shadow: 0 1px 3px var(--apa-onboard-rule2); }
  .apa-onboard__ping { width: 7px; height: 7px; border-radius: 50%; background: var(--apa-onboard-accent); animation: apa-onboard-beat 1.6s ease-out infinite; }
  .apa-onboard__pv { grid-area: q; margin: 10px; }
  .apa-onboard[data-tab="q"] .apa-onboard__pv, .apa-onboard[data-tab="pv"] .apa-onboard__q { display: none; }
  .apa-onboard__hint { display: none; }
  .apa-onboard__top { padding-top: 14px; }
  .apa-onboard__stage { align-content: start; }
}
@container (max-width: 520px) {
  .apa-onboard__opts--2 { grid-template-columns: 1fr; }
  .apa-onboard__win { grid-template-columns: 1fr; }
  .apa-onboard__wside { display: none; }
  .apa-onboard__board { grid-auto-flow: row; grid-auto-columns: auto; grid-template-columns: 1fr 1fr; overflow: auto; }
  .apa-onboard__brand { font-size: 0; gap: 0; }
  .apa-onboard__ok kbd { display: none; }
}

/* ---------- reduced motion: answers apply instantly ---------- */
@media (prefers-reduced-motion: reduce) {
  .apa-onboard, .apa-onboard *, .apa-onboard *::before, .apa-onboard *::after {
    animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0s !important;
  }
}

