  clients: { label: 'Clients', cols: ['Brief', 'In progress', 'Review', 'Delivered'], cards: [['Fennick rebrand', 'Brand'], ['Quayside app MVP', 'App'], ['Orrin site refresh', 'Web'], ['Lowmoor annual report', 'Print'], ['Saltmarsh field guide', 'Print'], ['Rookwood label system', 'Brand']] },
