const A = { role: null, size: null, use: [], color: null, name: '', invite: [] };
const S = { step: 0, phase: 'ask', tab: 'q', home: null, buildRun: 0 };
const stage = $('.apa-onboard__stage');

/* ---------- question rendering ---------- */
function slug(v) { return v.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 32); }
