      <div class="apa-onboard__sugs">${sugs.map((s, i) => `<button type="button" class="apa-onboard__sug" data-sug="${esc(s)}" style="--i:${i}">${esc(s)}</button>`).join('')}</div></div>`;
  } else {
    body = `<div class="apa-onboard__text"><div class="apa-onboard__chipbox"><span class="apa-onboard__chips"></span><input class="apa-onboard__mail" type="text" inputmode="email" placeholder="name@company.com" aria-label="Add a teammate’s email" autocomplete="off" spellcheck="false"></div></div>`;
  }
