    <p class="apa-onboard__qnum">${S.step + 1}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></p>
    <h2 class="apa-onboard__qh" tabindex="-1">${esc(q.h)}</h2><p class="apa-onboard__qsub">${esc(q.sub)}</p>${body}
