/* ---------- chrome: progress, buttons, hints ---------- */
function chrome() {
  const q = QS[S.step];
  const answered = [A.role, A.size, A.use.length, A.color, A.name.trim().length > 1, S.step > 5 || S.phase !== 'ask'].filter(Boolean).length;
  root.style.setProperty('--apa-onboard-p', S.phase === 'ask' ? (S.step / QS.length).toFixed(3) : 1);
  $('.apa-onboard__prog').setAttribute('aria-valuenow', S.phase === 'ask' ? S.step : 6);
  bind('count', S.phase === 'ask' ? `${S.step + 1} of ${QS.length}` : 'Done');
  const left = Math.max(0, QS.length - S.step) * 10;
  bind('left', S.phase === 'ask' ? `About ${left} s left` : answered ? 'All set' : '');
  $('.apa-onboard__back').disabled = S.phase !== 'ask' ? S.phase !== 'done' : S.step === 0;
  const ok = $('.apa-onboard__okl');
  if (S.phase === 'build') ok.textContent = 'Building…';
  else if (S.phase === 'done') ok.textContent = `Open ${A.name.trim() || 'workspace'}`;
  else if (q.type === 'chips') ok.textContent = A.invite.length ? `Send ${A.invite.length} invite${A.invite.length > 1 ? 's' : ''}` : 'Skip for now';
  else ok.textContent = S.step === QS.length - 1 ? 'Finish' : 'OK';
  $('.apa-onboard__hint').innerHTML = S.phase !== 'ask' ? '' : q.type === 'text' ? '<kbd>↵</kbd><i>OK</i><kbd>⇧</kbd><kbd>↵</kbd> back'
    : q.type === 'chips' ? '<kbd>↵</kbd><i>add</i><kbd>⌫</kbd><i>remove</i><kbd>⇧</kbd><kbd>↵</kbd> back'
    : `<kbd>A</kbd>–<kbd>${LETTERS[q.opts.length - 1]}</kbd><i>${q.type === 'multi' ? 'toggle' : 'choose'}</i><kbd>↑</kbd><kbd>↓</kbd><i>move</i><kbd>↵</kbd> OK`;
}

/* ---------- preview ---------- */
let pvSig = '';
function renderPV() {
