  const name = A.name.trim();
  bind('wsi', name ? initials(name).slice(0, 1) : '?'); bind('wsn', name || 'Your workspace'); bind('readyname', name || 'Your workspace');
  bind('pill', A.role ? `${ROLE[A.role]} defaults` : 'Choose a role');
  bind('team', A.size ? SIZE[A.size] : 'Team size?');
  // nav with FLIP on reorder
  const nav = $('.apa-onboard__nav');
  const before = new Map($$('.apa-onboard__nav li[data-k]').map((li) => [li.dataset.k, li.getBoundingClientRect().top]));
  const items = [['inbox', 'Inbox'], ['mine', 'My work']].concat(A.use.map((u) => [u, TPL[u].label]));
  nav.innerHTML = items.map(([k, l]) => `<li data-k="${k}" class="${k === A.use[0] ? 'is-home' : ''}"><svg viewBox="0 0 24 24">${ICON[k]}</svg>${esc(l)}</li>`).join('')
    + (A.use.length ? '' : '<li class="is-ghost"><i></i></li><li class="is-ghost"><i></i></li>');
  if (!reduce) $$('.apa-onboard__nav li[data-k]').forEach((li) => {
