  $('.apa-onboard__people').innerHTML = people.map(([t, c]) => `<span style="--c:${c}">${esc(t)}</span>`).join('') + (A.size && A.size !== '1' ? `<span class="is-more">${SIZE[A.size].replace('Team of ', '')}</span>` : '');
  // board: only rebuilt when the home board changes
  const home = A.use[0] || null;
