      const who = [['Y', 'var(--apa-onboard-accent)']].concat(A.invite.map((m, i) => [initials(m), WHO[i % WHO.length][1]])).concat(WHO);
      let k = 0;
      board.innerHTML = t.cols.map((c, ci) => `<div class="apa-onboard__col" style="transition-delay:${ci * 50}ms"><b>${esc(c)}<span>${per[ci].length}</span></b>${per[ci].map(([title, tag]) => { const w = who[k++ % who.length]; return `<div class="apa-onboard__card" style="transition-delay:${80 + k * 30}ms">${esc(title)}<span class="apa-onboard__meta"><span class="apa-onboard__tag">${esc(tag)}</span><span class="apa-onboard__who" style="--c:${w[1]}">${esc(w[0])}</span></span></div>`; }).join('')}</div>`).join('');
    }
  }
