}

/* ---------- answering ---------- */
let advanceT = 0;
function choose(v) {
  const q = QS[S.step];
  if (q.type === 'multi') {
    const i = A.use.indexOf(v);
    if (i >= 0) A.use.splice(i, 1);
    else if (A.use.length >= q.max) { msg('Three is the limit — unpick one first.'); blip(stage.querySelector(`[data-v="${v}"]`)); return; }
    else A.use.push(v);
    msg(''); refreshOpts(); renderPV(); chrome();
    return;
  }
  A[q.id] = v; msg(''); refreshOpts(); renderPV(); chrome();
  clearTimeout(advanceT);
  advanceT = later(() => { if (QS[S.step] === q && A[q.id] === v) ok(); }, reduce ? 150 : 420);
}
function addChip(raw) {
  const v = raw.trim().replace(/,$/, '').toLowerCase();
  if (!v) return false;
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) { msg(`“${raw.trim()}” isn’t an email address yet.`); return false; }
  if (A.invite.includes(v)) { msg(`${v} is already on the list.`); return false; }
  if (A.invite.length >= 8) { msg('Eight at a time — you can invite more from settings.'); return false; }
  A.invite.push(v); msg(''); renderChips(); renderPV(); chrome(); return true;
}

function ok() {
  clearTimeout(advanceT);
  if (S.phase === 'build') return;
  if (S.phase === 'done') { const w = $('.apa-onboard__win'); setTab('pv'); w.classList.remove('is-pulse'); void w.offsetWidth; w.classList.add('is-pulse'); return; }
  const q = QS[S.step];
  if (q.type === 'single' && !A[q.id]) { msg('Choose one to continue — or press a letter key.'); blip(stage.querySelector('.apa-onboard__opts')); return; }
  if (q.type === 'multi' && !A.use.length) { msg('Pick at least one so we know what to set up.'); blip(stage.querySelector('.apa-onboard__opts')); return; }
  if (q.type === 'text' && A.name.trim().length < 2) { msg('Give it a name of at least two characters.'); blip($('.apa-onboard__name')); $('.apa-onboard__name').focus(); return; }
  if (q.type === 'chips') { const inp = $('.apa-onboard__mail'); if (inp.value.trim() && !addChip(inp.value)) return; inp.value = ''; }
  if (S.step < QS.length - 1) { S.step++; renderQ(1); } else build();
}
function back() {
  clearTimeout(advanceT);
  if (S.phase === 'done') { S.phase = 'ask'; root.dataset.phase = 'ask'; S.step = QS.length - 1; renderQ(-1); return; }
  if (S.phase !== 'ask' || S.step === 0) return;
  S.step--; renderQ(-1);
}

function build() {
  S.phase = 'build'; root.dataset.phase = 'build'; const run = ++S.buildRun;
  const name = A.name.trim();
  const home = TPL[A.use[0]];
  const lines = [
    `Creating ${name} at loomwork.app/${slug(name)}`,
    `Setting up ${home.label} with ${home.cols.length} columns`,
    A.use.length > 1 ? `Adding ${A.use.slice(1).map((u) => TPL[u].label).join(' and ')}` : 'Adding Inbox and My work views',
    A.invite.length ? `Sending ${A.invite.length} invite${A.invite.length > 1 ? 's' : ''}` : 'Saving a seat for later invites',
    `Tuning defaults for ${ROLE[A.role]}`,
  ];
  stage.innerHTML = `<div class="apa-onboard__qwrap"><p class="apa-onboard__qnum">Almost there</p><h2 class="apa-onboard__qh" tabindex="-1">Building ${esc(name)}…</h2>
    <ol class="apa-onboard__build">${lines.map((l) => `<li><i aria-hidden="true"></i><span>${esc(l)}</span></li>`).join('')}</ol></div>`;
  if (!reduce) stage.firstElementChild.animate([{ opacity: 0, transform: 'translateY(26px)' }, { opacity: 1, transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.2,.85,.25,1)' });
  chrome();
  const lis = $$('.apa-onboard__build li');
  const tick = (i) => {
    if (run !== S.buildRun || S.phase !== 'build') return;
    if (i > 0) lis[i - 1].dataset.s = 'ok';
    if (i === lis.length) { later(() => done(lines), reduce ? 0 : 350); return; }
    lis[i].dataset.s = 'run';
    later(() => tick(i + 1), reduce ? 80 : 520);
  };
  tick(0);
}
function done() {
  S.phase = 'done'; root.dataset.phase = 'done';
  const name = A.name.trim();
  const views = A.use.length + 2;
  $('.apa-onboard__ready span').textContent = `is ready — ${A.use.length} board${A.use.length > 1 ? 's' : ''}, ${views} views, ${A.invite.length} invite${A.invite.length === 1 ? '' : 's'} sent`;
  stage.innerHTML = `<div class="apa-onboard__qwrap"><p class="apa-onboard__qnum">Ready</p><h2 class="apa-onboard__qh" tabindex="-1">${esc(name)} is ready</h2>
    <p class="apa-onboard__qsub">Here’s what we set up. Your home board opens first.</p>
    <dl class="apa-onboard__sum">
      <dt>Address</dt><dd>loomwork.app/${esc(slug(name))}</dd>
      <dt>Home board</dt><dd>${esc(TPL[A.use[0]].label)}</dd>
      <dt>Also</dt><dd>${A.use.length > 1 ? esc(A.use.slice(1).map((u) => TPL[u].label).join(', ')) : 'Inbox, My work'}</dd>
      <dt>Team</dt><dd>${esc(SIZE[A.size])}${A.invite.length ? ` · ${A.invite.length} invited` : ''}</dd>
    </dl>
    <div class="apa-onboard__sugs" style="margin-top:14px"><button type="button" class="apa-onboard__sug" data-act="restart">Start over</button></div></div>`;
  if (!reduce) stage.firstElementChild.animate([{ opacity: 0, transform: 'translateY(20px)' }, { opacity: 1, transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.2,.85,.25,1)' });
  chrome(); $('.apa-onboard__qh').focus({ preventScroll: true });
}
function restart() {
  Object.assign(A, { role: null, size: null, use: [], color: null, name: '', invite: [] });
  S.step = 0; S.phase = 'ask'; root.dataset.phase = 'ask'; pvSig = '';
  renderPV(); renderQ(-1);
}
function setTab(t) {
  S.tab = t; root.dataset.tab = t;
