/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const tab = e.target.closest('.apa-onboard__tabs [role="tab"]'); if (tab) { setTab(tab.dataset.tab); return; }
  const opt = e.target.closest('.apa-onboard__opt'); if (opt) { choose(opt.dataset.v); return; }
  const sug = e.target.closest('[data-sug]'); if (sug) { const i = $('.apa-onboard__name'); i.value = sug.dataset.sug; A.name = i.value; bind('slug', slug(A.name) || 'your-team'); msg(''); renderPV(); chrome(); i.focus(); return; }
  const un = e.target.closest('[data-unchip]'); if (un) { A.invite = A.invite.filter((m) => m !== un.dataset.unchip); renderChips(); renderPV(); chrome(); $('.apa-onboard__mail').focus(); return; }
  if (e.target.closest('.apa-onboard__chipbox')) { $('.apa-onboard__mail').focus(); }
  const a = e.target.closest('[data-act]'); if (!a) return;
  if (a.dataset.act === 'ok') ok(); else if (a.dataset.act === 'back') back(); else if (a.dataset.act === 'restart') restart();
});
root.addEventListener('input', (e) => {
  if (e.target.matches('.apa-onboard__name')) { A.name = e.target.value; bind('slug', slug(A.name) || 'your-team'); msg(''); renderPV(); chrome(); }
  if (e.target.matches('.apa-onboard__mail') && /[,\s]$/.test(e.target.value) && e.target.value.trim()) { if (addChip(e.target.value)) e.target.value = ''; }
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const tab = t.closest && t.closest('.apa-onboard__tabs [role="tab"]');
  if (tab && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) { e.preventDefault(); setTab(S.tab === 'q' ? 'pv' : 'q'); $(`.apa-onboard__tabs [data-tab="${S.tab}"]`).focus(); return; }
  if (e.key === 'Enter') {
    if (tab || (t.closest('button') && !t.closest('.apa-onboard__opt') && !t.matches('.apa-onboard__ok'))) return;
    if (t.matches('.apa-onboard__ok')) return;
    e.preventDefault();
    if (e.shiftKey) { back(); return; }
    if (t.matches('.apa-onboard__mail') && t.value.trim()) { if (addChip(t.value)) t.value = ''; return; }
    ok(); return;
  }
  if (e.key === 'Backspace' && t.matches('.apa-onboard__mail') && !t.value && A.invite.length) { A.invite.pop(); renderChips(); renderPV(); chrome(); return; }
  if (S.phase !== 'ask' || t.matches('input')) return;
  const q = QS[S.step];
  if (!q.opts) return;
  const k = e.key.toUpperCase(), idx = LETTERS.indexOf(k);
  if (k.length === 1 && idx >= 0 && idx < q.opts.length) { e.preventDefault(); choose(q.opts[idx][0]); const b = $$('.apa-onboard__opt')[idx]; if (b) b.focus({ preventScroll: true }); return; }
  if ((e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'ArrowRight') && t.matches('.apa-onboard__opt')) {
    e.preventDefault();
    const bs = $$('.apa-onboard__opt'), i = bs.indexOf(t), d = e.key === 'ArrowDown' || e.key === 'ArrowRight' ? 1 : -1;
    const n = bs[(i + d + bs.length) % bs.length]; bs.forEach((b) => { b.tabIndex = b === n ? 0 : -1; }); n.focus();
    if (q.type === 'single' && q.id === 'color') { A.color = n.dataset.v; refreshOpts(); renderPV(); }
  }
});

renderPV(); renderQ(0);
